(window.__X=window.__X||{})["xword"]={"v":1,"lessons":[{"id":"pos8","en":"The 8 parts of speech","th":"ชนิดของคำทั้ง 8 แบบ","intro":"คำทุกคำในประโยคมีหน้าที่ของมัน รู้ชนิดของคำ (part of speech) แล้วจะรู้ว่าคำนั้นวางตรงไหน และต้องใช้รูปไหน","r":[],"tips":[],"items":[{"id":"wf-pos8-0","p":0,"s":"ในประโยค \"The technician repaired the printer quickly.\" คำว่า quickly เป็นคำชนิดใด?","gap":0,"o":{"A":"noun","B":"adverb","C":"adjective","D":"verb"},"oth":{},"a":"B","x":"quickly บอกว่า repaired \"อย่างไร\" จึงเป็น adverb (ลงท้าย -ly)","v":[]},{"id":"wf-pos8-1","p":0,"s":"ในประโยค \"Our new supplier is reliable.\" คำว่า supplier เป็นคำชนิดใด?","gap":0,"o":{"A":"noun","B":"adjective","C":"adverb","D":"verb"},"oth":{},"a":"A","x":"supplier = ผู้จัดหา เป็นชื่อของคนหรือบริษัท จึงเป็น noun (supply + -er)","v":[]},{"id":"wf-pos8-2","p":0,"s":"คำใดเป็น verb ในประโยค \"They usually inspect every board.\"?","gap":0,"o":{"A":"board","B":"inspect","C":"usually","D":"every"},"oth":{},"a":"B","x":"inspect = ตรวจสอบ เป็นการกระทำของประธาน They","v":[]},{"id":"wf-pos8-3","p":0,"s":"คำใดเป็น adjective ในประโยค \"We need a careful check.\"?","gap":0,"o":{"A":"We","B":"careful","C":"check","D":"need"},"oth":{},"a":"B","x":"careful ขยายคำนาม check และลงท้าย -ful ซึ่งเป็น suffix ของ adjective","v":[]},{"id":"wf-pos8-4","p":0,"s":"คำว่า \"and, but, because\" เป็นคำชนิดใด?","gap":0,"o":{"A":"preposition (บุพบท)","B":"pronoun (สรรพนาม)","C":"conjunction (คำเชื่อม)","D":"adverb"},"oth":{},"a":"C","x":"ทั้งสามคำใช้เชื่อมคำหรือประโยคเข้าด้วยกัน","v":[]},{"id":"wf-pos8-5","p":0,"s":"คำว่า \"in, on, at, under\" เป็นคำชนิดใด?","gap":0,"o":{"A":"verb","B":"conjunction (คำเชื่อม)","C":"preposition (บุพบท)","D":"determiner"},"oth":{},"a":"C","x":"บุพบทบอกตำแหน่งหรือเวลา และตามด้วยคำนาม เช่น in the box","v":[]},{"id":"wf-pos8-6","p":0,"s":"ทุกประโยคที่สมบูรณ์ต้องมีคำชนิดใดเสมอ?","gap":0,"o":{"A":"adjective","B":"adverb","C":"preposition","D":"verb (และประธาน)"},"oth":{},"a":"D","x":"ประโยคต้องมีประธานและกริยาแท้อย่างน้อยอย่างละหนึ่ง","v":[]},{"id":"wf-pos8-7","p":0,"s":"ในประโยค \"It works well.\" คำว่า It เป็นคำชนิดใด?","gap":0,"o":{"A":"adverb","B":"pronoun","C":"noun","D":"conjunction"},"oth":{},"a":"B","x":"It ใช้แทนคำนามที่พูดถึงก่อนหน้า จึงเป็น pronoun","v":[]},{"id":"wf-pos8-8","p":0,"s":"คำว่า \"symptom\" (อาการ) เป็นคำชนิดใด?","gap":0,"o":{"A":"noun (คำนาม)","B":"adverb (คำกริยาวิเศษณ์)","C":"adjective (คำคุณศัพท์)","D":"verb (คำกริยา)"},"oth":{},"a":"A","x":"symptom เป็น noun (คำนาม)","v":[]},{"id":"wf-pos8-9","p":0,"s":"คำว่า \"Tuesday\" (วันอังคาร) เป็นคำชนิดใด?","gap":0,"o":{"A":"verb (คำกริยา)","B":"adjective (คำคุณศัพท์)","C":"noun (คำนาม)","D":"adverb (คำกริยาวิเศษณ์)"},"oth":{},"a":"C","x":"Tuesday เป็น noun (คำนาม)","v":[]},{"id":"wf-pos8-10","p":0,"s":"คำว่า \"propose\" (เสนอ) เป็นคำชนิดใด?","gap":0,"o":{"A":"adjective (คำคุณศัพท์)","B":"verb (คำกริยา)","C":"noun (คำนาม)","D":"adverb (คำกริยาวิเศษณ์)"},"oth":{},"a":"B","x":"propose เป็น verb (คำกริยา)","v":[]},{"id":"wf-pos8-11","p":0,"s":"คำว่า \"country\" (ประเทศ) เป็นคำชนิดใด?","gap":0,"o":{"A":"adverb (คำกริยาวิเศษณ์)","B":"noun (คำนาม)","C":"adjective (คำคุณศัพท์)","D":"verb (คำกริยา)"},"oth":{},"a":"B","x":"country เป็น noun (คำนาม)","v":[]},{"id":"wf-pos8-12","p":0,"s":"คำว่า \"entertain\" (ให้ความบันเทิง) เป็นคำชนิดใด?","gap":0,"o":{"A":"noun (คำนาม)","B":"adjective (คำคุณศัพท์)","C":"verb (คำกริยา)","D":"adverb (คำกริยาวิเศษณ์)"},"oth":{},"a":"C","x":"entertain เป็น verb (คำกริยา)","v":[]},{"id":"wf-pos8-13","p":0,"s":"คำว่า \"maybe\" (อาจจะ) เป็นคำชนิดใด?","gap":0,"o":{"A":"verb (คำกริยา)","B":"noun (คำนาม)","C":"adjective (คำคุณศัพท์)","D":"adverb (คำกริยาวิเศษณ์)"},"oth":{},"a":"D","x":"maybe เป็น adverb (คำกริยาวิเศษณ์)","v":[]}],"grp":"Parts of Speech — ชนิดของคำ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">คิดถึงทีมฟุตบอล: แต่ละคนมีตำแหน่ง คำในประโยคก็เหมือนกัน <b>noun</b> คือผู้เล่น <b>verb</b> คือการเล่น <b>adjective</b> บอกลักษณะผู้เล่น <b>adverb</b> บอกว่าเล่นอย่างไร ถ้ารู้ตำแหน่ง จะรู้ทันทีว่าช่องว่างในข้อสอบต้องการคำชนิดไหน</div><figure class=\"bv bv-blocks\"><div class=\"bv-row\"><span class=\"bv-rl\">ประโยคเดียวมีหลายชนิดคำ</span><div class=\"bv-chips\"><span class=\"bv-chip r-X\"><b>The</b></span><span class=\"bv-chip r-A\"><b>new</b><i>คำขยาย</i></span><span class=\"bv-chip r-S\"><b>engineer</b><i>ประธาน</i></span><span class=\"bv-chip r-ADV\"><b>carefully</b><i>adverb</i></span><span class=\"bv-chip r-V\"><b>tested</b><i>กริยา</i></span><span class=\"bv-chip r-X\"><b>the</b></span><span class=\"bv-chip r-O\"><b>circuit</b><i>กรรม</i></span><span class=\"bv-chip r-P\"><b>in</b><i>สถานที่</i></span><span class=\"bv-chip r-P\"><b>the lab</b><i>สถานที่</i></span></div></div><figcaption>ป้ายใต้คำบอกหน้าที่: คำนามเป็นประธานหรือกรรม คำขยายอยู่หน้าคำนาม adverb ขยายกริยา</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ชนิด</th><th>ตอบคำถาม</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>noun</td><td>ใคร / อะไร</td><td>engineer, quality, factory</td></tr><tr><td>verb</td><td>ทำอะไร / เป็นอะไร</td><td>check, send, is</td></tr><tr><td>adjective</td><td>แบบไหน</td><td>new, careful, electric</td></tr><tr><td>adverb</td><td>อย่างไร / เมื่อไร / บ่อยแค่ไหน</td><td>quickly, today, often</td></tr><tr><td>pronoun</td><td>แทนคำนาม</td><td>he, it, they</td></tr><tr><td>preposition</td><td>ที่ไหน / เมื่อไร (+ คำนาม)</td><td>in, on, at, under</td></tr><tr><td>conjunction</td><td>เชื่อม</td><td>and, but, because</td></tr><tr><td>interjection</td><td>อุทาน</td><td>Oh!, Wow!</td></tr></tbody></table></div><figcaption>ถามคำถามในช่องกลาง แล้วจะรู้ชนิดของคำ</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ประโยคพื้นฐาน</div><div class=\"tf-value\">noun/pronoun + verb + noun</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ขยายคำนาม</div><div class=\"tf-value\">adjective + noun</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ขยายกริยา</div><div class=\"tf-value\">verb + adverb</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>noun (n.) คำนาม</b> — ชื่อคน สัตว์ สิ่งของ สถานที่ ความคิด<br><span class=\"bv-rx\">The <b>engineer</b> checked the <b>machine</b>. <small>วิศวกรตรวจเครื่องจักร</small></span></p><p><b>verb (v.) คำกริยา</b> — การกระทำหรือสภาพ ทุกประโยคต้องมีอย่างน้อยหนึ่งตัว<br><span class=\"bv-rx\">She <b>sends</b> the report every Friday. <small>เธอส่งรายงานทุกวันศุกร์</small></span></p><p><b>adjective (adj.) คำคุณศัพท์</b> — บอกลักษณะของคำนาม<br><span class=\"bv-rx\">a <b>new</b> <b>digital</b> camera <small>กล้องดิจิทัลรุ่นใหม่</small></span></p><p><b>adverb (adv.) คำกริยาวิเศษณ์</b> — บอกว่าทำอย่างไร เมื่อไร บ่อยแค่ไหน ขยายกริยา คุณศัพท์ หรือ adverb อื่น<br><span class=\"bv-rx\">The line runs <b>smoothly</b>. <small>ไลน์ผลิตเดินได้ราบรื่น</small></span></p><p><b>pronoun / preposition / conjunction / interjection</b> — สรรพนามแทนคำนาม (he, it), บุพบทบอกตำแหน่งหรือเวลา (in, on, at), คำเชื่อมเชื่อมคำหรือประโยค (and, because), คำอุทาน (Oh!, Wow!)<br><span class=\"bv-rx\"><b>She</b> left <b>at</b> six <b>because</b> <b>she</b> was tired. <small>เธอกลับตอนหกโมงเพราะเหนื่อย</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The operator checks the machine every morning.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The operator checks the machine every morning.</div><div class=\"ex-th thai\">พนักงานคุมเครื่องตรวจเครื่องจักรทุกเช้า</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"This cable is too short.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">This cable is too short.</div><div class=\"ex-th thai\">สายเส้นนี้สั้นเกินไป</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please handle the boards carefully.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please handle the boards carefully.</div><div class=\"ex-th thai\">โปรดจับแผงวงจรอย่างระมัดระวัง</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We tested it, but it failed.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We tested it, but it failed.</div><div class=\"ex-th thai\">เราทดสอบแล้ว แต่ไม่ผ่าน</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ She is a care engineer.</p><p class=\"ok\">✓ She is a careful engineer.</p><small>ช่องหน้าคำนามต้องเป็น adjective (careful) ไม่ใช่ noun (care)</small></div><div class=\"bv-m\"><p class=\"no\">✗ He works careful.</p><p class=\"ok\">✓ He works carefully.</p><small>ขยายกริยา works ต้องใช้ adverb (-ly)</small></div><div class=\"bv-m\"><p class=\"no\">✗ The produce of this line is high.</p><p class=\"ok\">✓ The production of this line is high.</p><small>หลัง The ... of ต้องเป็น noun: production (produce เป็น verb)</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> เวลาเจอคำใหม่ ให้ดูตำแหน่งและส่วนท้ายคำก่อน เช่น -tion มักเป็น noun, -ly มักเป็น adverb, -ful มักเป็น adjective แม้ยังไม่รู้ความหมาย ก็เลือกคำตอบในข้อสอบได้</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The new operator quickly learned the process. She checks every part carefully, and her line has very few defects.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\"><mark>The new operator</mark> <mark>quickly</mark> <mark>learned</mark> the process. <mark>She</mark> checks every part <mark>carefully</mark>, <mark>and</mark> <mark>her</mark> line has <mark>very few</mark> defects.</div><div class=\"ts-th\">พนักงานใหม่เรียนรู้กระบวนการได้เร็ว เธอตรวจทุกชิ้นอย่างระมัดระวัง และไลน์ของเธอมีของเสียน้อยมาก</div></div></div></div>","easy":{"say":"ทุกคำมี \"ตำแหน่ง\" ในประโยค เหมือนผู้เล่นในทีม ถามตัวเองว่าคำนี้ตอบคำถาม ใคร/อะไร (noun) ทำอะไร (verb) แบบไหน (adjective) หรืออย่างไร (adverb)","eg":["The <b>new</b> engineer <b>quickly</b> fixed it.","new = แบบไหน (adj.) · quickly = อย่างไร (adv.)"],"rule":"ถาม \"ใคร-ทำอะไร-แบบไหน-อย่างไร\" แล้วจะรู้ชนิดของคำ"}},{"id":"noun","en":"Nouns","th":"คำนาม (noun)","intro":"คำนามเป็นชื่อของคน สิ่งของ สถานที่ หรือความคิด ทำหน้าที่เป็นประธานหรือกรรม และมักลงท้ายด้วย suffix ที่จำได้","r":[],"tips":[],"items":[{"id":"wf-noun-0","p":0,"s":"The _____ of the new line took three weeks.","gap":1,"o":{"A":"installing","B":"install","C":"installed","D":"installation"},"oth":{},"a":"D","x":"หลัง The และก่อน of ต้องเป็น noun: installation (install + -ation)","v":[]},{"id":"wf-noun-1","p":0,"s":"We are waiting for your _____.","gap":1,"o":{"A":"approve","B":"approved","C":"approval","D":"approving"},"oth":{},"a":"C","x":"หลัง your (คำแสดงความเป็นเจ้าของ) ต้องเป็น noun: approval","v":[]},{"id":"wf-noun-2","p":0,"s":"Customer _____ is very important to us.","gap":1,"o":{"A":"satisfy","B":"satisfied","C":"satisfying","D":"satisfaction"},"oth":{},"a":"D","x":"ตำแหน่งประธานหน้ากริยา is ต้องเป็น noun: satisfaction","v":[]},{"id":"wf-noun-3","p":0,"s":"Thank you for your _____ in this matter.","gap":1,"o":{"A":"assistant","B":"assisted","C":"assistance","D":"assist"},"oth":{},"a":"C","x":"หลัง your ต้องเป็น noun และความหมาย \"ความช่วยเหลือ\" คือ assistance (assistant = ผู้ช่วย ซึ่งเป็นคน)","v":[]},{"id":"wf-noun-4","p":0,"s":"คำใดเป็นคำนาม?","gap":0,"o":{"A":"improve","B":"improving","C":"improvement","D":"improved"},"oth":{},"a":"C","x":"-ment เป็น suffix ของ noun","v":[]},{"id":"wf-noun-5","p":0,"s":"คำใดเป็นคำนามนับไม่ได้ ใช้ a ข้างหน้าไม่ได้?","gap":0,"o":{"A":"tool","B":"equipment","C":"device","D":"machine"},"oth":{},"a":"B","x":"equipment นับไม่ได้ ใช้ some equipment หรือ a piece of equipment","v":[]},{"id":"wf-noun-6","p":0,"s":"The new manager made several important _____.","gap":1,"o":{"A":"decided","B":"decisions","C":"decide","D":"decisive"},"oth":{},"a":"B","x":"หลัง adjective (important) ต้องเป็น noun และ several ตามด้วยพหูพจน์ decisions","v":[]},{"id":"wf-noun-7","p":0,"s":"Please check the _____ of each part before packing.","gap":1,"o":{"A":"qualify","B":"qualifying","C":"qualified","D":"quality"},"oth":{},"a":"D","x":"หลัง the และก่อน of ต้องเป็น noun: quality","v":[]},{"id":"wf-noun-8","p":0,"s":"คำใดเป็น noun (คำนาม)?","gap":0,"o":{"A":"speak","B":"container","C":"enhance","D":"allow"},"oth":{},"a":"B","x":"container (ภาชนะ) ลงท้ายด้วย -er ซึ่งเป็น suffix ของ noun ส่วนคำอื่น: enhance = verb, speak = verb, allow = verb","v":[]},{"id":"wf-noun-9","p":0,"s":"คำใดเป็น noun (คำนาม)?","gap":0,"o":{"A":"directly","B":"vast","C":"protection","D":"promote"},"oth":{},"a":"C","x":"protection (การป้องกัน) ลงท้ายด้วย -ion ซึ่งเป็น suffix ของ noun ส่วนคำอื่น: directly = adverb, promote = verb, vast = adjective","v":[]},{"id":"wf-noun-10","p":0,"s":"คำใดเป็น noun (คำนาม)?","gap":0,"o":{"A":"happily","B":"observation","C":"successfully","D":"simply"},"oth":{},"a":"B","x":"observation (การสังเกต) ลงท้ายด้วย -ation ซึ่งเป็น suffix ของ noun ส่วนคำอื่น: simply = adverb, successfully = adverb, happily = adverb","v":[]},{"id":"wf-noun-11","p":0,"s":"คำใดเป็น noun (คำนาม)?","gap":0,"o":{"A":"encourage","B":"rarely","C":"healthy","D":"leader"},"oth":{},"a":"D","x":"leader (ผู้นำ) ลงท้ายด้วย -er ซึ่งเป็น suffix ของ noun ส่วนคำอื่น: healthy = adjective, encourage = verb, rarely = adverb","v":[]}],"grp":"Parts of Speech — ชนิดของคำ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">คำนามเหมือน \"ป้ายชื่อ\" ที่ติดให้ทุกสิ่ง ทั้งของที่จับได้ (machine) และสิ่งที่จับไม่ได้ (quality, safety) ในภาษาไทยเราพูด \"การ...\" \"ความ...\" เพื่อทำกริยาให้เป็นคำนาม ภาษาอังกฤษก็ทำแบบเดียวกันโดยเติม <b>suffix</b> ท้ายคำ</div><figure class=\"bv bv-parts\"><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">inspection</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">inspect</b><small>ตรวจ</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ion</b><small>การ...</small></span></span><span class=\"wp-th\">การตรวจสอบ</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">improvement</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">improve</b><small>ปรับปรุง</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ment</b><small>การ...</small></span></span><span class=\"wp-th\">การปรับปรุง</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">accuracy</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-r\"><b lang=\"en\">accur</b><small>ใส่ใจ</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">acy</b><small>ความ...</small></span></span><span class=\"wp-th\">ความแม่นยำ</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">reliability</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">rely</b><small>พึ่งพา</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">able</b><small>...ได้</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ity</b><small>ความ...</small></span></span><span class=\"wp-th\">ความน่าเชื่อถือ</span></div><figcaption>กริยาหรือคุณศัพท์ + suffix ของคำนาม = คำนาม (คล้าย &quot;การ...&quot; &quot;ความ...&quot; ในภาษาไทย)</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ตำแหน่ง</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>หลัง a / an / the</td><td>the &lt;decision&gt;</td></tr><tr><td>หลัง my / your / our</td><td>your &lt;approval&gt;</td></tr><tr><td>หลัง adjective</td><td>a quick &lt;response&gt;</td></tr><tr><td>ก่อน of</td><td>the &lt;quality&gt; of</td></tr><tr><td>หลังบุพบท</td><td>for &lt;inspection&gt;</td></tr></tbody></table></div><figcaption>ถ้าช่องว่างอยู่ตำแหน่งเหล่านี้ ให้เลือก noun</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ตำแหน่งคำนาม</div><div class=\"tf-value\">a / the / my + (adj) + NOUN</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ทำกริยาเป็นคำนาม</div><div class=\"tf-value\">verb + -tion / -ment / -ance</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ทำคุณศัพท์เป็นคำนาม</div><div class=\"tf-value\">adj + -ness / -ity</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>หน้าที่ของคำนาม</b> — เป็นประธาน (หน้ากริยา) เป็นกรรม (หลังกริยา) หรือตามหลังบุพบท<br><span class=\"bv-rx\"><b>Safety</b> is our first <b>priority</b>. <small>ความปลอดภัยคือสิ่งสำคัญอันดับแรก</small></span><br><span class=\"bv-rx\">Send the <b>invoice</b> to <b>accounting</b>. <small>ส่งใบแจ้งหนี้ไปแผนกบัญชี</small></span></p><p><b>ตำแหน่งที่ต้องเป็นคำนาม</b> — หลัง a / an / the / my / this, หลัง adjective, หลังบุพบท, ก่อน of<br><span class=\"bv-rx\">the <b>installation</b> of the software <small>การติดตั้งซอฟต์แวร์</small></span><br><span class=\"bv-rx\">a quick <b>decision</b> <small>การตัดสินใจที่รวดเร็ว</small></span></p><p><b>suffix ของคำนาม</b> — -tion/-sion, -ment, -ness, -ity, -ance/-ence, -er/-or, -ist, -ship, -age, -ure<br><span class=\"bv-rx\">inform → <b>information</b>, improve → <b>improvement</b>, kind → <b>kindness</b></span></p><p><b>คำนามนับได้ / นับไม่ได้</b> — นับได้มี a/an และเติม -s ได้ / นับไม่ได้ เช่น equipment, information, feedback ไม่เติม -s<br><span class=\"bv-rx\">two <b>machines</b> / some <b>equipment</b> <small>เครื่องจักรสองเครื่อง / อุปกรณ์จำนวนหนึ่ง</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The inspection found two defects.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The inspection found two defects.</div><div class=\"ex-th thai\">การตรวจพบของเสียสองชิ้น</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We need your signature here.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We need your signature here.</div><div class=\"ex-th thai\">เราต้องการลายเซ็นของคุณตรงนี้</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Accuracy is important in measurement.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Accuracy is important in measurement.</div><div class=\"ex-th thai\">ความแม่นยำสำคัญในการวัด</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The delivery arrived on time.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The delivery arrived on time.</div><div class=\"ex-th thai\">สินค้าที่ส่งมาถึงตรงเวลา</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ We need more informations.</p><p class=\"ok\">✓ We need more information.</p><small>information นับไม่ได้ ไม่เติม -s</small></div><div class=\"bv-m\"><p class=\"no\">✗ Thank you for your assist.</p><p class=\"ok\">✓ Thank you for your assistance.</p><small>หลัง your ต้องเป็น noun: assistance</small></div><div class=\"bv-m\"><p class=\"no\">✗ The produce cost is high.</p><p class=\"ok\">✓ The production cost is high.</p><small>ต้องใช้ noun production (produce เป็น verb ในความหมาย &quot;ผลิต&quot;)</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> คำนามบางคำมีสองแบบ: ผู้ทำ (employer, assistant) กับสิ่ง/การกระทำ (employment, assistance) อ่านความหมายในประโยคก่อนเลือก</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Our department received a complaint about the packaging. After an investigation, we found the cause and made an improvement.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">Our <mark>department</mark> received a <mark>complaint</mark> about the <mark>packaging</mark>. After an <mark>investigation</mark>, we found the <mark>cause</mark> and made an <mark>improvement</mark>.</div><div class=\"ts-th\">แผนกของเราได้รับคำร้องเรียนเรื่องบรรจุภัณฑ์ หลังจากตรวจสอบ เราพบสาเหตุและทำการปรับปรุง</div></div></div></div>","easy":{"say":"คำนามคือ \"ชื่อ\" ของสิ่งต่างๆ รวมถึงสิ่งที่จับไม่ได้ เช่น ความปลอดภัย ภาษาอังกฤษทำกริยาเป็นคำนามด้วยการเติมท้าย เหมือนภาษาไทยเติม \"การ\" \"ความ\" ข้างหน้า","eg":["inspect → <b>inspection</b>","ตรวจ → การตรวจ"],"rule":"หลัง a / the / your ... และก่อน of = ช่องของ noun"}},{"id":"verb","en":"Verbs","th":"คำกริยา (verb)","intro":"คำกริยาบอกการกระทำหรือสภาพ เป็นหัวใจของประโยค และเป็นคำเดียวที่เปลี่ยนรูปตาม tense และประธาน","r":[],"tips":[],"items":[{"id":"wf-verb-0","p":0,"s":"We need to _____ the process to save time.","gap":1,"o":{"A":"simply","B":"simple","C":"simplify","D":"simplicity"},"oth":{},"a":"C","x":"หลัง to ต้องเป็นกริยารูปเดิม: simplify (simple + -ify = ทำให้ง่าย)","v":[]},{"id":"wf-verb-1","p":0,"s":"The company plans to _____ its warehouse.","gap":1,"o":{"A":"large","B":"largely","C":"enlarge","D":"largeness"},"oth":{},"a":"C","x":"หลัง to ต้องเป็นกริยา: enlarge (en- + large = ทำให้ใหญ่)","v":[]},{"id":"wf-verb-2","p":0,"s":"Please _____ the form and return it by Friday.","gap":1,"o":{"A":"completion","B":"completely","C":"completed","D":"complete"},"oth":{},"a":"D","x":"ประโยคคำสั่งขึ้นต้นด้วยกริยารูปเดิม: complete","v":[]},{"id":"wf-verb-3","p":0,"s":"The new software will _____ the reporting process.","gap":1,"o":{"A":"automate","B":"automatic","C":"automatically","D":"automation"},"oth":{},"a":"A","x":"หลัง will ต้องเป็นกริยา: automate","v":[]},{"id":"wf-verb-4","p":0,"s":"คำใดเป็น linking verb (ตามด้วย adjective ได้)?","gap":0,"o":{"A":"seem","B":"repair","C":"send","D":"install"},"oth":{},"a":"A","x":"seem = ดูเหมือน เชื่อมประธานกับคำบอกลักษณะ เช่น It seems easy.","v":[]},{"id":"wf-verb-5","p":0,"s":"The machine _____ noisy after the repair.","gap":1,"o":{"A":"become","B":"becomes to","C":"becoming","D":"became"},"oth":{},"a":"D","x":"became (อดีตของ become) เป็น linking verb ตามด้วย adjective noisy","v":[]},{"id":"wf-verb-6","p":0,"s":"คำใดเป็นคำกริยา?","gap":0,"o":{"A":"standard","B":"standardized work","C":"standardize","D":"standardization"},"oth":{},"a":"C","x":"-ize เป็น suffix ของ verb (standard + -ize = ทำให้เป็นมาตรฐาน)","v":[]},{"id":"wf-verb-7","p":0,"s":"We should _____ the safety rules to all new staff.","gap":1,"o":{"A":"explanation","B":"explained","C":"explanatory","D":"explain"},"oth":{},"a":"D","x":"หลัง should ต้องเป็นกริยารูปเดิม: explain","v":[]},{"id":"wf-verb-8","p":0,"s":"คำใดเป็น verb (คำกริยา)?","gap":0,"o":{"A":"waiter","B":"due","C":"donate","D":"musical"},"oth":{},"a":"C","x":"donate (บริจาค) ลงท้ายด้วย -ate ซึ่งเป็น suffix ของ verb ส่วนคำอื่น: musical = adjective, waiter = noun, due = adjective","v":[]},{"id":"wf-verb-9","p":0,"s":"คำใดเป็น verb (คำกริยา)?","gap":0,"o":{"A":"tennis","B":"operate","C":"unfair","D":"movie"},"oth":{},"a":"B","x":"operate (ดำเนินงาน) ลงท้ายด้วย -ate ซึ่งเป็น suffix ของ verb ส่วนคำอื่น: tennis = noun, movie = noun, unfair = adjective","v":[]},{"id":"wf-verb-10","p":0,"s":"คำใดเป็น verb (คำกริยา)?","gap":0,"o":{"A":"cheap","B":"painting","C":"educate","D":"existence"},"oth":{},"a":"C","x":"educate (ให้ความรู้) ลงท้ายด้วย -ate ซึ่งเป็น suffix ของ verb ส่วนคำอื่น: painting = noun, cheap = adjective, existence = noun","v":[]},{"id":"wf-verb-11","p":0,"s":"คำใดเป็น verb (คำกริยา)?","gap":0,"o":{"A":"organize","B":"tea","C":"departure","D":"period"},"oth":{},"a":"A","x":"organize (จัดระเบียบ) ลงท้ายด้วย -ize ซึ่งเป็น suffix ของ verb ส่วนคำอื่น: departure = noun, tea = noun, period = noun","v":[]}],"grp":"Parts of Speech — ชนิดของคำ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">ถ้าประโยคคือรถ คำกริยาคือ <b>เครื่องยนต์</b> ไม่มีกริยา ประโยคก็ไม่เดิน ภาษาไทยบางครั้งไม่ต้องมีกริยา (\"ห้องนี้ใหญ่\") แต่ภาษาอังกฤษต้องมีเสมอ (\"This room <b>is</b> big.\")</div><figure class=\"bv bv-blocks\"><div class=\"bv-row\"><span class=\"bv-rl\">action verb</span><div class=\"bv-chips\"><span class=\"bv-chip r-S\"><b>The team</b><i>ประธาน</i></span><span class=\"bv-chip r-V\"><b>tested</b><i>กริยา</i></span><span class=\"bv-chip r-O\"><b>the new board</b><i>กรรม</i></span></div></div><div class=\"bv-row\"><span class=\"bv-rl\">linking verb + adjective</span><div class=\"bv-chips\"><span class=\"bv-chip r-S\"><b>The result</b><i>ประธาน</i></span><span class=\"bv-chip r-V\"><b>looks</b><i>กริยา</i></span><span class=\"bv-chip r-A\"><b>good</b><i>คำขยาย</i></span></div></div><div class=\"bv-row\"><span class=\"bv-rl\">ไม่มีกรรม</span><div class=\"bv-chips\"><span class=\"bv-chip r-S\"><b>The motor</b><i>ประธาน</i></span><span class=\"bv-chip r-V\"><b>stopped</b><i>กริยา</i></span><span class=\"bv-chip r-ADV\"><b>suddenly</b><i>adverb</i></span></div></div><figcaption>กริยาบางตัวต้องมีกรรม บางตัวเชื่อมไปหาคำบอกลักษณะ</figcaption></figure><figure class=\"bv bv-parts\"><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">simplify</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">simpl</b><small>ง่าย</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ify</b><small>ทำให้</small></span></span><span class=\"wp-th\">ทำให้ง่าย</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">standardize</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">standard</b><small>มาตรฐาน</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ize</b><small>ทำให้เป็น</small></span></span><span class=\"wp-th\">ทำให้เป็นมาตรฐาน</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">shorten</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">short</b><small>สั้น</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">en</b><small>ทำให้</small></span></span><span class=\"wp-th\">ทำให้สั้นลง</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">enlarge</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">en</b><small>ทำให้</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-b\"><b lang=\"en\">large</b><small>ใหญ่</small></span></span><span class=\"wp-th\">ขยายให้ใหญ่ขึ้น</span></div><figcaption>suffix และ prefix ที่ทำให้เป็นกริยา</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ประโยค</div><div class=\"tf-value\">ประธาน + VERB (+ กรรม)</div></div><div class=\"tense-formula\"><div class=\"tf-label\">หลังคำช่วย</div><div class=\"tf-value\">can / will / should / to + V1</div></div><div class=\"tense-formula\"><div class=\"tf-label\">linking verb</div><div class=\"tf-value\">be / seem / become / look + adjective</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>action verb กับ linking verb</b> — action = การกระทำ (check, send) / linking = เชื่อมประธานกับคำบอกลักษณะ (be, seem, become, look, feel) ตามด้วย adjective<br><span class=\"bv-rx\">The result <b>looks</b> good. <small>ผลออกมาดูดี</small></span><br><span class=\"bv-rx\">He <b>became</b> a supervisor. <small>เขาได้เป็นหัวหน้างาน</small></span></p><p><b>ต้องมีกรรม / ไม่ต้องมีกรรม</b> — transitive ต้องมีกรรมตาม (repair the machine) / intransitive ไม่ต้องมีกรรม (The machine stopped.)<br><span class=\"bv-rx\">We <b>repaired</b> the pump. <small>เราซ่อมปั๊มแล้ว</small></span><br><span class=\"bv-rx\">The pump <b>stopped</b>. <small>ปั๊มหยุดทำงาน</small></span></p><p><b>suffix ของคำกริยา</b> — -ize (ทำให้เป็น), -ify (ทำให้), -en (ทำให้), -ate (ทำ)<br><span class=\"bv-rx\">standard → <b>standardize</b>, clear → <b>clarify</b>, short → <b>shorten</b>, valid → <b>validate</b></span></p><p><b>ตำแหน่งที่ต้องเป็นกริยา</b> — หลังประธาน, หลัง to (to + V1), หลัง can / will / should, คำสั่งขึ้นต้นประโยค<br><span class=\"bv-rx\">Please <b>confirm</b> the order. <small>กรุณายืนยันคำสั่งซื้อ</small></span><br><span class=\"bv-rx\">We need to <b>reduce</b> costs. <small>เราต้องลดต้นทุน</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The machine stopped at 10 a.m.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The machine stopped at 10 a.m.</div><div class=\"ex-th thai\">เครื่องหยุดตอนสิบโมง</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please confirm your attendance.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please confirm your attendance.</div><div class=\"ex-th thai\">กรุณายืนยันการเข้าร่วม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The price seems reasonable.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The price seems reasonable.</div><div class=\"ex-th thai\">ราคาดูสมเหตุสมผล</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We will standardize the labels.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We will standardize the labels.</div><div class=\"ex-th thai\">เราจะทำฉลากให้เป็นมาตรฐานเดียวกัน</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ This machine very old.</p><p class=\"ok\">✓ This machine is very old.</p><small>ประโยคต้องมีกริยา ใช้ is</small></div><div class=\"bv-m\"><p class=\"no\">✗ We need to discussion the plan.</p><p class=\"ok\">✓ We need to discuss the plan.</p><small>หลัง to ต้องเป็นกริยา discuss ไม่ใช่ noun discussion</small></div><div class=\"bv-m\"><p class=\"no\">✗ The result looks well.</p><p class=\"ok\">✓ The result looks good.</p><small>หลัง linking verb (look) ใช้ adjective good ไม่ใช่ adverb well</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> จำ 4 ตำแหน่งของกริยา: หลังประธาน หลัง to หลังคำช่วย (can, will, should, must) และต้นประโยคคำสั่ง</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Yesterday the conveyor stopped. The technicians checked the motor, replaced a belt and restarted the line. Now it runs well.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">Yesterday the conveyor <mark>stopped</mark>. The technicians <mark>checked</mark> the motor, <mark>replaced</mark> a belt and <mark>restarted</mark> the line. Now it <mark>runs</mark> well.</div><div class=\"ts-th\">เมื่อวานสายพานหยุด ช่างตรวจมอเตอร์ เปลี่ยนสายพาน และเริ่มไลน์ใหม่ ตอนนี้เดินได้ดี</div></div></div></div>","easy":{"say":"กริยาคือเครื่องยนต์ของประโยค ภาษาอังกฤษต้องมีทุกประโยค แม้ประโยคที่บอกลักษณะก็ต้องมี is / are","eg":["This cable <b>is</b> short.","สายนี้สั้น (ภาษาไทยไม่มีคำว่า \"เป็น\" แต่ภาษาอังกฤษต้องมี is)"],"rule":"หลัง to / can / will / should = กริยารูปเดิม"}},{"id":"adj","en":"Adjectives","th":"คำคุณศัพท์ (adjective)","intro":"คำคุณศัพท์บอกลักษณะของคำนาม วางหน้าคำนาม หรือหลัง be / seem / become / look","r":[],"tips":[],"items":[{"id":"wf-adj-0","p":0,"s":"We are looking for a _____ supplier.","gap":1,"o":{"A":"rely","B":"reliably","C":"reliability","D":"reliable"},"oth":{},"a":"D","x":"ระหว่าง a กับ noun (supplier) ต้องเป็น adjective: reliable","v":[]},{"id":"wf-adj-1","p":0,"s":"The new method is very _____.","gap":1,"o":{"A":"effect","B":"effective","C":"effectively","D":"effectiveness"},"oth":{},"a":"B","x":"หลัง very และ be ต้องเป็น adjective: effective","v":[]},{"id":"wf-adj-2","p":0,"s":"Please be _____ when you carry the glass panels.","gap":1,"o":{"A":"care","B":"careful","C":"carefully","D":"carefulness"},"oth":{},"a":"B","x":"หลัง be ต้องเป็น adjective: careful","v":[]},{"id":"wf-adj-3","p":0,"s":"The training was _____. Everyone fell asleep.","gap":1,"o":{"A":"bore","B":"boredom","C":"boring","D":"bored"},"oth":{},"a":"C","x":"สิ่งที่ทำให้เบื่อใช้ -ing: boring","v":[]},{"id":"wf-adj-4","p":0,"s":"The staff were _____ with the new schedule.","gap":1,"o":{"A":"satisfied","B":"satisfying","C":"satisfaction","D":"satisfy"},"oth":{},"a":"A","x":"ความรู้สึกของคนใช้ -ed: satisfied","v":[]},{"id":"wf-adj-5","p":0,"s":"This chemical is _____. Wear gloves.","gap":1,"o":{"A":"dangerously","B":"dangerous","C":"danger","D":"endanger"},"oth":{},"a":"B","x":"หลัง is ต้องเป็น adjective: dangerous (danger + -ous)","v":[]},{"id":"wf-adj-6","p":0,"s":"คำใดเป็นคำคุณศัพท์?","gap":0,"o":{"A":"use","B":"useless","C":"user","D":"usage"},"oth":{},"a":"B","x":"-less เป็น suffix ของ adjective = ไม่มี (useless = ไร้ประโยชน์)","v":[]},{"id":"wf-adj-7","p":0,"s":"We bought three _____ printers.","gap":1,"o":{"A":"new","B":"newly","C":"newness","D":"news"},"oth":{},"a":"A","x":"adjective ไม่เติม -s แม้คำนามเป็นพหูพจน์","v":[]},{"id":"wf-adj-8","p":0,"s":"คำใดเป็น adjective (คำคุณศัพท์)?","gap":0,"o":{"A":"healthy","B":"decide","C":"staff","D":"technique"},"oth":{},"a":"A","x":"healthy (สุขภาพดี) ลงท้ายด้วย -y ซึ่งเป็น suffix ของ adjective ส่วนคำอื่น: staff = noun, decide = verb, technique = noun","v":[]},{"id":"wf-adj-9","p":0,"s":"คำใดเป็น adjective (คำคุณศัพท์)?","gap":0,"o":{"A":"silence","B":"coin","C":"cultural","D":"string"},"oth":{},"a":"C","x":"cultural (ทางวัฒนธรรม) ลงท้ายด้วย -al ซึ่งเป็น suffix ของ adjective ส่วนคำอื่น: coin = noun, string = noun, silence = noun","v":[]},{"id":"wf-adj-10","p":0,"s":"คำใดเป็น adjective (คำคุณศัพท์)?","gap":0,"o":{"A":"sticky","B":"farm","C":"wrap","D":"warn"},"oth":{},"a":"A","x":"sticky (เหนียว) ลงท้ายด้วย -y ซึ่งเป็น suffix ของ adjective ส่วนคำอื่น: farm = verb, warn = verb, wrap = verb","v":[]},{"id":"wf-adj-11","p":0,"s":"คำใดเป็น adjective (คำคุณศัพท์)?","gap":0,"o":{"A":"emotional","B":"adventure","C":"ice","D":"communication"},"oth":{},"a":"A","x":"emotional (ทางอารมณ์) ลงท้ายด้วย -al ซึ่งเป็น suffix ของ adjective ส่วนคำอื่น: adventure = noun, ice = noun, communication = noun","v":[]}],"grp":"Parts of Speech — ชนิดของคำ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">คำคุณศัพท์คือ \"ฟิลเตอร์\" ที่ทำให้คำนามชัดขึ้น machine เฉยๆ ไม่ชัด แต่ <b>old</b> machine, <b>automatic</b> machine ชัดกว่า ข้อต่างจากภาษาไทย: ภาษาอังกฤษวางคุณศัพท์ <b>หน้า</b>คำนาม (เครื่อง<b>ใหม่</b> = a <b>new</b> machine)</div><figure class=\"bv bv-blocks\"><div class=\"bv-row\"><span class=\"bv-rl\">หน้าคำนาม</span><div class=\"bv-chips\"><span class=\"bv-chip r-X\"><b>a</b></span><span class=\"bv-chip r-A\"><b>reliable</b><i>คำขยาย</i></span><span class=\"bv-chip r-O\"><b>supplier</b><i>กรรม</i></span></div></div><div class=\"bv-row\"><span class=\"bv-rl\">หลัง linking verb</span><div class=\"bv-chips\"><span class=\"bv-chip r-S\"><b>The supplier</b><i>ประธาน</i></span><span class=\"bv-chip r-BE\"><b>is</b><i>be</i></span><span class=\"bv-chip r-A\"><b>reliable</b><i>คำขยาย</i></span></div></div><figcaption>คุณศัพท์มีสองบ้าน: หน้าคำนาม และหลัง be / seem / look</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>suffix</th><th>ความหมาย</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>-ful</td><td>เต็มไปด้วย</td><td>useful, careful</td></tr><tr><td>-less</td><td>ไม่มี</td><td>useless, wireless</td></tr><tr><td>-ous</td><td>มีลักษณะ</td><td>dangerous, various</td></tr><tr><td>-ive</td><td>ที่มีลักษณะ</td><td>effective, active</td></tr><tr><td>-able / -ible</td><td>...ได้</td><td>reliable, flexible</td></tr><tr><td>-al / -ic</td><td>เกี่ยวกับ</td><td>electrical, electronic</td></tr></tbody></table></div><figcaption>เห็น suffix เหล่านี้ เดาได้เลยว่าเป็น adjective</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ตำแหน่ง 1</div><div class=\"tf-value\">a / the + ADJ + noun</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ตำแหน่ง 2</div><div class=\"tf-value\">be / seem / look + ADJ</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ความรู้สึก</div><div class=\"tf-value\">คน + -ed / สิ่งที่ทำให้รู้สึก + -ing</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>สองตำแหน่งหลัก</b> — หน้าคำนาม (a reliable supplier) หรือหลัง linking verb (The supplier is reliable.)<br><span class=\"bv-rx\">a <b>reliable</b> supplier <small>ผู้จัดหาที่ไว้ใจได้</small></span><br><span class=\"bv-rx\">The data is <b>accurate</b>. <small>ข้อมูลถูกต้องแม่นยำ</small></span></p><p><b>suffix ของคุณศัพท์</b> — -ful, -less, -ous, -ive, -able/-ible, -al, -ic, -y, -ish<br><span class=\"bv-rx\">care → <b>careful</b> / <b>careless</b>, danger → <b>dangerous</b>, effect → <b>effective</b>, electric → <b>electrical</b></span></p><p><b>-ed กับ -ing</b> — -ed = ความรู้สึกของคน (bored, interested) / -ing = สิ่งที่ทำให้รู้สึก (boring, interesting)<br><span class=\"bv-rx\">I am <b>interested</b> in the project. <small>ฉันสนใจโครงการนี้</small></span><br><span class=\"bv-rx\">The project is <b>interesting</b>. <small>โครงการนี้น่าสนใจ</small></span></p><p><b>adjective ไม่เติม -s</b> — คุณศัพท์ไม่เปลี่ยนตามพหูพจน์<br><span class=\"bv-rx\">two <b>new</b> machines (ไม่ใช่ news) <small>เครื่องใหม่สองเครื่อง</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"This is a wireless keyboard.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">This is a wireless keyboard.</div><div class=\"ex-th thai\">นี่คือคีย์บอร์ดไร้สาย</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The instructions are clear.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The instructions are clear.</div><div class=\"ex-th thai\">คำแนะนำชัดเจน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"It was a useful meeting.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">It was a useful meeting.</div><div class=\"ex-th thai\">เป็นการประชุมที่มีประโยชน์</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"I am confused by the drawing.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">I am confused by the drawing.</div><div class=\"ex-th thai\">ฉันงงกับแบบ</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ a machine new</p><p class=\"ok\">✓ a new machine</p><small>คุณศัพท์อยู่หน้าคำนาม</small></div><div class=\"bv-m\"><p class=\"no\">✗ I am boring in the meeting.</p><p class=\"ok\">✓ I am bored in the meeting.</p><small>ความรู้สึกของคนใช้ -ed (I am boring = ฉันเป็นคนน่าเบื่อ)</small></div><div class=\"bv-m\"><p class=\"no\">✗ The test was success.</p><p class=\"ok\">✓ The test was successful.</p><small>หลัง was ต้องเป็น adjective: successful</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> -able / -ible บอกว่า &quot;ทำ...ได้&quot; เช่น washable = ซักได้ readable = อ่านออก ใช้เดาความหมายคำใหม่ได้ดีมาก</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The new wireless sensor is small and accurate. The engineers were impressed because the results were excellent.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The new <mark>wireless</mark> sensor is <mark>small</mark> and <mark>accurate</mark>. The engineers were <mark>impressed</mark> because the results were <mark>excellent</mark>.</div><div class=\"ts-th\">เซนเซอร์ไร้สายตัวใหม่เล็กและแม่นยำ วิศวกรประทับใจเพราะผลลัพธ์ดีเยี่ยม</div></div></div></div>","easy":{"say":"คุณศัพท์บอก \"แบบไหน\" ของคำนาม วางหน้าคำนาม (กลับกับภาษาไทย) หรือหลัง is / are / seem","eg":["a <b>careful</b> check · The check is <b>careful</b>.","การตรวจที่ละเอียด"],"rule":"หน้าคำนาม หรือหลัง be = ช่องของ adjective"}},{"id":"adv","en":"Adverbs","th":"คำกริยาวิเศษณ์ (adverb)","intro":"adverb ขยายกริยา คุณศัพท์ หรือ adverb ด้วยกัน บอกว่าทำอย่างไร เมื่อไร ที่ไหน บ่อยแค่ไหน หรือมากแค่ไหน","r":[],"tips":[],"items":[{"id":"wf-adv-0","p":0,"s":"Please handle the samples _____.","gap":1,"o":{"A":"carefully","B":"careful","C":"careless","D":"care"},"oth":{},"a":"A","x":"ขยายกริยา handle ต้องเป็น adverb: carefully","v":[]},{"id":"wf-adv-1","p":0,"s":"The system restarts _____ after an update.","gap":1,"o":{"A":"automation","B":"automatically","C":"automatic","D":"automate"},"oth":{},"a":"B","x":"ขยายกริยา restarts ต้องเป็น adverb: automatically","v":[]},{"id":"wf-adv-2","p":0,"s":"The new line works very _____.","gap":1,"o":{"A":"better than","B":"well","C":"goodly","D":"good"},"oth":{},"a":"B","x":"ขยายกริยา works ต้องใช้ adverb well (good เป็น adjective)","v":[]},{"id":"wf-adv-3","p":0,"s":"The test results were _____ good.","gap":1,"o":{"A":"surprise","B":"surprised","C":"surprisingly","D":"surprising"},"oth":{},"a":"C","x":"ขยาย adjective good ต้องเป็น adverb: surprisingly","v":[]},{"id":"wf-adv-4","p":0,"s":"We _____ check the stock on Mondays.","gap":1,"o":{"A":"use","B":"usually","C":"usage","D":"usual"},"oth":{},"a":"B","x":"adverb บอกความถี่วางหน้ากริยาแท้ check","v":[]},{"id":"wf-adv-5","p":0,"s":"He _____ came to the meeting; he was there for only five minutes.","gap":1,"o":{"A":"hard","B":"hardness","C":"harder","D":"hardly"},"oth":{},"a":"D","x":"hardly = แทบจะไม่ (ต่างจาก hard = หนัก)","v":[]},{"id":"wf-adv-6","p":0,"s":"คำใดเป็น adverb?","gap":0,"o":{"A":"quicken","B":"quickly","C":"quick","D":"quickness"},"oth":{},"a":"B","x":"adjective + -ly = adverb","v":[]},{"id":"wf-adv-7","p":0,"s":"_____, the meeting was cancelled.","gap":1,"o":{"A":"Fortune","B":"Unfortunately","C":"Misfortune","D":"Unfortunate"},"oth":{},"a":"B","x":"ขยายทั้งประโยคและวางต้นประโยคตามด้วย comma ใช้ adverb","v":[]},{"id":"wf-adv-8","p":0,"s":"คำใดเป็น adverb (คำกริยาวิเศษณ์)?","gap":0,"o":{"A":"screen","B":"award","C":"delicious","D":"fully"},"oth":{},"a":"D","x":"fully (อย่างเต็มที่) ลงท้ายด้วย -ly ซึ่งเป็น suffix ของ adverb ส่วนคำอื่น: delicious = adjective, screen = verb, award = noun","v":[]},{"id":"wf-adv-9","p":0,"s":"คำใดเป็น adverb (คำกริยาวิเศษณ์)?","gap":0,"o":{"A":"reasonable","B":"mostly","C":"extend","D":"tent"},"oth":{},"a":"B","x":"mostly (ส่วนใหญ่) ลงท้ายด้วย -ly ซึ่งเป็น suffix ของ adverb ส่วนคำอื่น: reasonable = adjective, extend = verb, tent = noun","v":[]},{"id":"wf-adv-10","p":0,"s":"คำใดเป็น adverb (คำกริยาวิเศษณ์)?","gap":0,"o":{"A":"dancing","B":"invent","C":"totally","D":"examination"},"oth":{},"a":"C","x":"totally (โดยสิ้นเชิง) ลงท้ายด้วย -ly ซึ่งเป็น suffix ของ adverb ส่วนคำอื่น: dancing = noun, examination = noun, invent = verb","v":[]},{"id":"wf-adv-11","p":0,"s":"คำใดเป็น adverb (คำกริยาวิเศษณ์)?","gap":0,"o":{"A":"repair","B":"boss","C":"college","D":"initially"},"oth":{},"a":"D","x":"initially (เริ่มแรก) ลงท้ายด้วย -ly ซึ่งเป็น suffix ของ adverb ส่วนคำอื่น: repair = noun, boss = noun, college = noun","v":[]}],"grp":"Parts of Speech — ชนิดของคำ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">ถ้า adjective คือ \"แบบไหน\" adverb คือ \"<b>อย่างไร</b>\" ภาษาไทยใช้คำเดิมได้ทั้งสองแบบ (ทำงาน<b>ดี</b>, คน<b>ดี</b>) แต่ภาษาอังกฤษต้องเปลี่ยนรูป: good worker / works <b>well</b>, careful check / check <b>carefully</b></div><figure class=\"bv bv-parts\"><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">carefully</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">care</b><small>การดูแล</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ful</b><small>เต็มไปด้วย</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ly</b><small>อย่าง...</small></span></span><span class=\"wp-th\">อย่างระมัดระวัง</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">easily</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">eas</b><small>ง่าย (easy)</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ily</b><small>อย่าง...</small></span></span><span class=\"wp-th\">อย่างง่ายดาย</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">automatically</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">automatic</b><small>อัตโนมัติ</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ally</b><small>อย่าง...</small></span></span><span class=\"wp-th\">โดยอัตโนมัติ</span></div><figcaption>adjective + -ly = adverb (y → i, -ic → -ically)</figcaption></figure><figure class=\"bv bv-scale\"><div class=\"bv-sr\"><span class=\"bv-sw\">always</span><span class=\"bv-sb\"><i style=\"width:100%\"></i></span><span class=\"bv-st\">เสมอ</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">usually</span><span class=\"bv-sb\"><i style=\"width:80%\"></i></span><span class=\"bv-st\">มักจะ</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">often</span><span class=\"bv-sb\"><i style=\"width:65%\"></i></span><span class=\"bv-st\">บ่อย</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">sometimes</span><span class=\"bv-sb\"><i style=\"width:45%\"></i></span><span class=\"bv-st\">บางครั้ง</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">rarely</span><span class=\"bv-sb\"><i style=\"width:15%\"></i></span><span class=\"bv-st\">นานๆ ครั้ง</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">never</span><span class=\"bv-sb\"><i style=\"width:3%\"></i></span><span class=\"bv-st\">ไม่เคย</span></div><figcaption>adverb บอกความถี่ เรียงจากมากไปน้อย</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ขยายกริยา</div><div class=\"tf-value\">verb + ADV (work carefully)</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ขยายคุณศัพท์</div><div class=\"tf-value\">ADV + adj (very / extremely hot)</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ความถี่</div><div class=\"tf-value\">ADV + กริยาแท้ / be + ADV</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>adjective + -ly = adverb</b> — ส่วนใหญ่สร้างจาก adjective + -ly (y → i)<br><span class=\"bv-rx\">careful → <b>carefully</b>, easy → <b>easily</b>, automatic → <b>automatically</b></span></p><p><b>ขยายอะไรได้บ้าง</b> — กริยา (work carefully) คุณศัพท์ (extremely hot) adverb (very quickly) หรือทั้งประโยค (Unfortunately, ...)<br><span class=\"bv-rx\">The parts are <b>extremely</b> small. <small>ชิ้นส่วนเล็กมาก</small></span><br><span class=\"bv-rx\"><b>Unfortunately</b>, the shipment is late. <small>โชคไม่ดีที่สินค้ามาช้า</small></span></p><p><b>adverb บอกความถี่</b> — always, usually, often, sometimes, rarely, never วางหน้ากริยาแท้ แต่หลัง be<br><span class=\"bv-rx\">We <b>usually</b> start at 8. <small>เราเริ่มแปดโมงเป็นประจำ</small></span><br><span class=\"bv-rx\">He is <b>always</b> on time. <small>เขาตรงเวลาเสมอ</small></span></p><p><b>คำที่ต้องระวัง</b> — good (adj.) → well (adv.) / fast, hard, late เป็นทั้ง adj. และ adv. / hardly = แทบจะไม่, lately = เร็วๆ นี้<br><span class=\"bv-rx\">She works <b>hard</b>. <small>เธอทำงานหนัก</small></span><br><span class=\"bv-rx\">She <b>hardly</b> works. <small>เธอแทบไม่ทำงานเลย</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The robot moves slowly and precisely.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The robot moves slowly and precisely.</div><div class=\"ex-th thai\">หุ่นยนต์เคลื่อนที่ช้าๆ และแม่นยำ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The room is extremely clean.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The room is extremely clean.</div><div class=\"ex-th thai\">ห้องสะอาดมาก</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We often work overtime in December.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We often work overtime in December.</div><div class=\"ex-th thai\">เรามักทำงานล่วงเวลาในเดือนธันวาคม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Fortunately, nobody was hurt.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Fortunately, nobody was hurt.</div><div class=\"ex-th thai\">โชคดีที่ไม่มีใครบาดเจ็บ</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ He speaks English very good.</p><p class=\"ok\">✓ He speaks English very well.</p><small>ขยายกริยา speaks ใช้ well</small></div><div class=\"bv-m\"><p class=\"no\">✗ The machine runs quiet.</p><p class=\"ok\">✓ The machine runs quietly.</p><small>ขยายกริยา runs ใช้ adverb -ly</small></div><div class=\"bv-m\"><p class=\"no\">✗ I always am late.</p><p class=\"ok\">✓ I am always late.</p><small>adverb ความถี่วางหลัง be</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ระวัง friendly, lovely, costly, likely ลงท้าย -ly แต่เป็น adjective (noun + -ly) เช่น a friendly team ถ้าจะใช้เป็น adverb ต้องพูดว่า in a friendly way</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The new robot works quickly and quietly. It usually finishes a batch in ten minutes, and it rarely makes mistakes.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The new robot works <mark>quickly</mark> and <mark>quietly</mark>. It <mark>usually</mark> finishes a batch in ten minutes, and it <mark>rarely</mark> makes mistakes.</div><div class=\"ts-th\">หุ่นยนต์ตัวใหม่ทำงานเร็วและเงียบ ปกติทำงานหนึ่งชุดเสร็จในสิบนาที และแทบไม่ผิดพลาด</div></div></div></div>","easy":{"say":"adverb ตอบคำถาม \"อย่างไร\" ส่วนใหญ่คือ adjective + -ly ภาษาไทยใช้คำเดียวกันได้ แต่ภาษาอังกฤษต้องเปลี่ยนรูป","eg":["a <b>careful</b> worker → works <b>carefully</b>","คนทำงานละเอียด → ทำงานอย่างละเอียด"],"rule":"ขยายกริยา = adverb (-ly) / good → well"}},{"id":"pron","en":"Pronouns","th":"คำสรรพนาม (pronoun)","intro":"สรรพนามใช้แทนคำนามเพื่อไม่ต้องพูดซ้ำ เลือกรูปให้ถูกตามตำแหน่ง: ประธาน กรรม เจ้าของ หรือสะท้อนกลับ","r":[],"tips":[],"items":[{"id":"wf-pron-0","p":0,"s":"Please send the report to Mr. Lee and _____.","gap":1,"o":{"A":"I","B":"me","C":"my","D":"mine"},"oth":{},"a":"B","x":"หลัง to (บุพบท) ใช้รูปกรรม me","v":[]},{"id":"wf-pron-1","p":0,"s":"The supplier changed _____ address last month.","gap":1,"o":{"A":"its","B":"it","C":"it's","D":"itself"},"oth":{},"a":"A","x":"its = ของมัน ตามด้วยคำนาม address","v":[]},{"id":"wf-pron-2","p":0,"s":"_____ team finished the project early.","gap":1,"o":{"A":"Theirs","B":"Their","C":"They","D":"Them"},"oth":{},"a":"B","x":"หน้าคำนาม team ใช้ Their","v":[]},{"id":"wf-pron-3","p":0,"s":"This laptop is not mine. It is _____.","gap":1,"o":{"A":"herself","B":"hers","C":"she","D":"her"},"oth":{},"a":"B","x":"ใช้แทนทั้ง \"her laptop\" ใช้ hers","v":[]},{"id":"wf-pron-4","p":0,"s":"The engineers solved the problem _____.","gap":1,"o":{"A":"them","B":"themselves","C":"theirselves","D":"themself"},"oth":{},"a":"B","x":"สะท้อนกลับของ they คือ themselves","v":[]},{"id":"wf-pron-5","p":0,"s":"Ms. Tan and _____ will attend the training.","gap":1,"o":{"A":"me","B":"I","C":"my","D":"myself"},"oth":{},"a":"B","x":"ตำแหน่งประธานหน้ากริยา will attend ใช้ I","v":[]},{"id":"wf-pron-6","p":0,"s":"Did you make the slides _____?","gap":1,"o":{"A":"yours","B":"yourselves","C":"your","D":"yourself"},"oth":{},"a":"D","x":"ทำเอง (คนเดียว) = yourself","v":[]},{"id":"wf-pron-7","p":0,"s":"_____ important to wear safety glasses.","gap":1,"o":{"A":"It's","B":"Itself","C":"It","D":"Its"},"oth":{},"a":"A","x":"It's = It is","v":[]}],"grp":"Parts of Speech — ชนิดของคำ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">สรรพนามเหมือน \"ตัวแทน\" ที่ยืนแทนคำนาม เพื่อไม่ต้องพูดชื่อซ้ำ ภาษาไทยใช้ \"เขา\" คำเดียวได้ทุกตำแหน่ง แต่ภาษาอังกฤษเปลี่ยนรูป: <b>he</b> (ประธาน) <b>him</b> (กรรม) <b>his</b> (ของเขา)</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ประธาน</th><th>กรรม</th><th>ของ... + noun</th><th>ของ... (แทนทั้งกลุ่ม)</th><th>...เอง</th></tr></thead><tbody><tr><td>I</td><td>me</td><td>my</td><td>mine</td><td>myself</td></tr><tr><td>you</td><td>you</td><td>your</td><td>yours</td><td>yourself</td></tr><tr><td>he</td><td>him</td><td>his</td><td>his</td><td>himself</td></tr><tr><td>she</td><td>her</td><td>her</td><td>hers</td><td>herself</td></tr><tr><td>it</td><td>it</td><td>its</td><td>-</td><td>itself</td></tr><tr><td>we</td><td>us</td><td>our</td><td>ours</td><td>ourselves</td></tr><tr><td>they</td><td>them</td><td>their</td><td>theirs</td><td>themselves</td></tr></tbody></table></div><figcaption>อ่านแนวนอนทีละแถว แล้วเลือกคอลัมน์ตามตำแหน่งในประโยค</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ประธาน</div><div class=\"tf-value\">I / he / they + verb</div></div><div class=\"tense-formula\"><div class=\"tf-label\">กรรม</div><div class=\"tf-value\">verb / preposition + me / him / them</div></div><div class=\"tense-formula\"><div class=\"tf-label\">เจ้าของ</div><div class=\"tf-value\">my / his / their + noun</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>ประธาน / กรรม</b> — I, you, he, she, it, we, they (หน้ากริยา) / me, you, him, her, it, us, them (หลังกริยาหรือบุพบท)<br><span class=\"bv-rx\"><b>She</b> sent <b>me</b> the file. <small>เธอส่งไฟล์ให้ฉัน</small></span></p><p><b>แสดงความเป็นเจ้าของ</b> — my, your, his, her, its, our, their + คำนาม / mine, yours, his, hers, ours, theirs ใช้แทนทั้งกลุ่ม<br><span class=\"bv-rx\">This is <b>our</b> report. That one is <b>theirs</b>. <small>นี่คือรายงานของเรา อันนั้นของพวกเขา</small></span></p><p><b>สะท้อนกลับ</b> — myself, yourself, himself, herself, itself, ourselves, themselves = ทำกับตัวเอง หรือ \"เอง\"<br><span class=\"bv-rx\">He fixed it <b>himself</b>. <small>เขาซ่อมมันเอง</small></span></p><p><b>its กับ it&#x27;s</b> — its = ของมัน / it's = it is หรือ it has<br><span class=\"bv-rx\">The machine and <b>its</b> parts <small>เครื่องและชิ้นส่วนของมัน</small></span><br><span class=\"bv-rx\"><b>It's</b> broken. <small>มันเสีย</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"They asked us for more samples.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">They asked us for more samples.</div><div class=\"ex-th thai\">พวกเขาขอตัวอย่างเพิ่มจากเรา</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Is this pen yours?\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Is this pen yours?</div><div class=\"ex-th thai\">ปากกานี้ของคุณหรือเปล่า</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The door locks itself at night.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The door locks itself at night.</div><div class=\"ex-th thai\">ประตูล็อกตัวเองตอนกลางคืน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Our customer approved their order.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Our customer approved their order.</div><div class=\"ex-th thai\">ลูกค้าของเราอนุมัติคำสั่งซื้อของพวกเขาแล้ว</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Me and John checked it.</p><p class=\"ok\">✓ John and I checked it.</p><small>ตำแหน่งประธานใช้ I และสุภาพกว่าถ้าวางตัวเองไว้หลัง</small></div><div class=\"bv-m\"><p class=\"no\">✗ The company and it&#x27;s staff</p><p class=\"ok\">✓ The company and its staff</p><small>its = ของมัน ไม่มี apostrophe</small></div><div class=\"bv-m\"><p class=\"no\">✗ Please contact to me.</p><p class=\"ok\">✓ Please contact me.</p><small>contact ตามด้วยกรรมได้เลย ไม่ต้องมี to</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ถ้าไม่แน่ใจว่า I หรือ me ให้ตัดอีกคนออกแล้วลองอ่าน: &quot;Send it to John and (I/me)&quot; → &quot;Send it to me&quot; จึงใช้ me</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Mr. Park called us this morning. His team needs our help, so we will visit them tomorrow. I will bring the samples myself.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">Mr. Park called <mark>us</mark> this morning. <mark>His</mark> team needs <mark>our</mark> help, so <mark>we</mark> will visit <mark>them</mark> tomorrow. <mark>I</mark> will bring the samples <mark>myself</mark>.</div><div class=\"ts-th\">คุณพาร์คโทรหาเราเมื่อเช้า ทีมของเขาต้องการความช่วยเหลือจากเรา เราจึงจะไปพบพวกเขาพรุ่งนี้ ฉันจะเอาตัวอย่างไปเอง</div></div></div></div>","easy":{"say":"สรรพนามคือ \"ตัวแทน\" ของคำนาม ภาษาไทยใช้รูปเดียว แต่ภาษาอังกฤษเปลี่ยนรูปตามตำแหน่ง","eg":["<b>He</b> called <b>me</b> about <b>his</b> order.","เขาโทรหาฉันเรื่องคำสั่งซื้อของเขา"],"rule":"หน้ากริยา = I/he/they · หลังกริยา = me/him/them · หน้าคำนาม = my/his/their"}},{"id":"prep","en":"Prepositions","th":"คำบุพบท (preposition)","intro":"บุพบทเป็นคำเล็กที่บอกเวลา ตำแหน่ง หรือความสัมพันธ์ และต้องตามด้วยคำนาม สรรพนาม หรือ V-ing เสมอ","r":[],"tips":[],"items":[{"id":"wf-prep-0","p":0,"s":"The meeting will start _____ 2 p.m.","gap":1,"o":{"A":"by","B":"at","C":"on","D":"in"},"oth":{},"a":"B","x":"เวลาแน่นอนใช้ at","v":[]},{"id":"wf-prep-1","p":0,"s":"The shipment will arrive _____ Friday.","gap":1,"o":{"A":"to","B":"on","C":"in","D":"at"},"oth":{},"a":"B","x":"วันในสัปดาห์ใช้ on","v":[]},{"id":"wf-prep-2","p":0,"s":"The factory opened _____ 2019.","gap":1,"o":{"A":"since","B":"on","C":"at","D":"in"},"oth":{},"a":"D","x":"ปีใช้ in","v":[]},{"id":"wf-prep-3","p":0,"s":"Thank you for _____ the documents so quickly.","gap":1,"o":{"A":"sending","B":"sent","C":"send","D":"to send"},"oth":{},"a":"A","x":"หลังบุพบท for ใช้ V-ing","v":[]},{"id":"wf-prep-4","p":0,"s":"Ms. Kim is responsible _____ the safety training.","gap":1,"o":{"A":"of","B":"for","C":"to","D":"with"},"oth":{},"a":"B","x":"responsible for = รับผิดชอบ","v":[]},{"id":"wf-prep-5","p":0,"s":"The delay was due _____ bad weather.","gap":1,"o":{"A":"by","B":"for","C":"of","D":"to"},"oth":{},"a":"D","x":"due to = เนื่องจาก","v":[]},{"id":"wf-prep-6","p":0,"s":"Please put the tools back _____ the drawer.","gap":1,"o":{"A":"at","B":"on","C":"in","D":"of"},"oth":{},"a":"C","x":"ข้างในลิ้นชักใช้ in","v":[]},{"id":"wf-prep-7","p":0,"s":"_____ starting the machine, check the oil level.","gap":1,"o":{"A":"Before","B":"Although","C":"Because","D":"Since"},"oth":{},"a":"A","x":"Before (บุพบท) + V-ing = ก่อนทำ...","v":[]}],"grp":"Parts of Speech — ชนิดของคำ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">บุพบทเหมือน \"ลูกศร\" ที่ชี้ว่าคำนามอยู่ตรงไหนหรือเมื่อไร ภาษาไทยมี \"ที่\" ใช้ได้เกือบทุกแบบ แต่ภาษาอังกฤษแยก <b>at / on / in</b> ตามขนาด: จุดเล็ก → พื้นผิว → พื้นที่ใหญ่</div><figure class=\"bv bv-nest\"><div class=\"bv-box\"><b>in</b><p><span>เวลา</span>ปี เดือน ช่วงเวลา: in 2026, in May, in the morning</p><p><span>สถานที่</span>พื้นที่ใหญ่ ข้างใน: in Thailand, in the box</p><div class=\"bv-box\"><b>on</b><p><span>เวลา</span>วัน วันที่: on Monday, on 5 May</p><p><span>สถานที่</span>บนพื้นผิว ถนน: on the table, on Sukhumvit Road</p><div class=\"bv-box\"><b>at</b><p><span>เวลา</span>เวลาแน่นอน: at 9:00, at noon</p><p><span>สถานที่</span>จุดเจาะจง: at the gate, at the station</p></div></div></div><figcaption>กรอบนอกใหญ่สุด กรอบในเล็กสุด: in &gt; on &gt; at</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">เวลา</div><div class=\"tf-value\">at 9:00 · on Monday · in May</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ตำแหน่ง</div><div class=\"tf-value\">at the gate · on the table · in the box</div></div><div class=\"tense-formula\"><div class=\"tf-label\">บุพบท + กริยา</div><div class=\"tf-value\">for / before / after + V-ing</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>เวลา: at / on / in</b> — at + เวลาแน่นอน (at 9:00) / on + วัน วันที่ (on Monday, on 5 May) / in + เดือน ปี ช่วงยาว (in May, in 2026)<br><span class=\"bv-rx\">The audit is <b>on</b> Monday <b>at</b> 10 a.m. <small>การตรวจประเมินคือวันจันทร์สิบโมง</small></span></p><p><b>ตำแหน่ง: at / on / in</b> — at = จุด (at the gate) / on = บนพื้นผิว (on the table) / in = ข้างใน (in the box)<br><span class=\"bv-rx\">The label is <b>on</b> the box <b>in</b> the warehouse. <small>ฉลากอยู่บนกล่องในโกดัง</small></span></p><p><b>บุพบท + V-ing</b> — หลังบุพบท ถ้าเป็นกริยาต้องเติม -ing<br><span class=\"bv-rx\">Thank you <b>for helping</b>. <small>ขอบคุณที่ช่วย</small></span><br><span class=\"bv-rx\"><b>Before installing</b>, turn off the power. <small>ก่อนติดตั้ง ให้ปิดไฟ</small></span></p><p><b>บุพบทที่มากับคำ (collocation)</b> — responsible for, interested in, depend on, according to, in charge of, due to<br><span class=\"bv-rx\">He is <b>in charge of</b> quality. <small>เขาดูแลเรื่องคุณภาพ</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The new line starts in January.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The new line starts in January.</div><div class=\"ex-th thai\">ไลน์ใหม่เริ่มเดือนมกราคม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The forklift is at the loading dock.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The forklift is at the loading dock.</div><div class=\"ex-th thai\">รถยกอยู่ที่ท่าขนของ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"According to the manual, the limit is 50 °C.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">According to the manual, the limit is 50 °C.</div><div class=\"ex-th thai\">ตามคู่มือ ค่าสูงสุดคือ 50 องศาเซลเซียส</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"After checking the parts, sign the form.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">After checking the parts, sign the form.</div><div class=\"ex-th thai\">หลังตรวจชิ้นส่วนแล้ว ให้เซ็นแบบฟอร์ม</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ in Monday</p><p class=\"ok\">✓ on Monday</p><small>วันในสัปดาห์ใช้ on</small></div><div class=\"bv-m\"><p class=\"no\">✗ I look forward to meet you.</p><p class=\"ok\">✓ I look forward to meeting you.</p><small>to ใน look forward to เป็นบุพบท ตามด้วย V-ing</small></div><div class=\"bv-m\"><p class=\"no\">✗ discuss about the plan</p><p class=\"ok\">✓ discuss the plan</p><small>discuss ตามด้วยกรรมได้เลย ไม่ต้องมี about</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> จำบุพบทเป็นคู่กับคำ ไม่ใช่จำทีละคำ เช่น depend on, interested in, responsible for เขียนรวมกันลงสมุดเป็นวลีเดียว</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The audit is on Tuesday at nine. Please be at the main gate before 8:45. After checking in, we will start in Building B.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The audit is <mark>on</mark> Tuesday <mark>at</mark> nine. Please be <mark>at</mark> the main gate <mark>before</mark> 8:45. <mark>After</mark> checking <mark>in</mark>, we will start <mark>in</mark> Building B.</div><div class=\"ts-th\">การตรวจประเมินคือวันอังคารเก้าโมง กรุณามาที่ประตูหลักก่อน 8:45 หลังลงชื่อแล้ว เราจะเริ่มที่อาคาร B</div></div></div></div>","easy":{"say":"บุพบทคือลูกศรชี้เวลาและตำแหน่ง ภาษาไทยใช้ \"ที่\" คำเดียว แต่ภาษาอังกฤษแยกตามขนาด: at (จุด) on (ผิว/วัน) in (ข้างใน/เดือน ปี)","eg":["<b>on</b> Monday <b>at</b> 9:00 <b>in</b> the meeting room","วันจันทร์ เก้าโมง ในห้องประชุม"],"rule":"at จุด · on ผิว/วัน · in ข้างใน/เดือน ปี + หลังบุพบทใช้ V-ing"}},{"id":"conj","en":"Conjunctions & linking words","th":"คำเชื่อม (conjunction) และคำเชื่อมความ","intro":"คำเชื่อมต่อคำหรือประโยคเข้าด้วยกัน และบอกความสัมพันธ์: เพิ่ม ขัดแย้ง เหตุ ผล หรือเวลา","r":[],"tips":[],"items":[{"id":"wf-conj-0","p":0,"s":"We stopped the line _____ the sensor was broken.","gap":1,"o":{"A":"although","B":"because of","C":"so","D":"because"},"oth":{},"a":"D","x":"ตามด้วยประโยค (the sensor was broken) ใช้ because","v":[]},{"id":"wf-conj-1","p":0,"s":"The flight was delayed _____ the storm.","gap":1,"o":{"A":"because of","B":"because","C":"although","D":"so that"},"oth":{},"a":"A","x":"ตามด้วยคำนาม (the storm) ใช้ because of","v":[]},{"id":"wf-conj-2","p":0,"s":"_____ the price is high, the quality is excellent.","gap":1,"o":{"A":"Because","B":"Unless","C":"So","D":"Although"},"oth":{},"a":"D","x":"สองความที่ขัดกัน ใช้ Although","v":[]},{"id":"wf-conj-3","p":0,"s":"The supplier was late. _____, we missed the deadline.","gap":1,"o":{"A":"As a result","B":"Although","C":"Unless","D":"However"},"oth":{},"a":"A","x":"ผลที่ตามมา ใช้ As a result","v":[]},{"id":"wf-conj-4","p":0,"s":"The new design is lighter _____ cheaper.","gap":1,"o":{"A":"so","B":"and","C":"but","D":"or"},"oth":{},"a":"B","x":"เพิ่มข้อดีสองอย่างที่ไปทางเดียวกัน ใช้ and","v":[]},{"id":"wf-conj-5","p":0,"s":"Do not open the cover _____ the power is off.","gap":1,"o":{"A":"because","B":"and","C":"unless","D":"so"},"oth":{},"a":"C","x":"unless = ถ้าไม่ (ห้ามเปิด ถ้าไฟยังไม่ปิด)","v":[]},{"id":"wf-conj-6","p":0,"s":"Sales increased. _____, profits fell.","gap":1,"o":{"A":"However","B":"Because","C":"Moreover","D":"Therefore"},"oth":{},"a":"A","x":"สองประโยคขัดกัน ใช้ However + comma","v":[]},{"id":"wf-conj-7","p":0,"s":"Please wait here _____ the manager arrives.","gap":1,"o":{"A":"although","B":"because of","C":"until","D":"unless"},"oth":{},"a":"C","x":"until = จนกระทั่ง","v":[]}],"grp":"Parts of Speech — ชนิดของคำ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">คำเชื่อมคือ \"ป้ายจราจร\" ของประโยค บอกผู้อ่านว่าความต่อไปจะไปทางเดิม (<b>and, moreover</b>) เลี้ยวกลับ (<b>but, however</b>) หรือเป็นผล (<b>so, therefore</b>) อ่านคำเชื่อมก่อน จะเดาความประโยคถัดไปได้</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ความหมาย</th><th>เชื่อมในประโยค</th><th>ต้นประโยคใหม่ (+ ,)</th></tr></thead><tbody><tr><td>เพิ่ม</td><td>and</td><td>Moreover, / In addition,</td></tr><tr><td>ขัดแย้ง</td><td>but / although</td><td>However, / Nevertheless,</td></tr><tr><td>เหตุ</td><td>because / since</td><td>-</td></tr><tr><td>ผล</td><td>so</td><td>Therefore, / As a result,</td></tr><tr><td>เงื่อนไข</td><td>if / unless</td><td>-</td></tr><tr><td>เวลา</td><td>when / while / until</td><td>Then, / After that,</td></tr></tbody></table></div><figcaption>เลือกคำเชื่อมจากความหมายก่อน แล้วดูตำแหน่ง</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">เหตุ</div><div class=\"tf-value\">because + ประโยค / because of + noun</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ขัดแย้ง</div><div class=\"tf-value\">although + ประโยค / despite + noun</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ระหว่างประโยค</div><div class=\"tf-value\">. However, + ประโยค</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>เชื่อมของที่เท่ากัน (FANBOYS)</b> — for, and, nor, but, or, yet, so<br><span class=\"bv-rx\">The test passed, <b>but</b> the report is late. <small>ทดสอบผ่านแล้ว แต่รายงานช้า</small></span></p><p><b>เชื่อมประโยคหลักกับประโยครอง</b> — because, although, while, when, if, unless, until, since + ประโยค (มีประธาน + กริยา)<br><span class=\"bv-rx\"><b>Although</b> it was expensive, we bought it. <small>แม้จะแพง เราก็ซื้อ</small></span></p><p><b>because กับ because of</b> — because + ประโยค / because of (และ due to) + คำนาม<br><span class=\"bv-rx\"><b>because</b> the road was closed / <b>because of</b> the road closure <small>เพราะถนนปิด</small></span></p><p><b>คำเชื่อมความระหว่างประโยค</b> — however, therefore, moreover, in addition, as a result เป็น adverb วางต้นประโยคตามด้วย comma<br><span class=\"bv-rx\">The cost rose. <b>However</b>, sales also increased. <small>ต้นทุนสูงขึ้น อย่างไรก็ตาม ยอดขายก็เพิ่มขึ้นด้วย</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The parts arrived, so we started production.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The parts arrived, so we started production.</div><div class=\"ex-th thai\">ชิ้นส่วนมาถึงแล้ว เราจึงเริ่มผลิต</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"While the machine is running, do not open the door.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">While the machine is running, do not open the door.</div><div class=\"ex-th thai\">ขณะเครื่องทำงาน ห้ามเปิดประตู</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Despite the delay, we finished on time.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Despite the delay, we finished on time.</div><div class=\"ex-th thai\">แม้จะล่าช้า เราก็เสร็จทันเวลา</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The test failed. Therefore, we checked the wiring.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The test failed. Therefore, we checked the wiring.</div><div class=\"ex-th thai\">การทดสอบไม่ผ่าน เราจึงตรวจการเดินสาย</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Because of the machine was old, ...</p><p class=\"ok\">✓ Because the machine was old, ...</p><small>ตามด้วยประโยคใช้ because</small></div><div class=\"bv-m\"><p class=\"no\">✗ Although it was late, but we finished.</p><p class=\"ok\">✓ Although it was late, we finished.</p><small>ใช้ although กับ but ในประโยคเดียวกันไม่ได้</small></div><div class=\"bv-m\"><p class=\"no\">✗ The cost rose, however sales increased.</p><p class=\"ok\">✓ The cost rose. However, sales increased.</p><small>however เป็น adverb เชื่อมสองประโยคด้วย comma อย่างเดียวไม่ได้</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ข้อสอบชอบให้เลือกระหว่าง because / because of, although / despite ดูว่าหลังช่องว่างเป็น &quot;ประโยค&quot; (มีกริยา) หรือ &quot;คำนาม&quot;</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The order was urgent, so we worked overtime. Although the team was tired, everyone stayed. As a result, we shipped on time.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The order was urgent, <mark>so</mark> we worked overtime. <mark>Although</mark> the team was tired, everyone stayed. <mark>As a result</mark>, we shipped on time.</div><div class=\"ts-th\">คำสั่งซื้อด่วน เราจึงทำงานล่วงเวลา แม้ทีมจะเหนื่อย ทุกคนก็อยู่ต่อ ผลคือเราส่งของได้ทันเวลา</div></div></div></div>","easy":{"say":"คำเชื่อมคือป้ายจราจรของประโยค: and ไปต่อ, but / however เลี้ยวกลับ, so / therefore ผลลัพธ์","eg":["It was late, <b>but</b> we finished. <b>Therefore</b>, ...","ช้า แต่เราก็เสร็จ ดังนั้น..."],"rule":"หลังช่องเป็นประโยค = because / although · เป็นคำนาม = because of / despite"}},{"id":"det","en":"Determiners & articles","th":"คำนำหน้านาม (a / an / the, this, some, each)","intro":"determiner วางหน้าคำนามเพื่อบอกว่าเจาะจงหรือไม่ มีเท่าไร หรือของใคร","r":[],"tips":[],"items":[{"id":"wf-det-0","p":0,"s":"Please wait for _____ hour.","gap":1,"o":{"A":"the","B":"a","C":"-","D":"an"},"oth":{},"a":"D","x":"hour ไม่ออกเสียง h ขึ้นต้นด้วยเสียงสระ ใช้ an","v":[]},{"id":"wf-det-1","p":0,"s":"She works for _____ European company.","gap":1,"o":{"A":"an","B":"any","C":"the","D":"a"},"oth":{},"a":"D","x":"European ขึ้นต้นด้วยเสียง /j/ (ยู) ใช้ a","v":[]},{"id":"wf-det-2","p":0,"s":"_____ employee must wear a badge.","gap":1,"o":{"A":"All","B":"Every","C":"Both","D":"Many"},"oth":{},"a":"B","x":"Every + คำนามเอกพจน์ (employee)","v":[]},{"id":"wf-det-3","p":0,"s":"_____ samples on this table are rejected.","gap":1,"o":{"A":"Every","B":"This","C":"Each","D":"These"},"oth":{},"a":"D","x":"samples พหูพจน์และอยู่ใกล้ ใช้ These","v":[]},{"id":"wf-det-4","p":0,"s":"We don't have _____ spare parts left.","gap":1,"o":{"A":"a","B":"any","C":"every","D":"some"},"oth":{},"a":"B","x":"ประโยคปฏิเสธใช้ any","v":[]},{"id":"wf-det-5","p":0,"s":"_____ machines are new, the old one and the new one.","gap":1,"o":{"A":"Every","B":"Each","C":"Either","D":"Both"},"oth":{},"a":"D","x":"Both = ทั้งสอง ตามด้วยพหูพจน์","v":[]},{"id":"wf-det-6","p":0,"s":"Each of the reports _____ checked by the manager.","gap":1,"o":{"A":"is","B":"were","C":"be","D":"are"},"oth":{},"a":"A","x":"Each ... เป็นเอกพจน์ ใช้ is","v":[]},{"id":"wf-det-7","p":0,"s":"I bought a new printer. _____ printer is very fast.","gap":1,"o":{"A":"Some","B":"A","C":"An","D":"The"},"oth":{},"a":"D","x":"พูดถึงเครื่องเดิมเป็นครั้งที่สอง ใช้ The","v":[]}],"grp":"Parts of Speech — ชนิดของคำ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">determiner เหมือน \"ป้ายหน้าร้าน\" ที่บอกก่อนว่าคำนามข้างหลังคือ <b>อันไหน</b> และ <b>เท่าไร</b> ภาษาไทยมักไม่ใส่ (ซื้อเครื่องพิมพ์) แต่ภาษาอังกฤษต้องใส่ (bought <b>a</b> printer / <b>the</b> printer)</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>คำ</th><th>ใช้กับ</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>a / an</td><td>นับได้ เอกพจน์ ไม่เจาะจง</td><td>a tool, an hour</td></tr><tr><td>the</td><td>ทุกแบบ เมื่อรู้ว่าอันไหน</td><td>the tool, the tools</td></tr><tr><td>this / that</td><td>เอกพจน์</td><td>this box</td></tr><tr><td>these / those</td><td>พหูพจน์</td><td>these boxes</td></tr><tr><td>each / every</td><td>เอกพจน์</td><td>every worker</td></tr><tr><td>all / both</td><td>พหูพจน์</td><td>all workers, both sides</td></tr><tr><td>some / any</td><td>พหูพจน์ / นับไม่ได้</td><td>some water, any parts</td></tr></tbody></table></div><figcaption>ดูคำนามข้างหลังว่าเอกพจน์ พหูพจน์ หรือนับไม่ได้ แล้วเลือกคำ</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ไม่เจาะจง</div><div class=\"tf-value\">a / an + noun เอกพจน์</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ทุกอัน (ทีละอัน)</div><div class=\"tf-value\">each / every + noun เอกพจน์ + is</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ทั้งหมด</div><div class=\"tf-value\">all + noun พหูพจน์ + are</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>a / an / the</b> — a / an = หนึ่งอัน ยังไม่เจาะจง (ดูเสียงขึ้นต้น) / the = รู้กันว่าอันไหน<br><span class=\"bv-rx\"><b>an</b> hour, <b>a</b> unit, <b>the</b> unit we ordered</span></p><p><b>this / that / these / those</b> — this, these = ใกล้ / that, those = ไกล / these, those ใช้กับพหูพจน์<br><span class=\"bv-rx\"><b>These</b> boxes are heavy. <small>กล่องพวกนี้หนัก</small></span></p><p><b>some / any / no</b> — some บอกเล่า / any ปฏิเสธและคำถาม / no = ไม่มีเลย<br><span class=\"bv-rx\">Are there <b>any</b> questions? <small>มีคำถามไหม</small></span></p><p><b>each / every / all / both</b> — each, every + เอกพจน์ / all + พหูพจน์หรือนับไม่ได้ / both = ทั้งสอง<br><span class=\"bv-rx\"><b>Each</b> part <b>is</b> checked. <small>ทุกชิ้นได้รับการตรวจ</small></span><br><span class=\"bv-rx\"><b>All</b> parts <b>are</b> checked.</span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"An engineer will visit the site.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">An engineer will visit the site.</div><div class=\"ex-th thai\">วิศวกรคนหนึ่งจะไปที่หน้างาน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Every box has a label.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Every box has a label.</div><div class=\"ex-th thai\">ทุกกล่องมีฉลาก</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Those cables are too short.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Those cables are too short.</div><div class=\"ex-th thai\">สายพวกนั้นสั้นเกินไป</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"There is no time left.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">There is no time left.</div><div class=\"ex-th thai\">ไม่มีเวลาเหลือแล้ว</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Every workers must sign.</p><p class=\"ok\">✓ Every worker must sign.</p><small>every ตามด้วยเอกพจน์</small></div><div class=\"bv-m\"><p class=\"no\">✗ He is engineer.</p><p class=\"ok\">✓ He is an engineer.</p><small>อาชีพเอกพจน์ต้องมี a / an</small></div><div class=\"bv-m\"><p class=\"no\">✗ This samples are OK.</p><p class=\"ok\">✓ These samples are OK.</p><small>พหูพจน์ใช้ these</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> เลือก a หรือ an จาก &quot;เสียง&quot; ไม่ใช่ตัวอักษร: an hour (ไม่ออกเสียง h), a uniform (ขึ้นต้นเสียง ยู), an MBA (ขึ้นต้นเสียง เอ็ม)</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Every operator received a new badge. The badges open all doors in this building, but no badge opens the server room.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\"><mark>Every</mark> operator received <mark>a</mark> new badge. <mark>The</mark> badges open <mark>all</mark> doors in <mark>this</mark> building, but <mark>no</mark> badge opens <mark>the</mark> server room.</div><div class=\"ts-th\">พนักงานทุกคนได้บัตรใหม่ บัตรเปิดได้ทุกประตูในอาคารนี้ แต่ไม่มีบัตรไหนเปิดห้องเซิร์ฟเวอร์ได้</div></div></div></div>","easy":{"say":"คำนำหน้านามบอกว่าคำนามคือ \"อันไหน\" และ \"เท่าไร\" ภาษาไทยไม่ต้องใส่ แต่ภาษาอังกฤษต้องใส่หน้าคำนามนับได้เอกพจน์","eg":["<b>a</b> printer → <b>the</b> printer","เครื่องพิมพ์เครื่องหนึ่ง → เครื่องนั้น"],"rule":"each / every + เอกพจน์ · all / both / these + พหูพจน์"}},{"id":"multi","en":"One word, many parts of speech","th":"คำเดียวหลายชนิด (conversion)","intro":"คำอังกฤษจำนวนมากเป็นได้หลายชนิดโดยไม่เปลี่ยนรูป ดูชนิดจากตำแหน่งในประโยค ไม่ใช่จากตัวคำ","r":[],"tips":[],"items":[{"id":"wf-multi-0","p":0,"s":"ในประโยค \"Please order more screws.\" คำว่า order เป็นคำชนิดใด?","gap":0,"o":{"A":"adverb","B":"noun","C":"adjective","D":"verb"},"oth":{},"a":"D","x":"ขึ้นต้นประโยคคำสั่ง ตามด้วยกรรม more screws จึงเป็น verb","v":[]},{"id":"wf-multi-1","p":0,"s":"ในประโยค \"The order arrived today.\" คำว่า order เป็นคำชนิดใด?","gap":0,"o":{"A":"adverb","B":"adjective","C":"verb","D":"noun"},"oth":{},"a":"D","x":"หลัง The และเป็นประธานของ arrived จึงเป็น noun","v":[]},{"id":"wf-multi-2","p":0,"s":"ในวลี \"a safety check\" คำว่า safety ทำหน้าที่อะไร?","gap":0,"o":{"A":"เป็นประธาน","B":"เป็นกริยา","C":"เป็น adverb","D":"ขยายคำนาม check (เหมือน adjective)"},"oth":{},"a":"D","x":"คำนามวางหน้าคำนามอื่นเพื่อขยาย เช่น safety check, quality control","v":[]},{"id":"wf-multi-3","p":0,"s":"คำว่า \"increase\" ที่เป็น noun เน้นเสียงพยางค์ไหน?","gap":0,"o":{"A":"พยางค์แรก IN-crease","B":"พยางค์หลัง in-CREASE","C":"เน้นเท่ากัน","D":"ไม่เน้น"},"oth":{},"a":"A","x":"คำสองพยางค์แบบนี้ noun เน้นหน้า verb เน้นหลัง","v":[]},{"id":"wf-multi-4","p":0,"s":"ในประโยค \"The bus arrived late.\" คำว่า late เป็นคำชนิดใด?","gap":0,"o":{"A":"verb","B":"noun","C":"adverb","D":"adjective"},"oth":{},"a":"C","x":"ขยายกริยา arrived และ late ไม่เติม -ly (lately แปลว่า เร็วๆ นี้)","v":[]},{"id":"wf-multi-5","p":0,"s":"ประโยคใดใช้ \"schedule\" เป็น verb?","gap":0,"o":{"A":"We will schedule the meeting for Monday.","B":"a busy schedule","C":"The schedule is on the wall.","D":"Check your schedule."},"oth":{},"a":"A","x":"หลัง will ต้องเป็น verb","v":[]},{"id":"wf-multi-6","p":0,"s":"ในประโยค \"They ship orders daily.\" คำว่า daily เป็นคำชนิดใด?","gap":0,"o":{"A":"noun","B":"adverb","C":"verb","D":"adjective"},"oth":{},"a":"B","x":"บอกความถี่ของกริยา ship จึงเป็น adverb (ในวลี a daily report เป็น adjective)","v":[]},{"id":"wf-multi-7","p":0,"s":"คำว่า \"present\" ที่แปลว่า \"นำเสนอ\" เน้นเสียงอย่างไร?","gap":0,"o":{"A":"PRE-sent (พยางค์แรก)","B":"ไม่ออกเสียง t","C":"pre-SENT (พยางค์หลัง)","D":"เน้นเท่ากัน"},"oth":{},"a":"C","x":"verb เน้นพยางค์หลัง ส่วน PRE-sent (noun/adj) = ของขวัญ / ปัจจุบัน","v":[]}],"grp":"Parts of Speech — ชนิดของคำ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">ภาษาอังกฤษชอบ \"ยืมตำแหน่ง\" คำเดียวสวมได้หลายหมวก: <b>test</b> เป็นทั้ง \"การทดสอบ\" และ \"ทดสอบ\" สิ่งที่บอกชนิดคือ <b>ตำแหน่ง</b> ในประโยค เหมือนคนคนเดียวเป็นได้ทั้งพ่อ ลูก และหัวหน้า ขึ้นกับว่าอยู่ที่ไหน</div><figure class=\"bv bv-blocks\"><div class=\"bv-row\"><span class=\"bv-rl\">noun</span><div class=\"bv-chips\"><span class=\"bv-chip r-X\"><b>The</b></span><span class=\"bv-chip r-S\"><b>test</b><i>ประธาน</i></span><span class=\"bv-chip r-V\"><b>passed</b><i>กริยา</i></span></div></div><div class=\"bv-row\"><span class=\"bv-rl\">verb</span><div class=\"bv-chips\"><span class=\"bv-chip r-S\"><b>We</b><i>ประธาน</i></span><span class=\"bv-chip r-V\"><b>test</b><i>กริยา</i></span><span class=\"bv-chip r-O\"><b>every unit</b><i>กรรม</i></span></div></div><div class=\"bv-row\"><span class=\"bv-rl\">ขยายคำนาม</span><div class=\"bv-chips\"><span class=\"bv-chip r-X\"><b>a</b></span><span class=\"bv-chip r-A\"><b>test</b><i>คำขยาย</i></span><span class=\"bv-chip r-O\"><b>report</b><i>กรรม</i></span></div></div><figcaption>คำเดียวกัน ตำแหน่งต่างกัน ชนิดก็ต่างกัน</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>คำ</th><th>noun (เน้นหน้า)</th><th>verb (เน้นหลัง)</th></tr></thead><tbody><tr><td>record</td><td>REcord บันทึก</td><td>reCORD บันทึกไว้</td></tr><tr><td>increase</td><td>INcrease การเพิ่ม</td><td>inCREASE เพิ่มขึ้น</td></tr><tr><td>present</td><td>PREsent ของขวัญ</td><td>preSENT นำเสนอ</td></tr><tr><td>import</td><td>IMport สินค้านำเข้า</td><td>imPORT นำเข้า</td></tr><tr><td>object</td><td>OBject วัตถุ</td><td>obJECT คัดค้าน</td></tr></tbody></table></div><figcaption>เสียงเน้นช่วยแยกชนิดเวลาฟัง</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">หลัง a / the</div><div class=\"tf-value\">คำนั้นเป็น noun</div></div><div class=\"tense-formula\"><div class=\"tf-label\">หลังประธาน / to / will</div><div class=\"tf-value\">คำนั้นเป็น verb</div></div><div class=\"tense-formula\"><div class=\"tf-label\">noun + noun</div><div class=\"tf-value\">คำแรกขยายคำหลัง (safety check)</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>noun = verb (รูปเดียวกัน)</b> — email, test, check, order, change, report, plan, ship, schedule<br><span class=\"bv-rx\">Please <b>email</b> me the <b>email</b> address. <small>กรุณาอีเมลที่อยู่อีเมลมาให้ฉัน</small></span><br><span class=\"bv-rx\">We <b>tested</b> it. The <b>test</b> passed. <small>เราทดสอบแล้ว การทดสอบผ่าน</small></span></p><p><b>ดูจากคำรอบข้าง</b> — หลัง a / the → noun / หลังประธานหรือ to → verb / หน้าคำนาม → ทำหน้าที่ adjective<br><span class=\"bv-rx\">a <b>quality</b> check (quality ขยาย check) <small>การตรวจคุณภาพ</small></span></p><p><b>เน้นเสียงเปลี่ยนตามชนิด</b> — คำสองพยางค์บางคำ: noun เน้นหน้า / verb เน้นหลัง<br><span class=\"bv-rx\">a <b>RE</b>cord / to re<b>CORD</b> <small>บันทึก (น.) / บันทึก (ก.)</small></span><br><span class=\"bv-rx\">an <b>IN</b>crease / to in<b>CREASE</b> <small>การเพิ่มขึ้น / เพิ่มขึ้น</small></span></p><p><b>adjective ที่เป็น adverb ได้</b> — fast, hard, early, late, daily, monthly<br><span class=\"bv-rx\">a <b>fast</b> printer / It prints <b>fast</b>.</span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please check the voltage. The check takes five minutes.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please check the voltage. The check takes five minutes.</div><div class=\"ex-th thai\">กรุณาตรวจแรงดัน การตรวจใช้เวลาห้านาที</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We will ship the order on Monday.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We will ship the order on Monday.</div><div class=\"ex-th thai\">เราจะส่งของวันจันทร์</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Sales showed a 5% increase.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Sales showed a 5% increase.</div><div class=\"ex-th thai\">ยอดขายเพิ่มขึ้นห้าเปอร์เซ็นต์</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Prices increased last year.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Prices increased last year.</div><div class=\"ex-th thai\">ราคาเพิ่มขึ้นเมื่อปีที่แล้ว</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Please send me a email.</p><p class=\"ok\">✓ Please send me an email.</p><small>email ขึ้นต้นด้วยเสียงสระ ใช้ an</small></div><div class=\"bv-m\"><p class=\"no\">✗ He arrived lately.</p><p class=\"ok\">✓ He arrived late.</p><small>late (adv.) = สาย / lately = เร็วๆ นี้</small></div><div class=\"bv-m\"><p class=\"no\">✗ We need to increasing production.</p><p class=\"ok\">✓ We need to increase production.</p><small>หลัง to ใช้กริยารูปเดิม</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> เวลาเปิดพจนานุกรม ให้ดูทุกชนิดของคำ (n., v., adj.) คำเดียวอาจมีความหมายต่างกันตามชนิด เช่น plant (n.) = โรงงาน / พืช, plant (v.) = ปลูก</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Our plan is simple: we plan each order carefully, order parts early and test every unit before the final test report.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">Our <mark>plan</mark> is simple: we <mark>plan</mark> each <mark>order</mark> carefully, <mark>order</mark> parts early and <mark>test</mark> every unit before the final <mark>test</mark> report.</div><div class=\"ts-th\">แผนของเราง่าย: เราวางแผนแต่ละคำสั่งซื้ออย่างละเอียด สั่งชิ้นส่วนแต่เนิ่นๆ และทดสอบทุกเครื่องก่อนทำรายงานผลทดสอบฉบับสุดท้าย</div></div></div></div>","easy":{"say":"คำเดียวเป็นได้หลายชนิด ดูตำแหน่ง: หลัง a / the = noun หลังประธานหรือ to = verb","eg":["The <b>test</b> passed. / We <b>test</b> it.","การทดสอบผ่าน / เราทดสอบมัน"],"rule":"ชนิดของคำขึ้นกับตำแหน่ง ไม่ใช่ตัวคำ"}},{"id":"slot","en":"Choosing the right word form","th":"เลือกรูปคำให้ถูกตำแหน่ง (ข้อสอบ Part 5)","intro":"ข้อสอบ TOEIC Part 5 มักให้คำเดียวกันสี่รูป (noun, verb, adjective, adverb) ดูตำแหน่งของช่องว่างแล้วเลือกรูปได้โดยไม่ต้องแปลทั้งประโยค","r":[],"tips":[],"items":[{"id":"wf-slot-0","p":0,"s":"The manager praised the team for its _____ work.","gap":1,"o":{"A":"excel","B":"excellence","C":"excellently","D":"excellent"},"oth":{},"a":"D","x":"its + __ + noun (work) → adjective: excellent","v":[]},{"id":"wf-slot-1","p":0,"s":"The machine was _____ designed for small parts.","gap":1,"o":{"A":"specifically","B":"specification","C":"specific","D":"specify"},"oth":{},"a":"A","x":"ระหว่าง was กับ designed (V3) ใช้ adverb: specifically","v":[]},{"id":"wf-slot-2","p":0,"s":"All visitors must show _____ at the gate.","gap":1,"o":{"A":"identify","B":"identical","C":"identifiable","D":"identification"},"oth":{},"a":"D","x":"show + __ (กรรมของกริยา) → noun: identification","v":[]},{"id":"wf-slot-3","p":0,"s":"The new policy is _____ to all employees.","gap":1,"o":{"A":"apply","B":"applicable","C":"application","D":"applicably"},"oth":{},"a":"B","x":"is + __ + to → adjective: applicable","v":[]},{"id":"wf-slot-4","p":0,"s":"We need to _____ the cost of shipping.","gap":1,"o":{"A":"reductive","B":"reduction","C":"reduced","D":"reduce"},"oth":{},"a":"D","x":"to + __ → verb รูปเดิม: reduce","v":[]},{"id":"wf-slot-5","p":0,"s":"The _____ of the report is next Friday.","gap":1,"o":{"A":"submissive","B":"submission","C":"submit","D":"submitted"},"oth":{},"a":"B","x":"The + __ + of → noun: submission","v":[]},{"id":"wf-slot-6","p":0,"s":"Ms. Lin answered the questions _____.","gap":1,"o":{"A":"confidently","B":"confident","C":"confidence","D":"confide"},"oth":{},"a":"A","x":"หลังกรรม ขยายกริยา answered → adverb: confidently","v":[]},{"id":"wf-slot-7","p":0,"s":"Thank you for your _____ to detail.","gap":1,"o":{"A":"attention","B":"attend","C":"attentive","D":"attentively"},"oth":{},"a":"A","x":"your + __ → noun และ attention to detail = ความใส่ใจรายละเอียด","v":[]},{"id":"wf-slot-8","p":0,"s":"ในครอบครัวคำ \"similar\" คำใดเป็น adjective (คำคุณศัพท์)?","gap":0,"o":{"A":"passport","B":"similarly","C":"similar","D":"similarity"},"oth":{},"a":"C","x":"similar (คล้ายกัน) เป็น adjective (คำคุณศัพท์)","v":[]},{"id":"wf-slot-9","p":0,"s":"ในครอบครัวคำ \"true\" คำใดเป็น adjective (คำคุณศัพท์)?","gap":0,"o":{"A":"meal","B":"true","C":"truly","D":"truth"},"oth":{},"a":"B","x":"true (จริง) เป็น adjective (คำคุณศัพท์)","v":[]},{"id":"wf-slot-10","p":0,"s":"ในครอบครัวคำ \"sure\" คำใดเป็น adjective (คำคุณศัพท์)?","gap":0,"o":{"A":"enthusiasm","B":"sure","C":"surely","D":"ensure"},"oth":{},"a":"B","x":"sure (แน่ใจ) เป็น adjective (คำคุณศัพท์)","v":[]},{"id":"wf-slot-11","p":0,"s":"ในครอบครัวคำ \"offend\" คำใดเป็น verb (คำกริยา)?","gap":0,"o":{"A":"offend","B":"offensive","C":"offence","D":"ancient"},"oth":{},"a":"A","x":"offend (ทำให้ขุ่นเคือง) เป็น verb (คำกริยา)","v":[]}],"grp":"Parts of Speech — ชนิดของคำ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">ข้อสอบรูปคำ (word form) คือ \"ข้อแจกคะแนน\" เพราะไม่ต้องแปลทั้งประโยค แค่ดู <b>เพื่อนบ้าน</b> ของช่องว่าง 1–2 คำ เหมือนดูป้ายที่จอดรถว่าช่องนี้สำหรับรถแบบไหน</div><figure class=\"bv bv-steps\"><ol><li>ดูคำหน้าและหลังช่องว่าง</li><li>บอกได้ว่าช่องต้องการ noun / verb / adjective / adverb</li><li>ดู suffix ของตัวเลือกทั้งสี่</li><li>ถ้ายังเหลือสองตัว ดูความหมาย (คน กับ สิ่ง)</li></ol><figcaption>สี่ขั้นนี้ทำได้ในไม่ถึง 15 วินาที</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>รูปแบบรอบช่องว่าง</th><th>ต้องการ</th></tr></thead><tbody><tr><td>a / the / your ___ (of)</td><td>noun</td></tr><tr><td>a / the ___ noun</td><td>adjective</td></tr><tr><td>be / seem / become ___</td><td>adjective</td></tr><tr><td>ประธาน ___ (กรรม)</td><td>verb</td></tr><tr><td>to / can / will ___</td><td>verb รูปเดิม</td></tr><tr><td>___ verb / verb (กรรม) ___</td><td>adverb</td></tr><tr><td>be ___ V3 / V-ing</td><td>adverb</td></tr></tbody></table></div><figcaption>จำตารางนี้ แล้วข้อ word form จะง่ายขึ้นมาก</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">noun</div><div class=\"tf-value\">the ___ of</div></div><div class=\"tense-formula\"><div class=\"tf-label\">adjective</div><div class=\"tf-value\">the ___ noun / be ___</div></div><div class=\"tense-formula\"><div class=\"tf-label\">adverb</div><div class=\"tf-value\">be ___ V3 / verb ___</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>ขั้นที่ 1: ดูคำหน้าและหลังช่อง</b> — a / the / your + __ + of → noun / a / the + __ + noun → adjective / be + __ → adjective / __ + verb หรือ verb + __ → adverb</p><p><b>ขั้นที่ 2: ดู suffix ของตัวเลือก</b> — noun: -tion -ment -ness -ity -ance / adj: -ful -ous -ive -able -al / adv: -ly / verb: -ize -ify -en -ate</p><p><b>ขั้นที่ 3: ถ้ามีสองตัวชนิดเดียวกัน</b> — ค่อยดูความหมาย เช่น คน (-er, -ee, -ant) กับ สิ่ง (-tion, -ance)<br><span class=\"bv-rx\">assistant (ผู้ช่วย) / assistance (ความช่วยเหลือ)</span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The proposal was carefully reviewed.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The proposal was carefully reviewed.</div><div class=\"ex-th thai\">ข้อเสนอได้รับการพิจารณาอย่างละเอียด</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Her presentation was very informative.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Her presentation was very informative.</div><div class=\"ex-th thai\">การนำเสนอของเธอให้ข้อมูลดีมาก</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We received confirmation of the order.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We received confirmation of the order.</div><div class=\"ex-th thai\">เราได้รับการยืนยันคำสั่งซื้อแล้ว</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The device is easy to operate.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The device is easy to operate.</div><div class=\"ex-th thai\">อุปกรณ์ใช้งานง่าย</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ a success project</p><p class=\"ok\">✓ a successful project</p><small>หน้าคำนามใช้ adjective</small></div><div class=\"bv-m\"><p class=\"no\">✗ It was complete finished.</p><p class=\"ok\">✓ It was completely finished.</p><small>ระหว่าง be กับ V3 ใช้ adverb</small></div><div class=\"bv-m\"><p class=\"no\">✗ the inform of the customer</p><p class=\"ok\">✓ the information for the customer</p><small>หลัง the ใช้ noun (information)</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ตัวเลือกที่ลงท้าย -ly มักถูกเมื่อช่องว่างอยู่ระหว่าง be กับ V3 (is carefully checked) หรือหลังกรรม (answered the call politely)</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The successful team worked efficiently. Their efficiency impressed the director, who publicly thanked them for their dedication.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The <mark>successful</mark> team worked <mark>efficiently</mark>. Their <mark>efficiency</mark> impressed the director, who <mark>publicly</mark> thanked them for their <mark>dedication</mark>.</div><div class=\"ts-th\">ทีมที่ประสบความสำเร็จทำงานอย่างมีประสิทธิภาพ ประสิทธิภาพของพวกเขาทำให้ผู้อำนวยการประทับใจ และขอบคุณพวกเขาต่อหน้าทุกคนสำหรับความทุ่มเท</div></div></div></div>","easy":{"say":"ข้อเลือกรูปคำ ไม่ต้องแปลทั้งประโยค ดูแค่คำที่อยู่ติดช่องว่าง แล้วดูท้ายคำของตัวเลือก","eg":["the ___ of → <b>installation</b> · be ___ checked → <b>carefully</b>",""],"rule":"ดูเพื่อนบ้านของช่อง → รู้ชนิด → เลือกจาก suffix"}},{"id":"affix","en":"What are prefixes and suffixes?","th":"คำเติมหน้า คำเติมท้าย คืออะไร","intro":"คำยาวส่วนใหญ่สร้างจากคำสั้นบวกส่วนเติม: prefix อยู่หน้า เปลี่ยนความหมาย / suffix อยู่ท้าย มักเปลี่ยนชนิดของคำ","r":[],"tips":[],"items":[{"id":"wf-affix-0","p":0,"s":"ใน \"unhappiness\" ส่วนใดเป็น prefix?","gap":0,"o":{"A":"happy","B":"un-","C":"happi-","D":"-ness"},"oth":{},"a":"B","x":"un- อยู่หน้าคำและเปลี่ยนความหมายเป็นตรงข้าม","v":[]},{"id":"wf-affix-1","p":0,"s":"ใน \"employment\" ส่วนใดเป็น suffix?","gap":0,"o":{"A":"ploy","B":"employ","C":"-ment","D":"em-"},"oth":{},"a":"C","x":"-ment อยู่ท้ายคำ ทำให้ employ (v.) กลายเป็น noun","v":[]},{"id":"wf-affix-2","p":0,"s":"หน้าที่หลักของ suffix คืออะไร?","gap":0,"o":{"A":"บอก tense เท่านั้น","B":"เปลี่ยนความหมายเป็นตรงข้ามเสมอ","C":"ไม่มีหน้าที่","D":"เปลี่ยนชนิดของคำ"},"oth":{},"a":"D","x":"suffix เช่น -tion, -ful, -ly เปลี่ยนชนิดของคำ","v":[]},{"id":"wf-affix-3","p":0,"s":"คำใดเกิดจาก prefix + base?","gap":0,"o":{"A":"rewrite","B":"written","C":"writer","D":"writing"},"oth":{},"a":"A","x":"re- (อีกครั้ง) + write (เขียน)","v":[]},{"id":"wf-affix-4","p":0,"s":"คำใดเกิดจาก base + suffix?","gap":0,"o":{"A":"teacher","B":"preteach","C":"reteach","D":"unteach"},"oth":{},"a":"A","x":"teach + -er (ผู้ทำ) = ครู","v":[]},{"id":"wf-affix-5","p":0,"s":"\"disconnect\" แปลว่าอะไร ถ้า dis- = ไม่/แยก และ connect = เชื่อมต่อ?","gap":0,"o":{"A":"เชื่อมต่อมากเกินไป","B":"เชื่อมต่อใหม่","C":"ผู้เชื่อมต่อ","D":"ตัดการเชื่อมต่อ"},"oth":{},"a":"D","x":"dis- (แยก) + connect (เชื่อม) = ตัดการเชื่อมต่อ","v":[]},{"id":"wf-affix-6","p":0,"s":"ข้อใดเป็น root (ราก) ที่ใช้เดี่ยวเป็นคำไม่ได้?","gap":0,"o":{"A":"care ใน careful","B":"happy ใน unhappy","C":"dict (พูด) ใน predict","D":"read ใน reread"},"oth":{},"a":"C","x":"dict มาจากภาษาละติน dicere ใช้เดี่ยวไม่ได้ ต่างจาก happy, read, care ที่เป็นคำปกติ","v":[]},{"id":"wf-affix-7","p":0,"s":"\"rechargeable\" แยกส่วนได้อย่างไร?","gap":0,"o":{"A":"re- + chargeable-","B":"recharge + -ble","C":"rech + arge + able","D":"re- + charge + -able"},"oth":{},"a":"D","x":"re- (อีกครั้ง) + charge (ชาร์จ) + -able (...ได้) = ชาร์จใหม่ได้","v":[]},{"id":"wf-affix-8","p":0,"s":"คำว่า \"beneficial\" (เป็นประโยชน์) แยกส่วนอย่างไรจึงถูกต้อง?","gap":0,"o":{"A":"benefi + ci + al","B":"ben + eficia + l","C":"bene- + fic + -ial","D":"ben + efi + cial"},"oth":{},"a":"C","x":"beneficial = bene- + fic + -ial (ดี + ทำ + เกี่ยวกับ...)","v":[]},{"id":"wf-affix-9","p":0,"s":"คำว่า \"personally\" (ด้วยตนเอง) แยกส่วนอย่างไรจึงถูกต้อง?","gap":0,"o":{"A":"person + -al + -ly","B":"perso + na + lly","C":"perso + nall + y","D":"pers + on + ally"},"oth":{},"a":"A","x":"personally = person + -al + -ly (person + เกี่ยวกับ... + อย่าง...)","v":[]},{"id":"wf-affix-10","p":0,"s":"คำว่า \"administration\" (การบริหาร) แยกส่วนอย่างไรจึงถูกต้อง?","gap":0,"o":{"A":"ad- + ministr + -ation","B":"admi + nist + ration","C":"adm + inistrat + ion","D":"admi + nis + tration"},"oth":{},"a":"A","x":"administration = ad- + ministr + -ation (ไปยัง + เล็ก + การ... / สิ่งที่...)","v":[]},{"id":"wf-affix-11","p":0,"s":"คำว่า \"assumption\" (การสันนิษฐาน) แยกส่วนอย่างไรจึงถูกต้อง?","gap":0,"o":{"A":"ass + u + mption","B":"a + ssu + mption","C":"assu + mpti + on","D":"as- + sump + -tion"},"oth":{},"a":"D","x":"assumption = as- + sump + -tion (ไปยัง + เอา + การ... / สิ่งที่...)","v":[]}],"grp":"Prefixes & Suffixes — คำเติมหน้าและคำเติมท้าย","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">คำศัพท์เหมือน <b>ตัวต่อเลโก้</b> ตัวต่อชิ้นกลาง (base / root) ให้ความหมายหลัก ชิ้นหน้า (prefix) หมุนความหมาย ชิ้นหลัง (suffix) เปลี่ยนชนิดของคำ รู้ตัวต่อ 50 ชิ้น อ่านคำได้เป็นพันคำ</div><figure class=\"bv bv-parts\"><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">unemployment</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">un</b><small>ไม่</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-b\"><b lang=\"en\">employ</b><small>จ้าง</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ment</b><small>การ...</small></span></span><span class=\"wp-th\">การว่างงาน</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">rechargeable</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">re</b><small>อีกครั้ง</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-b\"><b lang=\"en\">charge</b><small>ชาร์จ</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">able</b><small>...ได้</small></span></span><span class=\"wp-th\">ชาร์จใหม่ได้</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">disconnection</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">dis</b><small>แยก</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-b\"><b lang=\"en\">connect</b><small>เชื่อม</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ion</b><small>การ...</small></span></span><span class=\"wp-th\">การตัดการเชื่อมต่อ</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">predict</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">pre</b><small>ก่อน</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">dict</b><small>พูด</small></span></span><span class=\"wp-th\">พูดก่อน = ทำนาย</span></div><figcaption>สีฟ้า = prefix · สีเขียว = แกน (base/root) · สีส้ม = suffix</figcaption></figure><figure class=\"bv bv-steps\"><ol><li>หาแกนกลาง (คำที่รู้จัก หรือราก)</li><li>ดู prefix ข้างหน้า: เปลี่ยนความหมายอย่างไร</li><li>ดู suffix ข้างหลัง: เป็นคำชนิดไหน</li><li>รวมความหมาย แล้วตรวจกับประโยค</li></ol><figcaption>วิธีแยกคำใหม่ 4 ขั้น</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">prefix</div><div class=\"tf-value\">อยู่หน้า → เปลี่ยนความหมาย</div></div><div class=\"tense-formula\"><div class=\"tf-label\">base / root</div><div class=\"tf-value\">แกน → ความหมายหลัก</div></div><div class=\"tense-formula\"><div class=\"tf-label\">suffix</div><div class=\"tf-value\">อยู่ท้าย → เปลี่ยนชนิดของคำ</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>base / root = แกนกลาง</b> — ส่วนที่มีความหมายหลัก อาจเป็นคำที่ใช้เดี่ยวได้ (base: employ) หรือรากละติน-กรีกที่ใช้เดี่ยวไม่ได้ (root: port, dict)<br><span class=\"bv-rx\">employ → <b>un</b>employ<b>ment</b> <small>จ้าง → การว่างงาน</small></span></p><p><b>prefix เปลี่ยนความหมาย</b> — ชนิดของคำมักไม่เปลี่ยน<br><span class=\"bv-rx\"><b>un</b>happy (adj.) · <b>re</b>write (v.) · <b>pre</b>view (n./v.) <small>ไม่มีความสุข · เขียนใหม่ · ดูตัวอย่างก่อน</small></span></p><p><b>suffix เปลี่ยนชนิดของคำ</b> — ทำให้กลายเป็น noun, verb, adjective หรือ adverb<br><span class=\"bv-rx\">employ (v.) → employ<b>ment</b> (n.) → employ<b>able</b> (adj.) <small>จ้าง → การจ้างงาน → จ้างได้</small></span></p><p><b>ใช้แยกคำใหม่</b> — แยกเป็นส่วน → รู้ความหมายแต่ละส่วน → เดาความหมายรวม → ตรวจกับบริบท<br><span class=\"bv-rx\">dis + connect + ion = disconnection <small>ไม่ + เชื่อม + การ = การตัดการเชื่อมต่อ</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The battery is rechargeable.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The battery is rechargeable.</div><div class=\"ex-th thai\">แบตเตอรี่ชาร์จใหม่ได้</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Unemployment fell this year.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Unemployment fell this year.</div><div class=\"ex-th thai\">อัตราการว่างงานลดลงปีนี้</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please disconnect the cable first.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please disconnect the cable first.</div><div class=\"ex-th thai\">กรุณาถอดสายก่อน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Can you predict the result?\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Can you predict the result?</div><div class=\"ex-th thai\">คุณทำนายผลได้ไหม</div></div></div></div><h3 class=\"bv-h\">กับดักที่พบบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ ตีความ &quot;invaluable&quot; ว่า &quot;ไม่มีค่า&quot;</p><p class=\"ok\">✓ invaluable = มีค่ามากจนประเมินไม่ได้</p><small>in- + value + -able = ประเมินค่าไม่ได้ (เพราะมีค่ามาก) ต้องตรวจกับบริบทเสมอ</small></div><div class=\"bv-m\"><p class=\"no\">✗ แยก &quot;uncle&quot; เป็น un- + cle</p><p class=\"ok\">✓ uncle เป็นคำพื้นฐาน ไม่มี prefix</p><small>ส่วนที่เหลือต้องมีความหมาย ถ้าแยกแล้วเหลือส่วนที่ไม่มีความหมาย แปลว่าแยกผิด</small></div><div class=\"bv-m\"><p class=\"no\">✗ แยก &quot;carpet&quot; เป็น car + pet</p><p class=\"ok\">✓ carpet เป็นคำเดียว (พรม)</p><small>คำที่ &quot;ดูเหมือน&quot; สองคำต่อกันไม่ได้เป็นคำประสมเสมอ</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ในแอปนี้ หน้าคลังคำแสดงส่วนประกอบของทุกคำที่แยกได้ และบอกตรงๆ ว่าคำไหนเป็นคำพื้นฐานที่แยกไม่ได้ ลองค้นหาด้วย &quot;un-&quot; หรือ &quot;-tion&quot; เพื่อดูคำทั้งหมดที่มีส่วนนั้น</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The new rechargeable battery is unbreakable and lightweight. The manufacturer says it is reusable for five years.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The new <mark>rechargeable</mark> battery is <mark>unbreakable</mark> and <mark>lightweight</mark>. The <mark>manufacturer</mark> says it is <mark>reusable</mark> for five years.</div><div class=\"ts-th\">แบตเตอรี่แบบชาร์จใหม่ได้รุ่นใหม่ทนทานไม่แตก และน้ำหนักเบา ผู้ผลิตบอกว่าใช้ซ้ำได้ห้าปี</div></div></div></div>","easy":{"say":"คำยาวคือตัวต่อเลโก้: ชิ้นหน้า (prefix) เปลี่ยนความหมาย ชิ้นกลางคือความหมายหลัก ชิ้นหลัง (suffix) เปลี่ยนชนิดของคำ","eg":["<b>re</b> + charge + <b>able</b> = rechargeable","อีกครั้ง + ชาร์จ + ได้ = ชาร์จใหม่ได้"],"rule":"prefix เปลี่ยนความหมาย · suffix เปลี่ยนชนิดคำ"}},{"id":"neg","en":"Negative prefixes","th":"prefix ความหมาย \"ไม่\" (un-, in-, dis-, non-, mis-)","intro":"prefix กลุ่มนี้ทำให้ความหมายตรงข้ามหรือผิดไป เป็นกลุ่มที่พบบ่อยที่สุดในข้อสอบและในงาน","r":[],"tips":[],"items":[{"id":"wf-neg-0","p":0,"s":"ตรงข้ามของ \"possible\" คือคำใด?","gap":0,"o":{"A":"impossible","B":"inpossible","C":"unpossible","D":"dispossible"},"oth":{},"a":"A","x":"p ขึ้นต้น ใช้ im-","v":[]},{"id":"wf-neg-1","p":0,"s":"ตรงข้ามของ \"legal\" คือคำใด?","gap":0,"o":{"A":"unlegal","B":"illegal","C":"inlegal","D":"dislegal"},"oth":{},"a":"B","x":"l ขึ้นต้น ใช้ il-","v":[]},{"id":"wf-neg-2","p":0,"s":"ตรงข้ามของ \"regular\" คือคำใด?","gap":0,"o":{"A":"inregular","B":"unregular","C":"disregular","D":"irregular"},"oth":{},"a":"D","x":"r ขึ้นต้น ใช้ ir-","v":[]},{"id":"wf-neg-3","p":0,"s":"\"misread\" แปลว่าอะไร?","gap":0,"o":{"A":"อ่านผิด","B":"ไม่อ่าน","C":"อ่านก่อน","D":"อ่านอีกครั้ง"},"oth":{},"a":"A","x":"mis- = ผิด","v":[]},{"id":"wf-neg-4","p":0,"s":"The ticket is _____; you cannot get your money back.","gap":1,"o":{"A":"misrefundable","B":"unrefundable","C":"disrefundable","D":"nonrefundable"},"oth":{},"a":"D","x":"non- + refundable = ขอคืนเงินไม่ได้ (คำที่ใช้จริงในเอกสาร)","v":[]},{"id":"wf-neg-5","p":0,"s":"Please _____ the cable before cleaning.","gap":1,"o":{"A":"unconnect","B":"disconnect","C":"misconnect","D":"inconnect"},"oth":{},"a":"B","x":"dis- + connect = ตัดการเชื่อมต่อ","v":[]},{"id":"wf-neg-6","p":0,"s":"\"unpack the box\" แปลว่าอะไร?","gap":0,"o":{"A":"ไม่บรรจุกล่อง","B":"แกะของออกจากกล่อง","C":"บรรจุกล่องใหม่","D":"บรรจุกล่องผิด"},"oth":{},"a":"B","x":"un- + กริยา = ทำย้อนกลับ","v":[]},{"id":"wf-neg-7","p":0,"s":"ข้อใดเป็นข้อเสีย?","gap":0,"o":{"A":"misadvantage","B":"advantage","C":"readvantage","D":"disadvantage"},"oth":{},"a":"D","x":"dis- + advantage = ข้อเสีย","v":[]},{"id":"wf-neg-8","p":0,"s":"\"unfailing\" = un- + fail + -ing แปลว่าอะไร? (un- = ไม่ / ตรงข้าม)","gap":0,"o":{"A":"ไม่เห็นด้วย","B":"ไม่ดีต่อสุขภาพ","C":"ไม่เคยเปลี่ยน","D":"ไม่ได้ล็อก"},"oth":{},"a":"C","x":"unfailing = un- + fail + -ing → ไม่เคยเปลี่ยน","v":[]},{"id":"wf-neg-9","p":0,"s":"\"dislike\" = dis- + like แปลว่าอะไร? (dis- = ไม่ / ตรงข้าม / แยกออก)","gap":0,"o":{"A":"ไม่ชอบ","B":"ไม่จำกัด","C":"เข้าใจผิด","D":"ความเข้าใจผิด"},"oth":{},"a":"A","x":"dislike = dis- + like → ไม่ชอบ","v":[]},{"id":"wf-neg-10","p":0,"s":"\"unoccupied\" = un- + occupied แปลว่าอะไร? (un- = ไม่ / ตรงข้าม)","gap":0,"o":{"A":"เข้าใจผิด","B":"ว่าง (ไม่มีคน)","C":"ปลดล็อก","D":"ข้อเสียเปรียบ"},"oth":{},"a":"B","x":"unoccupied = un- + occupied → ว่าง (ไม่มีคน)","v":[]},{"id":"wf-neg-11","p":0,"s":"\"unlock\" = un- + lock แปลว่าอะไร? (un- = ไม่ / ตรงข้าม)","gap":0,"o":{"A":"ไม่น่าพึงพอใจ","B":"กางออก","C":"ขุดพบ","D":"ปลดล็อก"},"oth":{},"a":"D","x":"unlock = un- + lock → ปลดล็อก","v":[]}],"grp":"Prefixes & Suffixes — คำเติมหน้าและคำเติมท้าย","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">prefix ปฏิเสธเหมือน <b>สวิตช์กลับขั้ว</b> กดหนึ่งครั้ง ความหมายกลับด้าน: safe → <b>un</b>safe, connect → <b>dis</b>connect ส่วน <b>mis-</b> ไม่ได้แปลว่าไม่ แต่แปลว่า \"ทำผิด\"</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>prefix</th><th>ความหมาย</th><th>ใช้กับ</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>un-</td><td>ไม่ / ย้อน</td><td>adj., v.</td><td>unsafe, unlock</td></tr><tr><td>in- / im- / il- / ir-</td><td>ไม่</td><td>adj. (ละติน)</td><td>incorrect, impossible, illegal, irregular</td></tr><tr><td>dis-</td><td>ไม่ / แยก</td><td>v., n., adj.</td><td>disagree, disconnect</td></tr><tr><td>non-</td><td>ไม่ใช่</td><td>n., adj.</td><td>nonstop, nonfood</td></tr><tr><td>mis-</td><td>ผิด</td><td>v., n.</td><td>misread, mistake</td></tr></tbody></table></div><figcaption>กลุ่ม &quot;ไม่&quot; และ &quot;ผิด&quot;</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ตัวถัดไป</th><th>ใช้</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>b, m, p</td><td>im-</td><td>imbalance, immature, impossible</td></tr><tr><td>l</td><td>il-</td><td>illegal, illogical</td></tr><tr><td>r</td><td>ir-</td><td>irregular, irrelevant</td></tr><tr><td>อื่นๆ</td><td>in-</td><td>incorrect, inaccurate</td></tr></tbody></table></div><figcaption>in- เปลี่ยนรูปให้ออกเสียงง่าย</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ตรงข้าม</div><div class=\"tf-value\">un- / in- / dis- + คำ</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ย้อนการกระทำ</div><div class=\"tf-value\">un- / dis- + กริยา (unlock, disconnect)</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ทำผิด</div><div class=\"tf-value\">mis- + กริยา (misread)</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>un-</b> — ไม่ / ตรงข้าม ใช้กับ adjective และกริยา (un- + กริยา = ย้อนการกระทำ)<br><span class=\"bv-rx\"><b>un</b>clear, <b>un</b>safe, <b>un</b>lock, <b>un</b>pack <small>ไม่ชัด, ไม่ปลอดภัย, ปลดล็อก, แกะของ</small></span></p><p><b>in- / im- / il- / ir-</b> — ไม่ เปลี่ยนรูปตามตัวอักษรถัดไป: im- หน้า b m p, il- หน้า l, ir- หน้า r<br><span class=\"bv-rx\"><b>in</b>correct, <b>im</b>possible, <b>il</b>legal, <b>ir</b>regular <small>ไม่ถูก, เป็นไปไม่ได้, ผิดกฎหมาย, ไม่สม่ำเสมอ</small></span></p><p><b>dis-</b> — ไม่ / ตรงข้าม / แยกออก ใช้กับกริยาและคำนามบ่อย<br><span class=\"bv-rx\"><b>dis</b>agree, <b>dis</b>connect, <b>dis</b>advantage <small>ไม่เห็นด้วย, ตัดการเชื่อมต่อ, ข้อเสีย</small></span></p><p><b>non- และ mis-</b> — non- = ไม่ใช่ (เป็นกลางกว่า un-) / mis- = ผิด พลาด<br><span class=\"bv-rx\"><b>non</b>-stop, <b>non</b>refundable / <b>mis</b>understand, <b>mis</b>print <small>ไม่หยุด, ขอคืนเงินไม่ได้ / เข้าใจผิด, พิมพ์ผิด</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The instructions are unclear.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The instructions are unclear.</div><div class=\"ex-th thai\">คำแนะนำไม่ชัดเจน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"This measurement is inaccurate.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">This measurement is inaccurate.</div><div class=\"ex-th thai\">การวัดนี้ไม่แม่นยำ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"I misunderstood the email.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">I misunderstood the email.</div><div class=\"ex-th thai\">ฉันเข้าใจอีเมลผิด</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The train runs nonstop to the airport.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The train runs nonstop to the airport.</div><div class=\"ex-th thai\">รถไฟวิ่งตรงไม่จอดไปสนามบิน</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดและกับดัก</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ unpossible</p><p class=\"ok\">✓ impossible</p><small>possible มาจากละติน ใช้ im-</small></div><div class=\"bv-m\"><p class=\"no\">✗ dislike = ไม่ชอบมากๆ</p><p class=\"ok\">✓ dislike = ไม่ชอบ</p><small>dis- แค่กลับความหมาย</small></div><div class=\"bv-m\"><p class=\"no\">✗ inflammable = ไม่ติดไฟ</p><p class=\"ok\">✓ inflammable = ติดไฟง่าย (เหมือน flammable)</p><small>in- ในคำนี้ไม่ได้แปลว่าไม่ ระวังป้ายเตือนสารเคมี!</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ระวัง inflammable = flammable = ติดไฟได้ ส่วนที่ไม่ติดไฟคือ nonflammable ในโรงงานป้ายนี้สำคัญมาก</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The label was incorrect, so the operator misread the part number. The parts were unusable, and we had to disconnect the line.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The label was <mark>incorrect</mark>, so the operator <mark>misread</mark> the part number. The parts were <mark>unusable</mark>, and we had to <mark>disconnect</mark> the line.</div><div class=\"ts-th\">ฉลากไม่ถูกต้อง พนักงานจึงอ่านหมายเลขชิ้นส่วนผิด ชิ้นส่วนใช้ไม่ได้ และเราต้องตัดไลน์</div></div></div></div>","easy":{"say":"prefix กลุ่มนี้เหมือนสวิตช์กลับขั้ว: un-, in-, dis-, non- = ไม่ / ตรงข้าม ส่วน mis- = ทำผิด","eg":["<b>un</b>safe · <b>im</b>possible · <b>dis</b>connect · <b>mis</b>read","ไม่ปลอดภัย · เป็นไปไม่ได้ · ตัดการเชื่อมต่อ · อ่านผิด"],"rule":"im- หน้า b m p · il- หน้า l · ir- หน้า r"}},{"id":"where","en":"Prefixes of time, place and degree","th":"prefix บอกเวลา ตำแหน่ง และระดับ","intro":"prefix กลุ่มนี้บอกว่า \"เมื่อไร\" (ก่อน หลัง อีกครั้ง) \"ที่ไหน\" (ใต้ เหนือ ระหว่าง ข้าม ออก) หรือ \"มากน้อยแค่ไหน\"","r":[],"tips":[],"items":[{"id":"wf-where-0","p":0,"s":"\"preheat the oven\" แปลว่าอะไร?","gap":0,"o":{"A":"อุ่นเตาอีกครั้ง","B":"อุ่นเตาก่อน","C":"อุ่นเตามากเกินไป","D":"ไม่อุ่นเตา"},"oth":{},"a":"B","x":"pre- = ก่อน","v":[]},{"id":"wf-where-1","p":0,"s":"The meeting was _____ until next week.","gap":1,"o":{"A":"preponed","B":"overponed","C":"reponed","D":"postponed"},"oth":{},"a":"D","x":"post- (หลัง) + pone (วาง) = เลื่อนออกไป","v":[]},{"id":"wf-where-2","p":0,"s":"If the motor runs too long, it may _____.","gap":1,"o":{"A":"reheat","B":"underheat","C":"preheat","D":"overheat"},"oth":{},"a":"D","x":"over- = มากเกิน","v":[]},{"id":"wf-where-3","p":0,"s":"We _____ our products to 20 countries.","gap":1,"o":{"A":"export","B":"transport","C":"import","D":"support"},"oth":{},"a":"A","x":"ex- (ออก) + port (ขน) = ส่งออก","v":[]},{"id":"wf-where-4","p":0,"s":"ผู้ที่ \"supervise\" คนอื่นคือใคร?","gap":0,"o":{"A":"ผู้ที่ทำงานใต้คนอื่น","B":"ผู้ที่มองไปข้างหลัง","C":"ผู้ที่ดูแลจากข้างบน (หัวหน้างาน)","D":"ผู้ที่ทำงานระหว่างแผนก"},"oth":{},"a":"C","x":"super- (เหนือ) + vise (มองเห็น) = ดูแลจากข้างบน","v":[]},{"id":"wf-where-5","p":0,"s":"\"intercompany\" หมายถึงอะไร?","gap":0,"o":{"A":"บริษัทย่อย","B":"ภายในบริษัทเดียว","C":"นอกบริษัท","D":"ระหว่างบริษัท"},"oth":{},"a":"D","x":"inter- = ระหว่าง","v":[]},{"id":"wf-where-6","p":0,"s":"We _____ the cost; it was much higher than we thought.","gap":1,"o":{"A":"underestimated","B":"reestimated","C":"overestimated","D":"preestimated"},"oth":{},"a":"A","x":"ต้นทุนจริงสูงกว่าที่คิด = เราประเมินต่ำไป (under-)","v":[]},{"id":"wf-where-7","p":0,"s":"คำใดแปลว่า \"พยากรณ์ / คาดการณ์ล่วงหน้า\"?","gap":0,"o":{"A":"outcast","B":"forecast","C":"overcast","D":"recast"},"oth":{},"a":"B","x":"fore- (ล่วงหน้า) + cast (โยน) = คาดการณ์","v":[]},{"id":"wf-where-8","p":0,"s":"\"overpriced\" = over- + priced แปลว่าอะไร? (over- = มากเกิน / ข้างบน)","gap":0,"o":{"A":"ชาร์จไฟใหม่","B":"ทรัพยากร","C":"แพงเกินไป","D":"ข้อจำกัด"},"oth":{},"a":"C","x":"overpriced = over- + priced → แพงเกินไป","v":[]},{"id":"wf-where-9","p":0,"s":"\"misunderstand\" = mis- + under- + stand แปลว่าอะไร? (under- = น้อยเกิน / ข้างใต้)","gap":0,"o":{"A":"ปูผิวถนนใหม่","B":"เติมสินค้า","C":"การต่ออายุ","D":"เข้าใจผิด"},"oth":{},"a":"D","x":"misunderstand = mis- + under- + stand → เข้าใจผิด","v":[]},{"id":"wf-where-10","p":0,"s":"\"understandable\" = under- + stand + -able แปลว่าอะไร? (under- = น้อยเกิน / ข้างใต้)","gap":0,"o":{"A":"คำพูด","B":"ยอดรวมย่อย","C":"ฟื้นฟู","D":"เข้าใจได้"},"oth":{},"a":"D","x":"understandable = under- + stand + -able → เข้าใจได้","v":[]},{"id":"wf-where-11","p":0,"s":"\"overnight\" = over- + night แปลว่าอะไร? (over- = มากเกิน / ข้างบน)","gap":0,"o":{"A":"คืน (สินค้า)","B":"ค้างคืน","C":"การติดตั้งใหม่","D":"กลางแจ้ง"},"oth":{},"a":"B","x":"overnight = over- + night → ค้างคืน","v":[]}],"grp":"Prefixes & Suffixes — คำเติมหน้าและคำเติมท้าย","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">prefix กลุ่มนี้เหมือน <b>ลูกศรบนแผนที่</b>: pre- ชี้ไปข้างหน้า (ก่อน) post- ชี้ไปข้างหลัง sub- ชี้ลง super- ชี้ขึ้น trans- ข้ามฝั่ง ex- ออกนอก รู้ลูกศร เดาความหมายได้ทันที</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>prefix</th><th>ลูกศร</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>pre-</td><td>ก่อน ⏪</td><td>prepare, preview, prepaid</td></tr><tr><td>post-</td><td>หลัง ⏩</td><td>postpone, postwar</td></tr><tr><td>re-</td><td>อีกครั้ง / กลับ ↻</td><td>restart, return, recycle</td></tr><tr><td>sub-</td><td>ใต้ / ย่อย ⬇</td><td>subway, subtotal, subcontract</td></tr><tr><td>super-</td><td>เหนือ ⬆</td><td>supervise, supermarket</td></tr><tr><td>inter-</td><td>ระหว่าง ↔</td><td>interview, international</td></tr><tr><td>trans-</td><td>ข้าม →</td><td>transport, transfer, translate</td></tr><tr><td>ex- / in-</td><td>ออก / เข้า</td><td>export / import</td></tr><tr><td>over- / under-</td><td>มากเกิน / น้อยเกิน</td><td>overload / underpaid</td></tr></tbody></table></div><figcaption>ลูกศรช่วยจำทิศทางของความหมาย</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">เวลา</div><div class=\"tf-value\">pre- · post- · fore- · re-</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ตำแหน่ง</div><div class=\"tf-value\">sub- · super- · inter- · trans- · ex- · in-</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ระดับ</div><div class=\"tf-value\">over- · under- · out-</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>เวลา</b> — pre- (ก่อน), post- (หลัง), fore- (ล่วงหน้า), re- (อีกครั้ง / กลับ)<br><span class=\"bv-rx\"><b>pre</b>view, <b>post</b>pone, <b>fore</b>cast, <b>re</b>start <small>ดูก่อน, เลื่อนไปหลัง, พยากรณ์, เริ่มใหม่</small></span></p><p><b>ตำแหน่ง</b> — sub- (ใต้ / ย่อย), super- (เหนือ), inter- (ระหว่าง), trans- (ข้าม), ex- (ออก), in- / im- (เข้า)<br><span class=\"bv-rx\"><b>sub</b>way, <b>super</b>vise, <b>inter</b>national, <b>trans</b>port, <b>ex</b>port, <b>im</b>port</span></p><p><b>ระดับ</b> — over- (มากเกิน), under- (น้อยเกิน), out- (เหนือกว่า / ออก)<br><span class=\"bv-rx\"><b>over</b>heat, <b>under</b>estimate, <b>out</b>perform <small>ร้อนเกิน, ประเมินต่ำไป, ทำได้ดีกว่า</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please preview the file before printing.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please preview the file before printing.</div><div class=\"ex-th thai\">กรุณาดูตัวอย่างไฟล์ก่อนพิมพ์</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We subcontract the painting work.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We subcontract the painting work.</div><div class=\"ex-th thai\">เราจ้างช่วงงานพ่นสี</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The truck transports parts between plants.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The truck transports parts between plants.</div><div class=\"ex-th thai\">รถบรรทุกขนชิ้นส่วนระหว่างโรงงาน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Do not overload the circuit.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Do not overload the circuit.</div><div class=\"ex-th thai\">อย่าใช้วงจรเกินกำลัง</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ repeat again</p><p class=\"ok\">✓ repeat</p><small>re- แปลว่าอีกครั้งอยู่แล้ว ไม่ต้องมี again</small></div><div class=\"bv-m\"><p class=\"no\">✗ return back</p><p class=\"ok\">✓ return</p><small>re- = กลับ อยู่แล้ว</small></div><div class=\"bv-m\"><p class=\"no\">✗ postpone = เตรียมการ</p><p class=\"ok\">✓ postpone = เลื่อนออกไป</p><small>post- = หลัง (คนละความหมายกับ prepare)</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> re- ทำคำใหม่ได้เกือบทุกกริยา: recheck, reinstall, reorder, retest เจอคำที่ไม่เคยเห็นแต่ขึ้นต้น re- ให้ลองแปลว่า &quot;...อีกครั้ง&quot;</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Before the audit, we prepared all documents. The supervisor rechecked them, and we transferred the files to the international team.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">Before the audit, we <mark>pre</mark>pared all documents. The <mark>super</mark>visor <mark>re</mark>checked them, and we <mark>trans</mark>ferred the files to the <mark>inter</mark>national team.</div><div class=\"ts-th\">ก่อนการตรวจประเมิน เราเตรียมเอกสารทั้งหมด หัวหน้างานตรวจซ้ำ แล้วเราส่งไฟล์ไปให้ทีมต่างประเทศ</div></div></div></div>","easy":{"say":"prefix กลุ่มนี้เหมือนลูกศร: pre- ก่อน, post- หลัง, re- อีกครั้ง, sub- ใต้, super- เหนือ, inter- ระหว่าง, trans- ข้าม, over- มากเกิน","eg":["<b>re</b>start · <b>ex</b>port · <b>over</b>heat","เริ่มใหม่ · ส่งออก · ร้อนเกิน"],"rule":"นึกลูกศรทิศทาง แล้วเดาความหมาย"}},{"id":"num","en":"Number and size prefixes","th":"prefix บอกจำนวนและขนาด","intro":"prefix ตัวเลขใช้มากในงานเทคนิค หน่วยวัด และชื่อผลิตภัณฑ์ จำครั้งเดียวใช้ได้ตลอด","r":[],"tips":[],"items":[{"id":"wf-num-0","p":0,"s":"\"bilingual\" หมายถึงอะไร?","gap":0,"o":{"A":"พูดได้สองภาษา","B":"ไม่พูด","C":"พูดได้สามภาษา","D":"พูดได้ภาษาเดียว"},"oth":{},"a":"A","x":"bi- = สอง, lingu = ภาษา","v":[]},{"id":"wf-num-1","p":0,"s":"1 milliampere (mA) เท่ากับกี่แอมแปร์?","gap":0,"o":{"A":"0.01 A","B":"1,000,000 A","C":"0.001 A","D":"1,000 A"},"oth":{},"a":"C","x":"milli- = หนึ่งในพัน","v":[]},{"id":"wf-num-2","p":0,"s":"1 kilowatt เท่ากับกี่วัตต์?","gap":0,"o":{"A":"1,000 W","B":"1,000,000 W","C":"100 W","D":"0.001 W"},"oth":{},"a":"A","x":"kilo- = พัน","v":[]},{"id":"wf-num-3","p":0,"s":"\"semiconductor\" แปลตามส่วนประกอบว่าอะไร?","gap":0,"o":{"A":"ตัวนำสองตัว","B":"ตัวนำขนาดใหญ่","C":"ไม่นำไฟฟ้า","D":"ตัวนำครึ่งๆ กลางๆ (สารกึ่งตัวนำ)"},"oth":{},"a":"D","x":"semi- = ครึ่ง/กึ่ง + conductor = ตัวนำ","v":[]},{"id":"wf-num-4","p":0,"s":"\"tripod\" มีกี่ขา?","gap":0,"o":{"A":"หนึ่ง","B":"สี่","C":"สาม","D":"สอง"},"oth":{},"a":"C","x":"tri- = สาม, pod = เท้า","v":[]},{"id":"wf-num-5","p":0,"s":"เครื่องวัดที่วัดได้หลายค่า (V, A, Ω) เรียกว่าอะไร?","gap":0,"o":{"A":"semimeter","B":"bimeter","C":"monometer","D":"multimeter"},"oth":{},"a":"D","x":"multi- = หลาย + meter = เครื่องวัด","v":[]},{"id":"wf-num-6","p":0,"s":"1 µm (micrometre) เล็กกว่า 1 mm กี่เท่า?","gap":0,"o":{"A":"1,000,000 เท่า","B":"100 เท่า","C":"1,000 เท่า","D":"10 เท่า"},"oth":{},"a":"C","x":"micro = 1/1,000,000 m, milli = 1/1,000 m จึงต่างกัน 1,000 เท่า","v":[]},{"id":"wf-num-7","p":0,"s":"\"monorail\" คืออะไร?","gap":0,"o":{"A":"รถไฟสองราง","B":"รถไฟใต้ดิน","C":"รถไฟรางเดี่ยว","D":"รถไฟหลายราง"},"oth":{},"a":"C","x":"mono- = หนึ่งเดียว","v":[]},{"id":"wf-num-8","p":0,"s":"\"semiretired\" = semi- + retire + -ed แปลว่าอะไร? (semi- = ครึ่ง / กึ่ง)","gap":0,"o":{"A":"อุปกรณ์ยึด (จำกัดการเคลื่อนที่)","B":"ห้องปฏิบัติการ","C":"เกษียณกึ่งหนึ่ง (ยังทำงานบางส่วน)","D":"สำคัญยิ่ง"},"oth":{},"a":"C","x":"semiretired = semi- + retire + -ed → เกษียณกึ่งหนึ่ง (ยังทำงานบางส่วน)","v":[]},{"id":"wf-num-9","p":0,"s":"\"multilayer\" = multi- + lay + -er แปลว่าอะไร? (multi- = หลาย)","gap":0,"o":{"A":"วงดนตรี","B":"หลายชั้น","C":"เขต","D":"วงกลม"},"oth":{},"a":"B","x":"multilayer = multi- + lay + -er → หลายชั้น","v":[]}],"grp":"Prefixes & Suffixes — คำเติมหน้าและคำเติมท้าย","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">prefix ตัวเลขคือ \"<b>เลขรหัส</b>\" ที่ซ่อนอยู่ในคำ bicycle มีสองล้อ (bi = 2) triangle มีสามมุม (tri = 3) ในงานไฟฟ้า mA, kW, µm ใช้ prefix ชุดเดียวกัน</div><figure class=\"bv bv-scale\"><div class=\"bv-sr\"><span class=\"bv-sw\">mega- (M)</span><span class=\"bv-sb\"><i style=\"width:100%\"></i></span><span class=\"bv-st\">1,000,000</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">kilo- (k)</span><span class=\"bv-sb\"><i style=\"width:80%\"></i></span><span class=\"bv-st\">1,000</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">(หน่วยหลัก)</span><span class=\"bv-sb\"><i style=\"width:60%\"></i></span><span class=\"bv-st\">1</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">centi- (c)</span><span class=\"bv-sb\"><i style=\"width:40%\"></i></span><span class=\"bv-st\">1/100</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">milli- (m)</span><span class=\"bv-sb\"><i style=\"width:25%\"></i></span><span class=\"bv-st\">1/1,000</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">micro- (µ)</span><span class=\"bv-sb\"><i style=\"width:10%\"></i></span><span class=\"bv-st\">1/1,000,000</span></div><figcaption>prefix หน่วย SI จากใหญ่ไปเล็ก</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>prefix</th><th>จำนวน</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>uni- / mono-</td><td>1</td><td>uniform, monorail</td></tr><tr><td>bi-</td><td>2</td><td>bicycle, bilingual</td></tr><tr><td>tri-</td><td>3</td><td>triangle, tripod</td></tr><tr><td>multi- / poly-</td><td>หลาย</td><td>multimeter, polygon</td></tr><tr><td>semi-</td><td>ครึ่ง</td><td>semiconductor, semiannual</td></tr></tbody></table></div><figcaption>ระวัง: monitor ไม่ได้มาจาก mono- แต่มาจาก monere (เตือน)</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ใหญ่</div><div class=\"tf-value\">mega- &gt; kilo-</div></div><div class=\"tense-formula\"><div class=\"tf-label\">เล็ก</div><div class=\"tf-value\">centi- &gt; milli- &gt; micro-</div></div><div class=\"tense-formula\"><div class=\"tf-label\">จำนวน</div><div class=\"tf-value\">uni/mono 1 · bi 2 · tri 3 · multi/poly หลาย · semi ครึ่ง</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>จำนวน</b> — uni- / mono- = หนึ่ง, bi- = สอง, tri- = สาม, multi- / poly- = หลาย, semi- = ครึ่ง<br><span class=\"bv-rx\"><b>uni</b>form, <b>bi</b>cycle, <b>tri</b>angle, <b>multi</b>meter, <b>semi</b>conductor</span></p><p><b>ขนาด</b> — micro- = เล็กมาก, mega- = ใหญ่มาก / ล้าน, mini- = เล็ก<br><span class=\"bv-rx\"><b>micro</b>chip, <b>mega</b>watt, <b>mini</b>mum</span></p><p><b>หน่วย SI</b> — kilo- (k) = 1,000 · centi- (c) = 1/100 · milli- (m) = 1/1,000 · micro- (µ) = 1/1,000,000<br><span class=\"bv-rx\">1 <b>kilo</b>gram = 1,000 g · 1 <b>milli</b>metre = 0.001 m</span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The plant uses 5 megawatts.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The plant uses 5 megawatts.</div><div class=\"ex-th thai\">โรงงานใช้ไฟ 5 เมกะวัตต์</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The gap must be 0.2 millimetres.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The gap must be 0.2 millimetres.</div><div class=\"ex-th thai\">ช่องว่างต้องเป็น 0.2 มิลลิเมตร</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Use a multimeter to check the voltage.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Use a multimeter to check the voltage.</div><div class=\"ex-th thai\">ใช้มัลติมิเตอร์วัดแรงดัน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We hold a semiannual review.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We hold a semiannual review.</div><div class=\"ex-th thai\">เราประชุมทบทวนปีละสองครั้ง</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดและกับดัก</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ biweekly = สองครั้งต่อสัปดาห์เสมอ</p><p class=\"ok\">✓ biweekly อาจแปลว่า ทุกสองสัปดาห์ หรือ สัปดาห์ละสองครั้ง</p><small>กำกวม ในงานควรเขียน every two weeks หรือ twice a week ให้ชัด</small></div><div class=\"bv-m\"><p class=\"no\">✗ 10 mm = 1 m</p><p class=\"ok\">✓ 1,000 mm = 1 m</p><small>milli = หนึ่งในพัน</small></div><div class=\"bv-m\"><p class=\"no\">✗ monitor มาจาก mono-</p><p class=\"ok\">✓ monitor มาจาก monere (เตือน)</p><small>ตัวอักษรเหมือนกันไม่ได้แปลว่าเป็น prefix เดียวกัน</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> เวลาเขียนตัวเลขในเอกสาร ให้เว้นวรรคระหว่างตัวเลขกับหน่วย (5 mm, 220 V) และใช้ตัวพิมพ์เล็ก-ใหญ่ให้ถูก: m = milli, M = mega</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The microcontroller runs on 3.3 volts and draws only 20 milliamperes. The multilayer board is semi-automatically tested.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The <mark>micro</mark>controller runs on 3.3 volts and draws only 20 <mark>milli</mark>amperes. The <mark>multi</mark>layer board is <mark>semi</mark>-automatically tested.</div><div class=\"ts-th\">ไมโครคอนโทรลเลอร์ใช้ไฟ 3.3 โวลต์ และกินกระแสแค่ 20 มิลลิแอมแปร์ แผงวงจรหลายชั้นได้รับการทดสอบแบบกึ่งอัตโนมัติ</div></div></div></div>","easy":{"say":"prefix ตัวเลขคือรหัสจำนวนในคำ: bi = 2, tri = 3, multi = หลาย, semi = ครึ่ง และหน่วยวัด kilo = พัน, milli = หนึ่งในพัน","eg":["<b>kilo</b>metre = 1,000 m · <b>milli</b>metre = 0.001 m",""],"rule":"M ใหญ่ k พัน · m พันส่วน µ ล้านส่วน"}},{"id":"morepre","en":"More useful prefixes","th":"prefix อื่นที่ใช้บ่อย (co-, anti-, auto-, self-, en-, de-)","intro":"prefix กลุ่มนี้พบบ่อยในข่าว ธุรกิจ และเทคโนโลยี","r":[],"tips":[],"items":[{"id":"wf-morepre-0","p":0,"s":"\"coworker\" คือใคร?","gap":0,"o":{"A":"หัวหน้างาน","B":"เพื่อนร่วมงาน","C":"คนงานรายวัน","D":"ลูกค้า"},"oth":{},"a":"B","x":"co- = ร่วมกัน","v":[]},{"id":"wf-morepre-1","p":0,"s":"Wear an _____ wrist strap when you handle the boards.","gap":1,"o":{"A":"auto-static","B":"co-static","C":"anti-static","D":"de-static"},"oth":{},"a":"C","x":"anti- = ต่อต้าน (กันไฟฟ้าสถิต)","v":[]},{"id":"wf-morepre-2","p":0,"s":"The door opens _____ when someone comes near.","gap":1,"o":{"A":"coautomatically","B":"dematically","C":"antimatically","D":"automatically"},"oth":{},"a":"D","x":"auto- = ด้วยตัวเอง","v":[]},{"id":"wf-morepre-3","p":0,"s":"Please _____ the alarm before you enter.","gap":1,"o":{"A":"enactivate","B":"deactivate","C":"antiactivate","D":"coactivate"},"oth":{},"a":"B","x":"de- = เอาออก/ปิด + activate = ปิดการทำงาน","v":[]},{"id":"wf-morepre-4","p":0,"s":"The new software will _____ us to work faster.","gap":1,"o":{"A":"unable","B":"disable","C":"deable","D":"enable"},"oth":{},"a":"D","x":"en- (ทำให้) + able = ทำให้สามารถ","v":[]},{"id":"wf-morepre-5","p":0,"s":"ตรงข้ามของ \"encode\" คือคำใด?","gap":0,"o":{"A":"uncode","B":"recode","C":"decode","D":"discode"},"oth":{},"a":"C","x":"de- = กลับด้าน","v":[]},{"id":"wf-morepre-6","p":0,"s":"\"self-service\" หมายถึงอะไร?","gap":0,"o":{"A":"ไม่มีบริการ","B":"บริการตัวเอง","C":"บริการสองคน","D":"บริการพิเศษ"},"oth":{},"a":"B","x":"self- = ตนเอง","v":[]},{"id":"wf-morepre-7","p":0,"s":"Sales _____ by 10% last month.","gap":1,"o":{"A":"antidecreased","B":"decreased","C":"coincreased","D":"encreased"},"oth":{},"a":"B","x":"de- = ลดลง (decrease ตรงข้ามกับ increase)","v":[]},{"id":"wf-morepre-8","p":0,"s":"\"coworker\" = co- + work + -er แปลว่าอะไร? (co- = ร่วมกัน / ด้วยกัน)","gap":0,"o":{"A":"ให้สิทธิ์","B":"ทุ่มเท","C":"เพื่อนร่วมงาน","D":"ทำให้มั่นใจ"},"oth":{},"a":"C","x":"coworker = co- + work + -er → เพื่อนร่วมงาน","v":[]},{"id":"wf-morepre-9","p":0,"s":"\"entitle\" = en- + title แปลว่าอะไร? (en- = ทำให้ / ใส่เข้าไป)","gap":0,"o":{"A":"ร่วมก่อตั้ง","B":"ทำให้มั่นใจ","C":"ให้สิทธิ์","D":"ที่แนบมา"},"oth":{},"a":"C","x":"entitle = en- + title → ให้สิทธิ์","v":[]},{"id":"wf-morepre-10","p":0,"s":"\"cofounder\" = co- + found + -er แปลว่าอะไร? (co- = ร่วมกัน / ด้วยกัน)","gap":0,"o":{"A":"สรุปผล","B":"ผู้ร่วมก่อตั้ง","C":"ทุ่มเท","D":"สนุก"},"oth":{},"a":"B","x":"cofounder = co- + found + -er → ผู้ร่วมก่อตั้ง","v":[]}],"grp":"Prefixes & Suffixes — คำเติมหน้าและคำเติมท้าย","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">co- คือ \"<b>ทีม</b>\" (ทำด้วยกัน) anti- คือ \"<b>เกราะ</b>\" (กันไว้) auto- / self- คือ \"<b>ทำเอง</b>\" en- คือ \"<b>เติมเข้า</b>\" de- คือ \"<b>เอาออก</b>\"</div><figure class=\"bv bv-parts\"><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">cooperate</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">co</b><small>ร่วมกัน</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-b\"><b lang=\"en\">operate</b><small>ทำงาน</small></span></span><span class=\"wp-th\">ร่วมมือกัน</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">antivirus</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">anti</b><small>ต่อต้าน</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-b\"><b lang=\"en\">virus</b><small>ไวรัส</small></span></span><span class=\"wp-th\">โปรแกรมกันไวรัส</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">enlarge</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">en</b><small>ทำให้</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-b\"><b lang=\"en\">large</b><small>ใหญ่</small></span></span><span class=\"wp-th\">ขยายให้ใหญ่</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">deactivate</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">de</b><small>เอาออก</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-b\"><b lang=\"en\">activ</b><small>ทำงาน</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ate</b><small>ทำให้</small></span></span><span class=\"wp-th\">ปิดการทำงาน</span></div><figcaption>prefix + คำที่รู้จัก = คำใหม่</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>คู่ตรงข้าม</th><th>ความหมาย</th></tr></thead><tbody><tr><td>encode / decode</td><td>เข้ารหัส / ถอดรหัส</td></tr><tr><td>increase / decrease</td><td>เพิ่ม / ลด</td></tr><tr><td>activate / deactivate</td><td>เปิดใช้งาน / ปิดใช้งาน</td></tr><tr><td>enable / disable</td><td>เปิดให้ใช้ได้ / ปิดไม่ให้ใช้</td></tr></tbody></table></div><figcaption>de- และ dis- มักใช้สร้างคำตรงข้าม</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ร่วมกัน</div><div class=\"tf-value\">co- / com- / con-</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ต่อต้าน</div><div class=\"tf-value\">anti- / counter-</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ทำให้ / เอาออก</div><div class=\"tf-value\">en- / de-</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>co- / com- / con-</b> — ร่วมกัน ด้วยกัน<br><span class=\"bv-rx\"><b>co</b>worker, <b>co</b>operate, <b>com</b>bine, <b>con</b>nect <small>เพื่อนร่วมงาน, ร่วมมือ, รวม, เชื่อม</small></span></p><p><b>anti- / counter-</b> — ต่อต้าน ตรงข้าม<br><span class=\"bv-rx\"><b>anti</b>virus, <b>anti</b>-static, <b>counter</b>measure <small>แอนตี้ไวรัส, กันไฟฟ้าสถิต, มาตรการตอบโต้</small></span></p><p><b>auto- / self-</b> — ด้วยตัวเอง<br><span class=\"bv-rx\"><b>auto</b>matic, <b>auto</b>pilot, <b>self</b>-check, <b>self</b>-service <small>อัตโนมัติ, ระบบบินอัตโนมัติ, ตรวจตัวเอง, บริการตนเอง</small></span></p><p><b>en- / em- และ de-</b> — en- = ทำให้ / ใส่เข้าไป · de- = เอาออก / ลดลง / กลับด้าน<br><span class=\"bv-rx\"><b>en</b>large, <b>en</b>able, <b>en</b>code / <b>de</b>code, <b>de</b>activate, <b>de</b>crease <small>ขยาย, ทำให้ทำได้, เข้ารหัส / ถอดรหัส, ปิดการทำงาน, ลดลง</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The two teams cooperate on the project.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The two teams cooperate on the project.</div><div class=\"ex-th thai\">สองทีมร่วมมือกันในโครงการ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Install antivirus software on every PC.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Install antivirus software on every PC.</div><div class=\"ex-th thai\">ติดตั้งโปรแกรมแอนตี้ไวรัสทุกเครื่อง</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The machine has a self-check function.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The machine has a self-check function.</div><div class=\"ex-th thai\">เครื่องมีฟังก์ชันตรวจสอบตัวเอง</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Enlarge the image to 200%.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Enlarge the image to 200%.</div><div class=\"ex-th thai\">ขยายภาพเป็น 200%</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดและกับดัก</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ anti = ก่อน</p><p class=\"ok\">✓ anti = ต่อต้าน / ante = ก่อน</p><small>antiwar (ต่อต้านสงคราม) กับ antecedent (สิ่งที่มาก่อน) คนละ prefix</small></div><div class=\"bv-m\"><p class=\"no\">✗ unable the function</p><p class=\"ok\">✓ disable the function</p><small>unable เป็น adjective ใช้เป็นกริยาไม่ได้</small></div><div class=\"bv-m\"><p class=\"no\">✗ automatic = ด้วยมือ</p><p class=\"ok\">✓ automatic = อัตโนมัติ (ทำเอง)</p><small>auto- = ตัวเอง</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ในงาน IT และระบบอัตโนมัติ จะเจอ enable / disable, activate / deactivate, encode / decode บ่อยมาก จำเป็นคู่</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Our coworkers enabled the automatic backup. The antivirus is self-updating, so nobody needs to deactivate it.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">Our <mark>co</mark>workers <mark>en</mark>abled the <mark>auto</mark>matic backup. The <mark>anti</mark>virus is <mark>self</mark>-updating, so nobody needs to <mark>de</mark>activate it.</div><div class=\"ts-th\">เพื่อนร่วมงานเปิดใช้การสำรองข้อมูลอัตโนมัติ โปรแกรมแอนตี้ไวรัสอัปเดตตัวเอง จึงไม่มีใครต้องปิดมัน</div></div></div></div>","easy":{"say":"co- ทำด้วยกัน · anti- ต่อต้าน · auto- / self- ทำเอง · en- ทำให้ / เติมเข้า · de- เอาออก / ลดลง","eg":["<b>en</b>able / <b>dis</b>able · <b>en</b>code / <b>de</b>code",""],"rule":"จำ prefix เป็นคู่ตรงข้าม"}},{"id":"nsuf","en":"Noun suffixes","th":"suffix ที่ทำให้เป็นคำนาม","intro":"suffix เหล่านี้เปลี่ยนกริยาหรือคุณศัพท์ให้เป็นคำนาม เหมือนคำว่า \"การ...\" และ \"ความ...\" ในภาษาไทย","r":[],"tips":[],"items":[{"id":"wf-nsuf-0","p":0,"s":"คำนามของ \"decide\" คือคำใด?","gap":0,"o":{"A":"decision","B":"decidity","C":"decidance","D":"decidement"},"oth":{},"a":"A","x":"decide → decision (-sion)","v":[]},{"id":"wf-nsuf-1","p":0,"s":"คำนามของ \"accurate\" คือคำใด?","gap":0,"o":{"A":"accurance","B":"accuracy","C":"accuration","D":"accuratement"},"oth":{},"a":"B","x":"accurate → accuracy (-cy) ใช้บ่อยในงานวัด","v":[]},{"id":"wf-nsuf-2","p":0,"s":"คำนามของ \"arrive\" คือคำใด?","gap":0,"o":{"A":"arrivance","B":"arrival","C":"arrivement","D":"arrivation"},"oth":{},"a":"B","x":"arrive → arrival (-al)","v":[]},{"id":"wf-nsuf-3","p":0,"s":"คำนามของ \"able\" คือคำใด?","gap":0,"o":{"A":"ablation","B":"ableness","C":"ability","D":"ablement"},"oth":{},"a":"C","x":"able → ability (-ity)","v":[]},{"id":"wf-nsuf-4","p":0,"s":"We need more _____ in the warehouse.","gap":1,"o":{"A":"storage","B":"stored","C":"store","D":"storing"},"oth":{},"a":"A","x":"more + noun: storage (store + -age) = พื้นที่เก็บของ","v":[]},{"id":"wf-nsuf-5","p":0,"s":"The _____ of the new line was a success.","gap":1,"o":{"A":"performance","B":"performed","C":"perform","D":"performer"},"oth":{},"a":"A","x":"The ... of → noun ที่หมายถึงผลการทำงาน = performance","v":[]},{"id":"wf-nsuf-6","p":0,"s":"Good _____ skills are important for managers.","gap":1,"o":{"A":"leadership","B":"leader","C":"lead","D":"leading"},"oth":{},"a":"A","x":"leader + -ship = ภาวะผู้นำ (ทักษะ)","v":[]},{"id":"wf-nsuf-7","p":0,"s":"What is the _____ between the two models?","gap":1,"o":{"A":"differently","B":"differ","C":"difference","D":"different"},"oth":{},"a":"C","x":"the + noun: difference (different → -ence)","v":[]},{"id":"wf-nsuf-8","p":0,"s":"\"possession\" (สิ่งที่เป็นเจ้าของ) ลงท้าย -ion เป็นคำชนิดใด?","gap":0,"o":{"A":"verb (คำกริยา)","B":"adjective (คำคุณศัพท์)","C":"adverb (คำกริยาวิเศษณ์)","D":"noun (คำนาม)"},"oth":{},"a":"D","x":"-ion (การ... / สิ่งที่...) ทำให้เป็น noun (คำนาม)","v":[]},{"id":"wf-nsuf-9","p":0,"s":"\"language\" (ภาษา) ลงท้าย -age เป็นคำชนิดใด?","gap":0,"o":{"A":"verb (คำกริยา)","B":"adverb (คำกริยาวิเศษณ์)","C":"adjective (คำคุณศัพท์)","D":"noun (คำนาม)"},"oth":{},"a":"D","x":"-age (การ... / ค่า... / ที่...) ทำให้เป็น noun (คำนาม)","v":[]},{"id":"wf-nsuf-10","p":0,"s":"\"presence\" (การมีอยู่) ลงท้าย -ence เป็นคำชนิดใด?","gap":0,"o":{"A":"adverb (คำกริยาวิเศษณ์)","B":"verb (คำกริยา)","C":"noun (คำนาม)","D":"adjective (คำคุณศัพท์)"},"oth":{},"a":"C","x":"-ence (การ... / ความ...) ทำให้เป็น noun (คำนาม)","v":[]},{"id":"wf-nsuf-11","p":0,"s":"\"opposition\" (ฝ่ายค้าน) ลงท้าย -ition เป็นคำชนิดใด?","gap":0,"o":{"A":"adjective (คำคุณศัพท์)","B":"noun (คำนาม)","C":"adverb (คำกริยาวิเศษณ์)","D":"verb (คำกริยา)"},"oth":{},"a":"B","x":"-ition (การ... / สิ่งที่...) ทำให้เป็น noun (คำนาม)","v":[]}],"grp":"Prefixes & Suffixes — คำเติมหน้าและคำเติมท้าย","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">ภาษาไทยเติม \"การ\" หน้ากริยา (ตรวจ → <b>การ</b>ตรวจ) และ \"ความ\" หน้าคุณศัพท์ (แม่นยำ → <b>ความ</b>แม่นยำ) ภาษาอังกฤษทำแบบเดียวกัน แต่เติม<b>ท้าย</b>คำ</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>suffix</th><th>มาจาก</th><th>ตัวอย่าง</th><th>คล้ายภาษาไทย</th></tr></thead><tbody><tr><td>-tion / -sion</td><td>กริยา</td><td>inspection, decision</td><td>การ...</td></tr><tr><td>-ment</td><td>กริยา</td><td>payment, improvement</td><td>การ...</td></tr><tr><td>-ance / -ence</td><td>กริยา / adj.</td><td>performance, difference</td><td>การ... / ความ...</td></tr><tr><td>-al / -ure / -age</td><td>กริยา</td><td>arrival, failure, storage</td><td>การ...</td></tr><tr><td>-ness</td><td>adj.</td><td>kindness, readiness</td><td>ความ...</td></tr><tr><td>-ity / -cy</td><td>adj.</td><td>ability, accuracy</td><td>ความ...</td></tr><tr><td>-ship / -hood</td><td>noun</td><td>leadership, childhood</td><td>ภาวะ / สถานะ</td></tr></tbody></table></div><figcaption>suffix ของคำนามที่พบบ่อยที่สุด</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">การ...</div><div class=\"tf-value\">verb + -tion / -ment / -ance / -al</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ความ...</div><div class=\"tf-value\">adj + -ness / -ity / -cy</div></div><div class=\"tense-formula\"><div class=\"tf-label\">สถานะ</div><div class=\"tf-value\">noun + -ship / -hood</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>กริยา → คำนาม</b> — -tion / -sion / -ation, -ment, -ance / -ence, -al, -ure, -age<br><span class=\"bv-rx\">inform → <b>information</b>, pay → <b>payment</b>, perform → <b>performance</b>, arrive → <b>arrival</b>, fail → <b>failure</b>, store → <b>storage</b></span></p><p><b>คุณศัพท์ → คำนาม</b> — -ness, -ity / -ty, -ance / -ence, -cy<br><span class=\"bv-rx\">kind → <b>kindness</b>, able → <b>ability</b>, accurate → <b>accuracy</b>, different → <b>difference</b></span></p><p><b>คำนาม → คำนามแบบใหม่</b> — -ship (สถานะ/ทักษะ), -hood (ภาวะ), -dom (อาณาเขต/ภาวะ), -ism (แนวคิด)<br><span class=\"bv-rx\">leader → <b>leadership</b>, child → <b>childhood</b>, free → <b>freedom</b></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The inspection took two hours.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The inspection took two hours.</div><div class=\"ex-th thai\">การตรวจใช้เวลาสองชั่วโมง</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Payment is due in 30 days.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Payment is due in 30 days.</div><div class=\"ex-th thai\">ครบกำหนดชำระใน 30 วัน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Accuracy is critical in this test.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Accuracy is critical in this test.</div><div class=\"ex-th thai\">ความแม่นยำสำคัญมากในการทดสอบนี้</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The failure was caused by heat.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The failure was caused by heat.</div><div class=\"ex-th thai\">ความล้มเหลวเกิดจากความร้อน</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ decidement</p><p class=\"ok\">✓ decision</p><small>แต่ละคำมี suffix ของตัวเอง ต้องจำหรือเปิดพจนานุกรม</small></div><div class=\"bv-m\"><p class=\"no\">✗ He has a good leader.</p><p class=\"ok\">✓ He has good leadership skills.</p><small>leader = คน / leadership = ภาวะผู้นำ</small></div><div class=\"bv-m\"><p class=\"no\">✗ The arrive time</p><p class=\"ok\">✓ The arrival time</p><small>หน้าคำนาม time ใช้ noun arrival ขยาย</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> คำที่ลงท้าย -tion / -sion เน้นเสียงพยางค์ก่อนหน้าเสมอ: in-for-MA-tion, de-CI-sion, in-SPEC-tion</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"After the inspection, we found a difference in thickness. The failure affected production, so we made an improvement to the storage area.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">After the <mark>inspection</mark>, we found a <mark>difference</mark> in <mark>thickness</mark>. The <mark>failure</mark> affected <mark>production</mark>, so we made an <mark>improvement</mark> to the <mark>storage</mark> area.</div><div class=\"ts-th\">หลังการตรวจ เราพบความต่างของความหนา ความผิดพลาดกระทบการผลิต เราจึงปรับปรุงพื้นที่เก็บของ</div></div></div></div>","easy":{"say":"suffix ของคำนามคือ \"การ...\" และ \"ความ...\" แบบอังกฤษ แต่เติมท้ายคำ","eg":["inspect → inspect<b>ion</b> · accurate → accura<b>cy</b>","ตรวจ → การตรวจ · แม่นยำ → ความแม่นยำ"],"rule":"-tion -ment -ance = การ... · -ness -ity = ความ..."}},{"id":"person","en":"Suffixes for people","th":"suffix บอกคน (-er, -ee, -ist, -ian, -ant)","intro":"suffix กลุ่มนี้บอกว่าเป็น \"คน\" ที่ทำหรือได้รับการกระทำ และอาชีพต่างๆ","r":[],"tips":[],"items":[{"id":"wf-person-0","p":0,"s":"คนที่ \"ได้รับ\" การฝึกอบรมคือใคร?","gap":0,"o":{"A":"trainist","B":"trainer","C":"trainee","D":"trainian"},"oth":{},"a":"C","x":"-ee = ผู้ได้รับการกระทำ","v":[]},{"id":"wf-person-1","p":0,"s":"คนที่จ้างคนอื่นทำงานคือใคร?","gap":0,"o":{"A":"employer","B":"employment","C":"employee","D":"employable"},"oth":{},"a":"A","x":"-er = ผู้ทำ (ผู้จ้าง)","v":[]},{"id":"wf-person-2","p":0,"s":"ช่างที่ซ่อมระบบไฟฟ้าคือใคร?","gap":0,"o":{"A":"electrician","B":"electricer","C":"electricee","D":"electricist"},"oth":{},"a":"A","x":"electric + -ian","v":[]},{"id":"wf-person-3","p":0,"s":"Every _____ must send a CV and a cover letter.","gap":1,"o":{"A":"apply","B":"applied","C":"applicant","D":"application"},"oth":{},"a":"C","x":"ผู้สมัคร = applicant (apply + -ant)","v":[]},{"id":"wf-person-4","p":0,"s":"คนที่ให้คำปรึกษาคือใคร?","gap":0,"o":{"A":"consultation","B":"consultee","C":"consultative","D":"consultant"},"oth":{},"a":"D","x":"consult + -ant","v":[]},{"id":"wf-person-5","p":0,"s":"ข้อใดเป็น \"เครื่องมือ\" ไม่ใช่คน?","gap":0,"o":{"A":"scientist","B":"printer","C":"supervisor","D":"trainee"},"oth":{},"a":"B","x":"-er ใช้กับเครื่องมือได้ด้วย เช่น printer, computer","v":[]},{"id":"wf-person-6","p":0,"s":"The _____ asked the new staff many questions.","gap":1,"o":{"A":"interviewee","B":"interviewing","C":"interviewer","D":"interview"},"oth":{},"a":"C","x":"ผู้ที่ถามคำถาม = ผู้สัมภาษณ์ (interviewer)","v":[]},{"id":"wf-person-7","p":0,"s":"คนที่ทำงานในห้องแล็บวิทยาศาสตร์คือใคร?","gap":0,"o":{"A":"scientist","B":"sciencer","C":"scientee","D":"sciencian"},"oth":{},"a":"A","x":"science + -ist = นักวิทยาศาสตร์","v":[]},{"id":"wf-person-8","p":0,"s":"\"actor\" (นักแสดงชาย) ลงท้าย -or เป็นคำชนิดใด?","gap":0,"o":{"A":"adjective (คำคุณศัพท์)","B":"adverb (คำกริยาวิเศษณ์)","C":"verb (คำกริยา)","D":"noun (คำนาม)"},"oth":{},"a":"D","x":"-or (ผู้... / สิ่งที่...) ทำให้เป็น noun (คำนาม)","v":[]},{"id":"wf-person-9","p":0,"s":"\"moment\" (ช่วงเวลา) ลงท้าย -ent เป็นคำชนิดใด?","gap":0,"o":{"A":"verb (คำกริยา)","B":"adverb (คำกริยาวิเศษณ์)","C":"noun (คำนาม)","D":"adjective (คำคุณศัพท์)"},"oth":{},"a":"C","x":"-ent (ผู้... / ที่...) ทำให้เป็น noun (คำนาม)","v":[]},{"id":"wf-person-10","p":0,"s":"\"writer\" (นักเขียน) ลงท้าย -er เป็นคำชนิดใด?","gap":0,"o":{"A":"verb (คำกริยา)","B":"adjective (คำคุณศัพท์)","C":"noun (คำนาม)","D":"adverb (คำกริยาวิเศษณ์)"},"oth":{},"a":"C","x":"-er (ผู้... / สิ่งที่...) ทำให้เป็น noun (คำนาม)","v":[]},{"id":"wf-person-11","p":0,"s":"\"accident\" (อุบัติเหตุ) ลงท้าย -ent เป็นคำชนิดใด?","gap":0,"o":{"A":"adverb (คำกริยาวิเศษณ์)","B":"noun (คำนาม)","C":"adjective (คำคุณศัพท์)","D":"verb (คำกริยา)"},"oth":{},"a":"B","x":"-ent (ผู้... / ที่...) ทำให้เป็น noun (คำนาม)","v":[]}],"grp":"Prefixes & Suffixes — คำเติมหน้าและคำเติมท้าย","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">-er กับ -ee เป็นคู่ \"<b>ผู้ส่ง–ผู้รับ</b>\" เหมือนลูกบอล: employ<b>er</b> โยนงาน employ<b>ee</b> รับงาน train<b>er</b> สอน train<b>ee</b> เรียน</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ผู้ทำ (-er/-or)</th><th>ผู้ได้รับ (-ee)</th></tr></thead><tbody><tr><td>employer นายจ้าง</td><td>employee ลูกจ้าง</td></tr><tr><td>trainer ผู้สอน</td><td>trainee ผู้ฝึกงาน</td></tr><tr><td>interviewer ผู้สัมภาษณ์</td><td>interviewee ผู้ถูกสัมภาษณ์</td></tr><tr><td>payer ผู้จ่าย</td><td>payee ผู้รับเงิน</td></tr></tbody></table></div><figcaption>คู่ผู้ส่ง–ผู้รับ</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>suffix</th><th>ตัวอย่างอาชีพในโรงงาน</th></tr></thead><tbody><tr><td>-er / -or</td><td>operator, inspector, supervisor, manager</td></tr><tr><td>-ist</td><td>chemist, machinist, specialist</td></tr><tr><td>-ian</td><td>technician, electrician</td></tr><tr><td>-ant / -ent</td><td>assistant, consultant, accountant</td></tr></tbody></table></div><figcaption>ชื่อตำแหน่งงานส่วนใหญ่ใช้ suffix เหล่านี้</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ผู้ทำ</div><div class=\"tf-value\">verb + -er / -or / -ant</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ผู้ได้รับ</div><div class=\"tf-value\">verb + -ee</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ผู้เชี่ยวชาญ</div><div class=\"tf-value\">noun + -ist / -ian</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>-er / -or = ผู้ทำ</b> — ใช้ได้กับคนและเครื่องมือ<br><span class=\"bv-rx\">employ<b>er</b>, operat<b>or</b>, supervis<b>or</b>, print<b>er</b> (เครื่องพิมพ์) <small>นายจ้าง, พนักงานคุมเครื่อง, หัวหน้างาน</small></span></p><p><b>-ee = ผู้ถูกกระทำ / ผู้ได้รับ</b> — คู่กับ -er<br><span class=\"bv-rx\">employ<b>ee</b> (ลูกจ้าง) / employ<b>er</b> (นายจ้าง), train<b>ee</b> / train<b>er</b></span></p><p><b>-ist / -ian = ผู้เชี่ยวชาญ</b> — มักเป็นอาชีพหรือผู้ศึกษาด้านนั้น<br><span class=\"bv-rx\">scient<b>ist</b>, dent<b>ist</b>, technic<b>ian</b>, electric<b>ian</b> <small>นักวิทยาศาสตร์, ทันตแพทย์, ช่างเทคนิค, ช่างไฟ</small></span></p><p><b>-ant / -ent = ผู้ทำ</b> — มาจากกริยาละติน<br><span class=\"bv-rx\">assist<b>ant</b>, applic<b>ant</b>, consult<b>ant</b>, resid<b>ent</b> <small>ผู้ช่วย, ผู้สมัคร, ที่ปรึกษา, ผู้อยู่อาศัย</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The inspector found a scratch.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The inspector found a scratch.</div><div class=\"ex-th thai\">ผู้ตรวจพบรอยขีดข่วน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"All trainees must wear a red badge.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">All trainees must wear a red badge.</div><div class=\"ex-th thai\">ผู้ฝึกงานทุกคนต้องติดบัตรสีแดง</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The technician calibrated the scale.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The technician calibrated the scale.</div><div class=\"ex-th thai\">ช่างเทคนิคสอบเทียบตาชั่ง</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Our accountant checks the invoices.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Our accountant checks the invoices.</div><div class=\"ex-th thai\">นักบัญชีของเราตรวจใบแจ้งหนี้</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ He is an employer of ABC (หมายถึงลูกจ้าง)</p><p class=\"ok\">✓ He is an employee of ABC.</p><small>ลูกจ้าง = employee</small></div><div class=\"bv-m\"><p class=\"no\">✗ She is an assistance.</p><p class=\"ok\">✓ She is an assistant.</p><small>assistance = ความช่วยเหลือ (สิ่ง) / assistant = ผู้ช่วย (คน)</small></div><div class=\"bv-m\"><p class=\"no\">✗ technicist</p><p class=\"ok\">✓ technician</p><small>ต้องจำว่าคำไหนใช้ -ist คำไหนใช้ -ian</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> -ee เน้นเสียงที่ตัว -ee เสมอ: em-ploy-EE, train-EE, at-ten-DEE ช่วยให้ฟังแยกจาก -er ได้</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The trainer showed the new trainees how to work with the operators. A technician and an inspector joined the session.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The <mark>trainer</mark> showed the new <mark>trainees</mark> how to work with the <mark>operators</mark>. A <mark>technician</mark> and an <mark>inspector</mark> joined the session.</div><div class=\"ts-th\">ผู้สอนแสดงให้ผู้ฝึกงานใหม่ดูวิธีทำงานร่วมกับพนักงานคุมเครื่อง ช่างเทคนิคและผู้ตรวจเข้าร่วมด้วย</div></div></div></div>","easy":{"say":"-er / -or / -ant = ผู้ทำ · -ee = ผู้ได้รับ · -ist / -ian = ผู้เชี่ยวชาญหรืออาชีพ","eg":["employ<b>er</b> (นายจ้าง) ↔ employ<b>ee</b> (ลูกจ้าง)",""],"rule":"-er ส่ง · -ee รับ"}},{"id":"asuf","en":"Adjective suffixes","th":"suffix ที่ทำให้เป็นคำคุณศัพท์","intro":"suffix กลุ่มนี้สร้างคำคุณศัพท์จากคำนามหรือกริยา และแต่ละตัวมีความหมายของมันเอง","r":[],"tips":[],"items":[{"id":"wf-asuf-0","p":0,"s":"คำใดแปลว่า \"ไร้สาย\"?","gap":0,"o":{"A":"wirous","B":"wireful","C":"wirable","D":"wireless"},"oth":{},"a":"D","x":"-less = ไม่มี","v":[]},{"id":"wf-asuf-1","p":0,"s":"A _____ hose can bend easily.","gap":1,"o":{"A":"flexous","B":"flexible","C":"flexless","D":"flexful"},"oth":{},"a":"B","x":"-ible = ...ได้ (งอได้ = ยืดหยุ่น)","v":[]},{"id":"wf-asuf-2","p":0,"s":"This area is _____. Do not enter without a helmet.","gap":1,"o":{"A":"dangerable","B":"dangerful","C":"dangerous","D":"dangerive"},"oth":{},"a":"C","x":"danger + -ous","v":[]},{"id":"wf-asuf-3","p":0,"s":"The new training method is very _____.","gap":1,"o":{"A":"effectous","B":"effective","C":"effectless","D":"effectful"},"oth":{},"a":"B","x":"effect + -ive","v":[]},{"id":"wf-asuf-4","p":0,"s":"Is this jacket _____? Can I put it in the washing machine?","gap":1,"o":{"A":"washless","B":"washous","C":"washful","D":"washable"},"oth":{},"a":"D","x":"wash + -able = ซักได้","v":[]},{"id":"wf-asuf-5","p":0,"s":"คำใดแปลว่า \"ไม่ระมัดระวัง\"?","gap":0,"o":{"A":"careless","B":"carefully","C":"caring","D":"careful"},"oth":{},"a":"A","x":"-less = ไม่มี (ไม่มีความระมัดระวัง)","v":[]},{"id":"wf-asuf-6","p":0,"s":"The light is _____ from the street.","gap":1,"o":{"A":"visful","B":"visable","C":"visible","D":"visous"},"oth":{},"a":"C","x":"vis (เห็น) + -ible = มองเห็นได้ (สะกด -ible)","v":[]},{"id":"wf-asuf-7","p":0,"s":"The color is _____, not pure red.","gap":1,"o":{"A":"reddish","B":"redless","C":"redful","D":"reddable"},"oth":{},"a":"A","x":"-ish = ค่อนข้าง","v":[]},{"id":"wf-asuf-8","p":0,"s":"\"uncomfortable\" (ไม่สบายตัว) ลงท้าย -able เป็นคำชนิดใด?","gap":0,"o":{"A":"adjective (คำคุณศัพท์)","B":"verb (คำกริยา)","C":"noun (คำนาม)","D":"adverb (คำกริยาวิเศษณ์)"},"oth":{},"a":"A","x":"-able (...ได้) ทำให้เป็น adjective (คำคุณศัพท์)","v":[]},{"id":"wf-asuf-9","p":0,"s":"\"nervous\" (ประหม่า) ลงท้าย -ous เป็นคำชนิดใด?","gap":0,"o":{"A":"adjective (คำคุณศัพท์)","B":"adverb (คำกริยาวิเศษณ์)","C":"verb (คำกริยา)","D":"noun (คำนาม)"},"oth":{},"a":"A","x":"-ous (มีลักษณะ / เต็มไปด้วย) ทำให้เป็น adjective (คำคุณศัพท์)","v":[]},{"id":"wf-asuf-10","p":0,"s":"\"healthy\" (สุขภาพดี) ลงท้าย -y เป็นคำชนิดใด?","gap":0,"o":{"A":"adjective (คำคุณศัพท์)","B":"verb (คำกริยา)","C":"noun (คำนาม)","D":"adverb (คำกริยาวิเศษณ์)"},"oth":{},"a":"A","x":"-y (มีลักษณะ / เต็มไปด้วย) ทำให้เป็น adjective (คำคุณศัพท์)","v":[]},{"id":"wf-asuf-11","p":0,"s":"\"spicy\" (เผ็ด) ลงท้าย -y เป็นคำชนิดใด?","gap":0,"o":{"A":"noun (คำนาม)","B":"verb (คำกริยา)","C":"adverb (คำกริยาวิเศษณ์)","D":"adjective (คำคุณศัพท์)"},"oth":{},"a":"D","x":"-y (มีลักษณะ / เต็มไปด้วย) ทำให้เป็น adjective (คำคุณศัพท์)","v":[]}],"grp":"Prefixes & Suffixes — คำเติมหน้าและคำเติมท้าย","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">suffix ของคุณศัพท์แต่ละตัวเหมือน \"<b>สติกเกอร์ความหมาย</b>\": -ful = เต็ม, -less = ว่าง, -able = ทำได้, -ous = มีมาก, -al / -ic = เกี่ยวกับ ติดสติกเกอร์บนคำนาม ได้คุณศัพท์ใหม่ทันที</div><figure class=\"bv bv-parts\"><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">useful</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">use</b><small>ประโยชน์</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ful</b><small>เต็มไปด้วย</small></span></span><span class=\"wp-th\">มีประโยชน์</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">useless</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">use</b><small>ประโยชน์</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">less</b><small>ไม่มี</small></span></span><span class=\"wp-th\">ไร้ประโยชน์</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">washable</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">wash</b><small>ซัก</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">able</b><small>...ได้</small></span></span><span class=\"wp-th\">ซักได้</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">dangerous</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">danger</b><small>อันตราย</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ous</b><small>มีลักษณะ</small></span></span><span class=\"wp-th\">อันตราย (adj.)</span></div><figcaption>คำนาม / กริยา + suffix = คุณศัพท์</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>electric</th><th>electrical</th><th>electronic</th></tr></thead><tbody><tr><td>ใช้ไฟฟ้า / ไฟฟ้าโดยตรง</td><td>เกี่ยวกับไฟฟ้า (กว้างกว่า)</td><td>อิเล็กทรอนิกส์ (วงจร ชิป)</td></tr><tr><td>electric car, electric shock</td><td>electrical engineer, electrical safety</td><td>electronic device, electronic component</td></tr></tbody></table></div><figcaption>สามคำที่คนงานไฟฟ้าต้องแยกให้ออก</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">มี / ไม่มี</div><div class=\"tf-value\">noun + -ful / -less</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ทำได้</div><div class=\"tf-value\">verb + -able / -ible</div></div><div class=\"tense-formula\"><div class=\"tf-label\">เกี่ยวกับ</div><div class=\"tf-value\">noun + -al / -ic / -ical</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>-ful / -less</b> — เต็มไปด้วย / ไม่มี (คู่ตรงข้าม)<br><span class=\"bv-rx\">use<b>ful</b> / use<b>less</b>, care<b>ful</b> / care<b>less</b>, wire<b>less</b></span></p><p><b>-able / -ible</b> — ...ได้<br><span class=\"bv-rx\">wash<b>able</b>, read<b>able</b>, flex<b>ible</b>, vis<b>ible</b> <small>ซักได้, อ่านออก, ยืดหยุ่น, มองเห็นได้</small></span></p><p><b>-ous / -ive / -y</b> — มีลักษณะ / เต็มไปด้วย<br><span class=\"bv-rx\">danger<b>ous</b>, effect<b>ive</b>, act<b>ive</b>, nois<b>y</b>, dust<b>y</b></span></p><p><b>-al / -ic / -ical</b> — เกี่ยวกับ<br><span class=\"bv-rx\">nation<b>al</b>, electr<b>ic</b> / electr<b>ical</b>, technic<b>al</b>, histor<b>ic</b></span></p><p><b>-ish</b> — ค่อนข้าง / ชาว...<br><span class=\"bv-rx\">red<b>dish</b> (ค่อนข้างแดง), Engl<b>ish</b></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The manual is very useful.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The manual is very useful.</div><div class=\"ex-th thai\">คู่มือมีประโยชน์มาก</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We use a wireless scanner.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We use a wireless scanner.</div><div class=\"ex-th thai\">เราใช้เครื่องสแกนไร้สาย</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Wear gloves; the liquid is corrosive.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Wear gloves; the liquid is corrosive.</div><div class=\"ex-th thai\">สวมถุงมือ ของเหลวกัดกร่อน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"He is an electrical engineer.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">He is an electrical engineer.</div><div class=\"ex-th thai\">เขาเป็นวิศวกรไฟฟ้า</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ visable</p><p class=\"ok\">✓ visible</p><small>-able และ -ible ต้องจำการสะกด คำจากรากละตินมักใช้ -ible</small></div><div class=\"bv-m\"><p class=\"no\">✗ an electronic shock</p><p class=\"ok\">✓ an electric shock</p><small>ไฟดูด = electric shock</small></div><div class=\"bv-m\"><p class=\"no\">✗ a hopeless (= มีความหวัง)</p><p class=\"ok\">✓ hopeful = มีความหวัง / hopeless = สิ้นหวัง</p><small>-ful กับ -less ตรงข้ามกัน</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ถ้าตัดส่วนหน้าออกแล้วเหลือคำที่ใช้ได้ มักใช้ -able (wash-able, read-able) ถ้าเหลือส่วนที่ใช้เดี่ยวไม่ได้ มักใช้ -ible (vis-ible, poss-ible)</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The new wireless sensor is washable and waterproof. It is useful in dusty and dangerous areas.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The new <mark>wireless</mark> sensor is <mark>washable</mark> and <mark>waterproof</mark>. It is <mark>useful</mark> in <mark>dusty</mark> and <mark>dangerous</mark> areas.</div><div class=\"ts-th\">เซนเซอร์ไร้สายรุ่นใหม่ล้างน้ำได้และกันน้ำ มีประโยชน์ในพื้นที่ฝุ่นเยอะและอันตราย</div></div></div></div>","easy":{"say":"suffix ของคุณศัพท์คือสติกเกอร์ความหมาย: -ful เต็ม · -less ไม่มี · -able ทำได้ · -ous / -y มีมาก · -al / -ic เกี่ยวกับ","eg":["use<b>ful</b> / use<b>less</b> · wash<b>able</b>","มีประโยชน์ / ไร้ประโยชน์ · ซักได้"],"rule":"จำความหมายของสติกเกอร์ แล้วเดาคำใหม่ได้"}},{"id":"vsuf","en":"Verb and adverb suffixes","th":"suffix ของคำกริยาและคำกริยาวิเศษณ์","intro":"suffix ของกริยาบอกว่า \"ทำให้เป็น...\" ส่วน suffix ของ adverb บอกว่า \"อย่างไร\" หรือ \"ไปทางไหน\"","r":[],"tips":[],"items":[{"id":"wf-vsuf-0","p":0,"s":"Turn the screw _____ to tighten it.","gap":1,"o":{"A":"clockly","B":"clockward","C":"clockwise","D":"clockize"},"oth":{},"a":"C","x":"clock + -wise = ตามเข็มนาฬิกา","v":[]},{"id":"wf-vsuf-1","p":0,"s":"Please _____ the bolts to 10 N·m.","gap":1,"o":{"A":"tightly","B":"tightize","C":"tighten","D":"tightify"},"oth":{},"a":"C","x":"tight + -en = ขันให้แน่น","v":[]},{"id":"wf-vsuf-2","p":0,"s":"We need to _____ our tasks. What is most important?","gap":1,"o":{"A":"prioritization","B":"prioritize","C":"prior","D":"priority"},"oth":{},"a":"B","x":"prior + -itize = จัดลำดับความสำคัญ","v":[]},{"id":"wf-vsuf-3","p":0,"s":"Can you _____ this point? I do not understand.","gap":1,"o":{"A":"clearly","B":"clarity","C":"clear","D":"clarify"},"oth":{},"a":"D","x":"clear → clarify (-ify) = ทำให้ชัด","v":[]},{"id":"wf-vsuf-4","p":0,"s":"The company wants to _____ all labels.","gap":1,"o":{"A":"standardly","B":"standardization","C":"standard","D":"standardize"},"oth":{},"a":"D","x":"หลัง to ใช้กริยา: standardize","v":[]},{"id":"wf-vsuf-5","p":0,"s":"Move the lever _____.","gap":1,"o":{"A":"upward","B":"upize","C":"upwise","D":"upen"},"oth":{},"a":"A","x":"up + -ward = ขึ้นไปทางบน","v":[]},{"id":"wf-vsuf-6","p":0,"s":"Save your work; _____, you may lose it.","gap":1,"o":{"A":"otherwise","B":"otherize","C":"otherly","D":"otherward"},"oth":{},"a":"A","x":"otherwise = มิฉะนั้น","v":[]},{"id":"wf-vsuf-7","p":0,"s":"The test must _____ the new design.","gap":1,"o":{"A":"validate","B":"validity","C":"validly","D":"valid"},"oth":{},"a":"A","x":"valid + -ate = ยืนยันว่าถูกต้อง","v":[]},{"id":"wf-vsuf-8","p":0,"s":"\"organize\" (จัดระเบียบ) ลงท้าย -ize เป็นคำชนิดใด?","gap":0,"o":{"A":"adjective (คำคุณศัพท์)","B":"noun (คำนาม)","C":"adverb (คำกริยาวิเศษณ์)","D":"verb (คำกริยา)"},"oth":{},"a":"D","x":"-ize (ทำให้เป็น...) ทำให้เป็น verb (คำกริยา)","v":[]},{"id":"wf-vsuf-9","p":0,"s":"\"justify\" (ให้เหตุผลรองรับ) ลงท้าย -ify เป็นคำชนิดใด?","gap":0,"o":{"A":"verb (คำกริยา)","B":"adjective (คำคุณศัพท์)","C":"adverb (คำกริยาวิเศษณ์)","D":"noun (คำนาม)"},"oth":{},"a":"A","x":"-ify (ทำให้...) ทำให้เป็น verb (คำกริยา)","v":[]},{"id":"wf-vsuf-10","p":0,"s":"\"operate\" (ดำเนินงาน) ลงท้าย -ate เป็นคำชนิดใด?","gap":0,"o":{"A":"verb (คำกริยา)","B":"adjective (คำคุณศัพท์)","C":"noun (คำนาม)","D":"adverb (คำกริยาวิเศษณ์)"},"oth":{},"a":"A","x":"-ate (ทำให้ / ทำ...) ทำให้เป็น verb (คำกริยา)","v":[]}],"grp":"Prefixes & Suffixes — คำเติมหน้าและคำเติมท้าย","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">suffix ของกริยาเหมือน \"<b>ปุ่มเปลี่ยนสถานะ</b>\": short (สั้น) + -en = ทำให้สั้น, simple + -ify = ทำให้ง่าย, standard + -ize = ทำให้เป็นมาตรฐาน คุณศัพท์บอกสภาพ กริยาทำให้เกิดสภาพนั้น</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>adjective / noun</th><th>+ suffix</th><th>= verb</th></tr></thead><tbody><tr><td>short สั้น</td><td>-en</td><td>shorten ทำให้สั้น</td></tr><tr><td>simple ง่าย</td><td>-ify</td><td>simplify ทำให้ง่าย</td></tr><tr><td>standard มาตรฐาน</td><td>-ize</td><td>standardize ทำให้เป็นมาตรฐาน</td></tr><tr><td>active ทำงานอยู่</td><td>-ate</td><td>activate เปิดใช้งาน</td></tr></tbody></table></div><figcaption>สภาพ → ทำให้เกิดสภาพนั้น</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ทิศทาง</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>-ward(s) ไปทาง</td><td>upward ↑ downward ↓ forward → backward ←</td></tr><tr><td>-wise ตามทาง / ในแง่</td><td>clockwise ↻ counterclockwise ↺ otherwise</td></tr></tbody></table></div><figcaption>adverb บอกทิศทางที่ใช้ในคู่มือเครื่องจักร</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ทำให้</div><div class=\"tf-value\">adj + -en / -ify / -ize</div></div><div class=\"tense-formula\"><div class=\"tf-label\">อย่าง</div><div class=\"tf-value\">adj + -ly</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ทิศทาง</div><div class=\"tf-value\">up / down / for + -ward</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>-ize / -ise</b> — ทำให้เป็น (อเมริกันใช้ -ize อังกฤษใช้ได้ทั้งสองแบบ)<br><span class=\"bv-rx\">standard<b>ize</b>, organ<b>ize</b>, prior<b>itize</b>, custom<b>ize</b> <small>ทำให้เป็นมาตรฐาน, จัดระเบียบ, จัดลำดับความสำคัญ, ปรับแต่ง</small></span></p><p><b>-ify / -en / -ate</b> — ทำให้<br><span class=\"bv-rx\">simpl<b>ify</b>, clar<b>ify</b>, short<b>en</b>, tight<b>en</b>, activ<b>ate</b>, valid<b>ate</b> <small>ทำให้ง่าย, ทำให้ชัด, ทำให้สั้น, ขันให้แน่น, เปิดใช้งาน, ยืนยันความถูกต้อง</small></span></p><p><b>-ly (adverb)</b> — อย่าง... (จาก adjective)<br><span class=\"bv-rx\">quick<b>ly</b>, safe<b>ly</b>, automatical<b>ly</b></span></p><p><b>-ward(s) / -wise</b> — ไปทาง... / ในแง่ของ...<br><span class=\"bv-rx\">up<b>ward</b>, for<b>ward</b>, clock<b>wise</b>, other<b>wise</b> <small>ขึ้นไป, ไปข้างหน้า, ตามเข็มนาฬิกา, มิฉะนั้น</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We simplified the form.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We simplified the form.</div><div class=\"ex-th thai\">เราทำแบบฟอร์มให้ง่ายขึ้น</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Turn the knob counterclockwise.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Turn the knob counterclockwise.</div><div class=\"ex-th thai\">หมุนปุ่มทวนเข็มนาฬิกา</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please organize the files by date.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please organize the files by date.</div><div class=\"ex-th thai\">กรุณาจัดไฟล์ตามวันที่</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Prices moved upward this quarter.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Prices moved upward this quarter.</div><div class=\"ex-th thai\">ราคาปรับขึ้นในไตรมาสนี้</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Please clear this point. (หมายถึงอธิบาย)</p><p class=\"ok\">✓ Please clarify this point.</p><small>clarify = อธิบายให้ชัด</small></div><div class=\"bv-m\"><p class=\"no\">✗ tight the screw</p><p class=\"ok\">✓ tighten the screw</p><small>tight เป็น adjective ต้องเติม -en เป็นกริยา</small></div><div class=\"bv-m\"><p class=\"no\">✗ turn clockwisely</p><p class=\"ok\">✓ turn clockwise</p><small>clockwise เป็น adverb อยู่แล้ว</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ในคู่มือเครื่องจักร เจอ tighten / loosen, clockwise / counterclockwise (anticlockwise แบบอังกฤษ) บ่อยมาก จำเป็นคู่</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"First, loosen the cover and turn the dial counterclockwise. Then tighten the bolts and activate the safety switch. Otherwise, the machine will not start.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">First, <mark>loosen</mark> the cover and turn the dial <mark>counterclockwise</mark>. Then <mark>tighten</mark> the bolts and <mark>activate</mark> the safety switch. <mark>Otherwise</mark>, the machine will not start.</div><div class=\"ts-th\">ขั้นแรก คลายฝาครอบและหมุนหน้าปัดทวนเข็มนาฬิกา จากนั้นขันโบลต์ให้แน่นและเปิดสวิตช์นิรภัย มิฉะนั้นเครื่องจะไม่ทำงาน</div></div></div></div>","easy":{"say":"suffix ของกริยาเป็นปุ่ม \"ทำให้\": short → shorten, simple → simplify, standard → standardize","eg":["tight + <b>en</b> = tighten","แน่น → ขันให้แน่น"],"rule":"-en / -ify / -ize / -ate = ทำให้ · -ly = อย่าง · -ward = ไปทาง"}},{"id":"spell","en":"Spelling changes with suffixes","th":"การสะกดเมื่อเติม suffix","intro":"เวลาเติม suffix ตัวสะกดบางครั้งเปลี่ยน มีกฎหลัก 4 ข้อที่ใช้ได้กับคำส่วนใหญ่","r":[],"tips":[],"items":[{"id":"wf-spell-0","p":0,"s":"เติม -ing ให้ \"ship\" สะกดอย่างไร?","gap":0,"o":{"A":"shipeing","B":"shiping","C":"shippeing","D":"shipping"},"oth":{},"a":"D","x":"CVC พยางค์เดียว ซ้ำตัวท้าย: shipping","v":[]},{"id":"wf-spell-1","p":0,"s":"เติม -ness ให้ \"happy\" สะกดอย่างไร?","gap":0,"o":{"A":"happyness","B":"happness","C":"happieness","D":"happiness"},"oth":{},"a":"D","x":"พยัญชนะ + y → i","v":[]},{"id":"wf-spell-2","p":0,"s":"เติม -able ให้ \"use\" สะกดอย่างไร?","gap":0,"o":{"A":"usabel","B":"usable","C":"usabile","D":"usible"},"oth":{},"a":"B","x":"ตัด e ก่อน suffix ที่ขึ้นต้นด้วยสระ: use → usable","v":[]},{"id":"wf-spell-3","p":0,"s":"เติม -ful ให้ \"use\" สะกดอย่างไร?","gap":0,"o":{"A":"usefuly","B":"usful","C":"usefull","D":"useful"},"oth":{},"a":"D","x":"suffix ขึ้นต้นด้วยพยัญชนะ เก็บ e ไว้ และ -ful มี l ตัวเดียว","v":[]},{"id":"wf-spell-4","p":0,"s":"adverb ของ \"automatic\" คือคำใด?","gap":0,"o":{"A":"automatily","B":"automaticly","C":"automaticaly","D":"automatically"},"oth":{},"a":"D","x":"-ic → -ically","v":[]},{"id":"wf-spell-5","p":0,"s":"เติม -ed ให้ \"stop\" สะกดอย่างไร?","gap":0,"o":{"A":"stopped","B":"stopt","C":"stoped","D":"stoppd"},"oth":{},"a":"A","x":"ซ้ำ p ก่อน -ed","v":[]},{"id":"wf-spell-6","p":0,"s":"เติม -ing ให้ \"apply\" สะกดอย่างไร?","gap":0,"o":{"A":"appliying","B":"applying","C":"appliing","D":"appling"},"oth":{},"a":"B","x":"เก็บ y หน้า -ing","v":[]},{"id":"wf-spell-7","p":0,"s":"เติม -ly ให้ \"easy\" สะกดอย่างไร?","gap":0,"o":{"A":"easyly","B":"easilly","C":"easly","D":"easily"},"oth":{},"a":"D","x":"y → i แล้วเติม -ly","v":[]}],"grp":"Prefixes & Suffixes — คำเติมหน้าและคำเติมท้าย","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">กฎการสะกดเหมือน \"<b>ข้อต่อท่อ</b>\" เวลาต่อสองท่อเข้าด้วยกัน บางครั้งต้องตัดปลายนิดหน่อย (ตัด e) เปลี่ยนหัวต่อ (y → i) หรือเสริมข้อต่อ (ซ้ำพยัญชนะ) เพื่อให้ต่อกันได้พอดี</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>กฎ</th><th>ก่อน</th><th>หลัง</th></tr></thead><tbody><tr><td>ตัด e (+ สระ)</td><td>make, create, use</td><td>making, creation, usable</td></tr><tr><td>เก็บ e (+ พยัญชนะ)</td><td>use, safe, care</td><td>useful, safety, careful</td></tr><tr><td>y → i</td><td>happy, easy, apply</td><td>happiness, easily, applied</td></tr><tr><td>เก็บ y + -ing</td><td>apply, study</td><td>applying, studying</td></tr><tr><td>ซ้ำพยัญชนะ</td><td>plan, stop, ship</td><td>planning, stopped, shipping</td></tr><tr><td>-ic → -ically</td><td>automatic, basic</td><td>automatically, basically</td></tr></tbody></table></div><figcaption>สี่กฎหลักของการต่อ suffix</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ตัด e</div><div class=\"tf-value\">make → making</div></div><div class=\"tense-formula\"><div class=\"tf-label\">y → i</div><div class=\"tf-value\">happy → happiness</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ซ้ำ</div><div class=\"tf-value\">plan → planning</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>1. ตัด e ท้าย ถ้า suffix ขึ้นต้นด้วยสระ</b> — make → making, use → usable, create → creation / แต่เก็บ e ถ้า suffix ขึ้นต้นด้วยพยัญชนะ: use → useful, safe → safety</p><p><b>2. y → i</b> — พยัญชนะ + y เปลี่ยน y เป็น i: happy → happiness, easy → easily, apply → applied / แต่เก็บ y หน้า -ing: apply → applying</p><p><b>3. พยัญชนะท้ายซ้ำ</b> — คำพยางค์เดียวแบบ พยัญชนะ-สระ-พยัญชนะ ซ้ำตัวท้ายก่อน suffix ขึ้นต้นด้วยสระ: plan → planning, stop → stopped, ship → shipping</p><p><b>4. -ic → -ically</b> — adjective ที่ลงท้าย -ic เติม -ally เป็น adverb: automatic → automatically, basic → basically (ยกเว้น public → publicly)</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We are shipping the order today.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We are shipping the order today.</div><div class=\"ex-th thai\">เรากำลังส่งของวันนี้</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The parts are easily damaged.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The parts are easily damaged.</div><div class=\"ex-th thai\">ชิ้นส่วนเสียหายง่าย</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Safety comes first.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Safety comes first.</div><div class=\"ex-th thai\">ความปลอดภัยมาก่อน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The data is updated automatically.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The data is updated automatically.</div><div class=\"ex-th thai\">ข้อมูลอัปเดตอัตโนมัติ</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ planing (วางแผน)</p><p class=\"ok\">✓ planning</p><small>plan เป็น CVC ต้องซ้ำ n (planing = การไสไม้)</small></div><div class=\"bv-m\"><p class=\"no\">✗ beautifull</p><p class=\"ok\">✓ beautiful</p><small>-ful มี l ตัวเดียวเสมอ</small></div><div class=\"bv-m\"><p class=\"no\">✗ basicly</p><p class=\"ok\">✓ basically</p><small>-ic → -ically</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> คำที่เน้นเสียงพยางค์หลัง ก็ซ้ำพยัญชนะด้วย: preFER → preferred, ocCUR → occurred แต่ OFfer → offered (เน้นหน้า ไม่ซ้ำ)</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The team stopped the line, planned a fix and applied it carefully. Happily, the shipping date did not change.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The team <mark>stopped</mark> the line, <mark>planned</mark> a fix and <mark>applied</mark> it <mark>carefully</mark>. <mark>Happily</mark>, the <mark>shipping</mark> date did not change.</div><div class=\"ts-th\">ทีมหยุดไลน์ วางแผนแก้ไข และลงมือแก้อย่างระมัดระวัง โชคดีที่วันส่งของไม่เปลี่ยน</div></div></div></div>","easy":{"say":"เวลาต่อ suffix บางครั้งต้อง \"แต่งปลายคำ\" ให้ต่อกันได้: ตัด e, เปลี่ยน y เป็น i, หรือซ้ำพยัญชนะตัวท้าย","eg":["make → mak<b>ing</b> · happy → happ<b>i</b>ness · plan → pla<b>nn</b>ing",""],"rule":"ตัด e · y → i · ซ้ำพยัญชนะ · -ic → -ically"}},{"id":"stack","en":"Long words with many parts","th":"คำยาวที่มีหลายส่วน แยกทีละชั้น","intro":"คำยาวมักเกิดจากการต่อส่วนเติมซ้อนกันหลายชั้น แยกจากด้านนอกเข้าหาแกนทีละชั้น จะเข้าใจได้แม้ไม่เคยเห็นคำนั้น","r":[],"tips":[],"items":[{"id":"wf-stack-0","p":0,"s":"\"internationally\" เป็นคำชนิดใด?","gap":0,"o":{"A":"noun","B":"adjective","C":"verb","D":"adverb"},"oth":{},"a":"D","x":"ส่วนท้ายสุดคือ -ly จึงเป็น adverb","v":[]},{"id":"wf-stack-1","p":0,"s":"แกนกลางของ \"unbelievable\" คืออะไร?","gap":0,"o":{"A":"unbelieve","B":"liev","C":"believe","D":"able"},"oth":{},"a":"C","x":"un- + believe + -able","v":[]},{"id":"wf-stack-2","p":0,"s":"\"reorganization\" แปลตามส่วนว่าอะไร?","gap":0,"o":{"A":"ผู้จัดระเบียบ","B":"จัดระเบียบไม่ได้","C":"การจัดระเบียบใหม่","D":"ไม่จัดระเบียบ"},"oth":{},"a":"C","x":"re- (ใหม่) + organ + -ize (ทำให้) + -ation (การ)","v":[]},{"id":"wf-stack-3","p":0,"s":"\"independence\" เป็นคำชนิดใด?","gap":0,"o":{"A":"noun","B":"adverb","C":"verb","D":"adjective"},"oth":{},"a":"A","x":"ลงท้ายด้วย -ence เป็น noun","v":[]},{"id":"wf-stack-4","p":0,"s":"\"uncomfortable\" มีกี่ส่วน?","gap":0,"o":{"A":"2: uncomfort + able","B":"1: คำเดียว","C":"4: un + com + fort + able (ไม่มีความหมาย)","D":"3: un- + comfort + -able"},"oth":{},"a":"D","x":"สำหรับการเรียน แยกเป็น un- + comfort + -able (ถ้าลึกถึงราก com + fort = แข็งแรงร่วมกัน)","v":[]},{"id":"wf-stack-5","p":0,"s":"คำใดแปลว่า \"ไม่สามารถคาดเดาได้\"?","gap":0,"o":{"A":"predictable","B":"predictably","C":"prediction","D":"unpredictable"},"oth":{},"a":"D","x":"un- + predict + -able","v":[]},{"id":"wf-stack-6","p":0,"s":"\"misunderstanding\" แยกเป็นอะไร?","gap":0,"o":{"A":"mi + sunder + standing","B":"mis- + understand + -ing","C":"mis + under + -ing","D":"misunder + standing"},"oth":{},"a":"B","x":"mis- (ผิด) + understand (เข้าใจ) + -ing (การ) = ความเข้าใจผิด","v":[]},{"id":"wf-stack-7","p":0,"s":"\"unemployment\" ส่วนไหนบอกว่าเป็นคำนาม?","gap":0,"o":{"A":"em-","B":"-ment","C":"employ","D":"un-"},"oth":{},"a":"B","x":"suffix สุดท้าย -ment บอกชนิดคำ","v":[]},{"id":"wf-stack-8","p":0,"s":"คำว่า \"assignment\" (งานที่ได้รับมอบหมาย) แยกส่วนอย่างไรจึงถูกต้อง?","gap":0,"o":{"A":"a + ssig + nment","B":"a + ssignme + nt","C":"ass + ignm + ent","D":"as- + sign + -ment"},"oth":{},"a":"D","x":"assignment = as- + sign + -ment (ไปยัง + เครื่องหมาย + การ... / ผลของ...)","v":[]},{"id":"wf-stack-9","p":0,"s":"คำว่า \"renewal\" (การต่ออายุ) แยกส่วนอย่างไรจึงถูกต้อง?","gap":0,"o":{"A":"re- + new + -al","B":"r + ene + wal","C":"r + enewa + l","D":"r + en + ewal"},"oth":{},"a":"A","x":"renewal = re- + new + -al (อีกครั้ง + new + เกี่ยวกับ...)","v":[]},{"id":"wf-stack-10","p":0,"s":"คำว่า \"subjective\" (ขึ้นกับความรู้สึกส่วนตัว) แยกส่วนอย่างไรจึงถูกต้อง?","gap":0,"o":{"A":"s + ubjectiv + e","B":"sub- + ject + -ive","C":"su + bjecti + ve","D":"subje + ctiv + e"},"oth":{},"a":"B","x":"subjective = sub- + ject + -ive (ใต้ + โยน + ที่มีลักษณะ / ที่ชอบ...)","v":[]},{"id":"wf-stack-11","p":0,"s":"คำว่า \"evident\" (ชัดเจน) แยกส่วนอย่างไรจึงถูกต้อง?","gap":0,"o":{"A":"ev + i + dent","B":"e- + vid + -ent","C":"e + vi + dent","D":"evi + den + t"},"oth":{},"a":"B","x":"evident = e- + vid + -ent (ออก + เห็น + ผู้... / ที่...)","v":[]}],"grp":"Prefixes & Suffixes — คำเติมหน้าและคำเติมท้าย","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">คำยาวเหมือน <b>หัวหอม</b> มีหลายชั้น ลอกออกทีละชั้นจากด้านนอก (suffix ท้ายสุด, prefix หน้าสุด) จนเหลือแกน (base / root) แล้วค่อยประกอบความหมายกลับ</div><figure class=\"bv bv-steps\"><ol><li>internationally</li><li>international + -ly (อย่าง...)</li><li>inter- (ระหว่าง) + national</li><li>nation (ชาติ) + -al (เกี่ยวกับ)</li><li>รวม: อย่างระหว่างประเทศ = ในระดับนานาชาติ</li></ol><figcaption>ลอกหัวหอมทีละชั้น</figcaption></figure><figure class=\"bv bv-parts\"><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">unpredictable</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">un</b><small>ไม่</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-p\"><b lang=\"en\">pre</b><small>ก่อน</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">dict</b><small>พูด</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">able</b><small>...ได้</small></span></span><span class=\"wp-th\">คาดเดาไม่ได้</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">reorganization</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">re</b><small>ใหม่</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-b\"><b lang=\"en\">organ</b><small>อวัยวะ/ส่วน</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">iz</b><small>ทำให้</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ation</b><small>การ...</small></span></span><span class=\"wp-th\">การจัดระเบียบใหม่</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">misunderstanding</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">mis</b><small>ผิด</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-b\"><b lang=\"en\">understand</b><small>เข้าใจ</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ing</b><small>การ...</small></span></span><span class=\"wp-th\">ความเข้าใจผิด</span></div><figcaption>คำยาวแยกเป็นส่วนสั้นที่รู้จัก</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ลอกชั้นนอก</div><div class=\"tf-value\">suffix สุดท้าย → prefix</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ชนิดคำ</div><div class=\"tf-value\">ดูจาก suffix สุดท้าย</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ความหมาย</div><div class=\"tf-value\">ประกอบจากแกนออกไป</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>แยกจากนอกเข้าใน</b> — ลอก suffix ตัวท้ายสุดออกก่อน แล้ว prefix แล้วดูแกน<br><span class=\"bv-rx\">un + [[employ] + ment] → unemployment <small>ไม่ + (จ้าง + การ) = การว่างงาน</small></span></p><p><b>ชนิดของคำดูจาก suffix สุดท้าย</b> — suffix ตัวสุดท้ายบอกชนิดของคำทั้งคำ<br><span class=\"bv-rx\">in + depend + ent + ly → independently = adverb (เพราะลงท้าย -ly) <small>อย่างเป็นอิสระ</small></span></p><p><b>หนึ่งแกน หลายคำ</b> — แกนเดียวต่อได้หลายแบบ<br><span class=\"bv-rx\">nation → national → international → internationally / nationality / nationwide</span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The weather is unpredictable.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The weather is unpredictable.</div><div class=\"ex-th thai\">อากาศคาดเดาไม่ได้</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The reorganization starts in May.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The reorganization starts in May.</div><div class=\"ex-th thai\">การปรับโครงสร้างเริ่มเดือนพฤษภาคม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"It was a misunderstanding.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">It was a misunderstanding.</div><div class=\"ex-th thai\">มันเป็นความเข้าใจผิด</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The unit works independently.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The unit works independently.</div><div class=\"ex-th thai\">หน่วยนี้ทำงานอย่างอิสระ</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่พบบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ แยก &quot;understand&quot; เป็น under + stand แล้วแปลว่า &quot;ยืนข้างใต้&quot;</p><p class=\"ok\">✓ understand = เข้าใจ</p><small>บางคำประกอบมาตั้งแต่ภาษาอังกฤษโบราณ ความหมายรวมเปลี่ยนไปแล้ว ต้องตรวจกับพจนานุกรม</small></div><div class=\"bv-m\"><p class=\"no\">✗ อ่าน unemployment เป็นคำกริยา</p><p class=\"ok\">✓ unemployment เป็น noun</p><small>ดูชนิดจาก suffix สุดท้าย (-ment)</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ใช้หน้า &quot;แผนผังรากศัพท์&quot; ในแอปนี้ฝึกดูคำที่มีแกนเดียวกัน จะเห็นว่าคำยาวส่วนใหญ่สร้างจากส่วนที่เรารู้จักอยู่แล้ว</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Due to a misunderstanding, the reorganization was unexpectedly delayed. The results became unpredictable.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">Due to a <mark>misunderstanding</mark>, the <mark>reorganization</mark> was <mark>unexpectedly</mark> delayed. The results became <mark>unpredictable</mark>.</div><div class=\"ts-th\">เนื่องจากความเข้าใจผิด การปรับโครงสร้างจึงล่าช้าโดยไม่คาดคิด ผลลัพธ์จึงคาดเดาไม่ได้</div></div></div></div>","easy":{"say":"คำยาวเหมือนหัวหอม ลอก suffix ท้ายสุดกับ prefix หน้าสุดออกทีละชั้น จนเหลือแกน แล้วประกอบความหมายกลับ","eg":["un + predict + able = <b>unpredictable</b>","ไม่ + ทำนาย + ได้ = คาดเดาไม่ได้"],"rule":"suffix ตัวสุดท้ายบอกชนิดของคำ"}},{"id":"fam","en":"What is a word family?","th":"ครอบครัวคำ (word family) คืออะไร","intro":"ครอบครัวคำคือกลุ่มคำที่มีแกนเดียวกัน แต่เป็นคำต่างชนิด รู้หนึ่งคำ ก็เดาคำอื่นในครอบครัวได้","r":[],"tips":[],"items":[{"id":"wf-fam-0","p":0,"s":"คำใดไม่อยู่ในครอบครัวเดียวกับ \"employ\"?","gap":0,"o":{"A":"unemployment","B":"employer","C":"employee","D":"emphasis"},"oth":{},"a":"D","x":"employer, employee, unemployment มีแกน employ ส่วน emphasis (การเน้น) เป็นคนละคำ","v":[]},{"id":"wf-fam-1","p":0,"s":"adjective ในครอบครัว \"success\" คือคำใด?","gap":0,"o":{"A":"successfully","B":"success","C":"successful","D":"succeed"},"oth":{},"a":"C","x":"-ful เป็น suffix ของ adjective","v":[]},{"id":"wf-fam-2","p":0,"s":"The project was completed _____.","gap":1,"o":{"A":"successful","B":"success","C":"succeed","D":"successfully"},"oth":{},"a":"D","x":"ขยายกริยา completed ใช้ adverb","v":[]},{"id":"wf-fam-3","p":0,"s":"We want our new product to _____.","gap":1,"o":{"A":"successful","B":"success","C":"successfully","D":"succeed"},"oth":{},"a":"D","x":"หลัง to ใช้กริยา","v":[]},{"id":"wf-fam-4","p":0,"s":"\"economical car\" หมายถึงอะไร?","gap":0,"o":{"A":"รถราคาแพง","B":"รถทางเศรษฐกิจ","C":"รถประหยัด","D":"รถของนักเศรษฐศาสตร์"},"oth":{},"a":"C","x":"economical = ประหยัด ต่างจาก economic = เกี่ยวกับเศรษฐกิจ","v":[]},{"id":"wf-fam-5","p":0,"s":"noun ในครอบครัว \"decide\" ที่แปลว่า \"การตัดสินใจ\" คือคำใด?","gap":0,"o":{"A":"decisive","B":"decided","C":"decision","D":"decisively"},"oth":{},"a":"C","x":"decide → decision","v":[]},{"id":"wf-fam-6","p":0,"s":"She is a very _____ manager; she makes choices quickly.","gap":1,"o":{"A":"decisive","B":"decisively","C":"decision","D":"decide"},"oth":{},"a":"A","x":"หลัง very และหน้าคำนาม manager ใช้ adjective: decisive (เด็ดขาด)","v":[]},{"id":"wf-fam-7","p":0,"s":"ข้อใดเรียงครอบครัวคำ noun / verb / adjective / adverb ถูกต้อง?","gap":0,"o":{"A":"safe / – / safely / safety","B":"safely / safe / safety / –","C":"safe / safety / safely / –","D":"safety / – / safe / safely"},"oth":{},"a":"D","x":"safety (n.) · safe (adj.) · safely (adv.) และไม่มีกริยาโดยตรง","v":[]},{"id":"wf-fam-8","p":0,"s":"คำใดอยู่ในครอบครัวเดียวกับ \"enable\" (ทำให้สามารถ)?","gap":0,"o":{"A":"eat","B":"unable","C":"expression","D":"external"},"oth":{},"a":"B","x":"enable กับ unable มีแกนเดียวกัน (ครอบครัว able)","v":[]},{"id":"wf-fam-9","p":0,"s":"คำใดอยู่ในครอบครัวเดียวกับ \"ensure\" (ทำให้มั่นใจ)?","gap":0,"o":{"A":"surely","B":"edge","C":"entertain","D":"establish"},"oth":{},"a":"A","x":"ensure กับ surely มีแกนเดียวกัน (ครอบครัว sure)","v":[]},{"id":"wf-fam-10","p":0,"s":"คำใดอยู่ในครอบครัวเดียวกับ \"truth\" (ความจริง)?","gap":0,"o":{"A":"too","B":"truly","C":"term","D":"trend"},"oth":{},"a":"B","x":"truth กับ truly มีแกนเดียวกัน (ครอบครัว true)","v":[]},{"id":"wf-fam-11","p":0,"s":"คำใดอยู่ในครอบครัวเดียวกับ \"writing\" (การเขียน)?","gap":0,"o":{"A":"wear","B":"write","C":"wave","D":"wire"},"oth":{},"a":"B","x":"writing กับ write มีแกนเดียวกัน (ครอบครัว write)","v":[]}],"grp":"Word Families — ครอบครัวคำและรากศัพท์","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">ครอบครัวคำเหมือน <b>ครอบครัวจริง</b>: มีนามสกุลเดียวกัน (แกน employ) แต่แต่ละคนมีหน้าที่ต่างกัน คนหนึ่งเป็นคน (employee) คนหนึ่งเป็นการกระทำ (employment) คนหนึ่งเป็นลักษณะ (employable)</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>noun</th><th>verb</th><th>adjective</th><th>adverb</th></tr></thead><tbody><tr><td>employment, employer, employee</td><td>employ</td><td>employable, unemployed</td><td>-</td></tr><tr><td>success</td><td>succeed</td><td>successful</td><td>successfully</td></tr><tr><td>decision</td><td>decide</td><td>decisive</td><td>decisively</td></tr><tr><td>production, product, productivity</td><td>produce</td><td>productive</td><td>productively</td></tr><tr><td>safety</td><td>-</td><td>safe</td><td>safely</td></tr><tr><td>efficiency</td><td>-</td><td>efficient</td><td>efficiently</td></tr></tbody></table></div><figcaption>ตารางครอบครัวคำ: อ่านแนวนอน = คำในครอบครัวเดียวกัน</figcaption></figure><figure class=\"bv bv-parts\"><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">employer</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">employ</b><small>จ้าง</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">er</b><small>ผู้...</small></span></span><span class=\"wp-th\">นายจ้าง</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">employee</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">employ</b><small>จ้าง</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ee</b><small>ผู้ได้รับ</small></span></span><span class=\"wp-th\">ลูกจ้าง</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">employment</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-b\"><b lang=\"en\">employ</b><small>จ้าง</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ment</b><small>การ...</small></span></span><span class=\"wp-th\">การจ้างงาน</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">unemployed</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">un</b><small>ไม่</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-b\"><b lang=\"en\">employ</b><small>จ้าง</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ed</b><small>ที่ถูก...</small></span></span><span class=\"wp-th\">ว่างงาน</span></div><figcaption>สมาชิกในครอบครัว employ</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">จำเป็นตาราง</div><div class=\"tf-value\">noun / verb / adj / adv</div></div><div class=\"tense-formula\"><div class=\"tf-label\">เลือกรูปในข้อสอบ</div><div class=\"tf-value\">ดูตำแหน่ง → เลือกสมาชิกที่ชนิดตรง</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ระวัง</div><div class=\"tf-value\">บางช่องมีหลายคำ ความหมายต่างกัน</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>หนึ่งแกน หลายชนิด</b> — employ (v.) → employer / employee / employment (n.) → employable / unemployed (adj.)<br><span class=\"bv-rx\">We <b>employ</b> 300 people. Our <b>employees</b> like their <b>employment</b> terms. <small>เราจ้าง 300 คน พนักงานพอใจเงื่อนไขการจ้างงาน</small></span></p><p><b>ตารางครอบครัวคำ</b> — เขียนเป็นตาราง 4 ช่อง noun / verb / adjective / adverb ช่วยจำได้ทั้งชุด<br><span class=\"bv-rx\">success (n.) · succeed (v.) · successful (adj.) · successfully (adv.)</span></p><p><b>บางช่องอาจว่างหรือมีหลายคำ</b> — ไม่ใช่ทุกคำมีครบสี่ชนิด และบางช่องมีหลายคำที่ความหมายต่างกัน<br><span class=\"bv-rx\">economy (เศรษฐกิจ) · economic (ทางเศรษฐกิจ) · economical (ประหยัด)</span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The factory employs 500 people.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The factory employs 500 people.</div><div class=\"ex-th thai\">โรงงานจ้างงาน 500 คน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Employee safety is our priority.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Employee safety is our priority.</div><div class=\"ex-th thai\">ความปลอดภัยของพนักงานคือสิ่งสำคัญ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The new machine is more productive.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The new machine is more productive.</div><div class=\"ex-th thai\">เครื่องใหม่ผลิตได้มากกว่า</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Productivity rose by 8%.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Productivity rose by 8%.</div><div class=\"ex-th thai\">ผลิตภาพเพิ่มขึ้น 8%</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ He is an employment of ABC.</p><p class=\"ok\">✓ He is an employee of ABC.</p><small>คน = employee / การจ้าง = employment</small></div><div class=\"bv-m\"><p class=\"no\">✗ an economic car</p><p class=\"ok\">✓ an economical car</p><small>ประหยัด = economical</small></div><div class=\"bv-m\"><p class=\"no\">✗ We need to success.</p><p class=\"ok\">✓ We need to succeed.</p><small>หลัง to ใช้กริยา succeed</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ในหน้าคลังคำของแอปนี้ ทุกคำมีบรรทัด &quot;ครอบครัวคำ&quot; บอกคำอื่นในคลังที่อยู่ครอบครัวเดียวกัน แตะเพื่อฟังเสียงทีละคำ</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Our employer values productivity. The new production line is very productive, and every employee works safely.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">Our <mark>employer</mark> values <mark>productivity</mark>. The new <mark>production</mark> line is very <mark>productive</mark>, and every <mark>employee</mark> works <mark>safely</mark>.</div><div class=\"ts-th\">นายจ้างของเราให้ความสำคัญกับผลิตภาพ ไลน์ผลิตใหม่ผลิตได้มาก และพนักงานทุกคนทำงานอย่างปลอดภัย</div></div></div></div>","easy":{"say":"ครอบครัวคำคือคำที่มี \"นามสกุล\" เดียวกัน (แกนเดียวกัน) แต่เป็นคำต่างชนิด จำเป็นตาราง noun / verb / adj / adv","eg":["<b>employ</b> · employ<b>er</b> · employ<b>ee</b> · employ<b>ment</b>","จ้าง · นายจ้าง · ลูกจ้าง · การจ้างงาน"],"rule":"รู้หนึ่งคำ เดาได้ทั้งครอบครัว"}},{"id":"famtbl","en":"Word families that appear in tests","th":"ครอบครัวคำที่ออกสอบบ่อย","intro":"ครอบครัวคำเหล่านี้ออกในข้อสอบเลือกรูปคำบ่อยมาก และใช้ในอีเมลกับรายงานทุกวัน","r":[],"tips":[],"items":[{"id":"wf-famtbl-0","p":0,"s":"Our prices are very _____.","gap":1,"o":{"A":"competitively","B":"compete","C":"competitive","D":"competition"},"oth":{},"a":"C","x":"หลัง very และ be ใช้ adjective: competitive","v":[]},{"id":"wf-famtbl-1","p":0,"s":"The _____ for the job closes on Friday.","gap":1,"o":{"A":"apply","B":"applicant","C":"application","D":"applicable"},"oth":{},"a":"C","x":"ใบสมัคร / การสมัคร = application (applicant = ผู้สมัคร)","v":[]},{"id":"wf-famtbl-2","p":0,"s":"The machine works _____; it never stops.","gap":1,"o":{"A":"rely","B":"reliability","C":"reliable","D":"reliably"},"oth":{},"a":"D","x":"ขยายกริยา works ใช้ adverb","v":[]},{"id":"wf-famtbl-3","p":0,"s":"Thank you for your _____.","gap":1,"o":{"A":"attentive","B":"attention","C":"attend","D":"attendee"},"oth":{},"a":"B","x":"Thank you for your attention = ขอบคุณที่ตั้งใจฟัง","v":[]},{"id":"wf-famtbl-4","p":0,"s":"_____ at the meeting is required.","gap":1,"o":{"A":"Attentive","B":"Attend","C":"Attendance","D":"Attendee"},"oth":{},"a":"C","x":"การเข้าร่วม (ประธานของประโยค) = attendance","v":[]},{"id":"wf-famtbl-5","p":0,"s":"We need _____ data for the report.","gap":1,"o":{"A":"accurateness","B":"accuracy","C":"accurately","D":"accurate"},"oth":{},"a":"D","x":"หน้าคำนาม data ใช้ adjective","v":[]},{"id":"wf-famtbl-6","p":0,"s":"The brochure is very _____.","gap":1,"o":{"A":"information","B":"informative","C":"informatively","D":"inform"},"oth":{},"a":"B","x":"informative = ให้ข้อมูลดี","v":[]},{"id":"wf-famtbl-7","p":0,"s":"The rule is _____ to all visitors.","gap":1,"o":{"A":"applicant","B":"applicable","C":"apply","D":"application"},"oth":{},"a":"B","x":"be applicable to = ใช้บังคับกับ","v":[]},{"id":"wf-famtbl-8","p":0,"s":"คำใดอยู่ในครอบครัวเดียวกับ \"actor\" (นักแสดงชาย)?","gap":0,"o":{"A":"app","B":"allow","C":"award","D":"action"},"oth":{},"a":"D","x":"actor กับ action มีแกนเดียวกัน (ครอบครัว act)","v":[]},{"id":"wf-famtbl-9","p":0,"s":"คำใดอยู่ในครอบครัวเดียวกับ \"sure\" (แน่ใจ)?","gap":0,"o":{"A":"surely","B":"story","C":"suffer","D":"similar"},"oth":{},"a":"A","x":"sure กับ surely มีแกนเดียวกัน (ครอบครัว sure)","v":[]},{"id":"wf-famtbl-10","p":0,"s":"คำใดอยู่ในครอบครัวเดียวกับ \"similar\" (คล้ายกัน)?","gap":0,"o":{"A":"sing","B":"similarly","C":"sailor","D":"slightly"},"oth":{},"a":"B","x":"similar กับ similarly มีแกนเดียวกัน (ครอบครัว similar)","v":[]},{"id":"wf-famtbl-11","p":0,"s":"คำใดอยู่ในครอบครัวเดียวกับ \"offend\" (ทำให้ขุ่นเคือง)?","gap":0,"o":{"A":"offensive","B":"obtain","C":"opposition","D":"oven"},"oth":{},"a":"A","x":"offend กับ offensive มีแกนเดียวกัน (ครอบครัว offend)","v":[]}],"grp":"Word Families — ครอบครัวคำและรากศัพท์","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">ครอบครัวคำในหน้านี้คือ \"<b>ลูกค้าประจำ</b>\" ของข้อสอบ ถ้าจำเป็นตารางได้ ข้อ word form ส่วนใหญ่ตอบได้ในไม่กี่วินาที</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>noun</th><th>verb</th><th>adjective</th><th>adverb</th></tr></thead><tbody><tr><td>competition / competitor</td><td>compete</td><td>competitive</td><td>competitively</td></tr><tr><td>management / manager</td><td>manage</td><td>manageable / managerial</td><td>-</td></tr><tr><td>information</td><td>inform</td><td>informative</td><td>informatively</td></tr><tr><td>communication</td><td>communicate</td><td>communicative</td><td>-</td></tr><tr><td>reliability</td><td>rely</td><td>reliable</td><td>reliably</td></tr><tr><td>accuracy</td><td>-</td><td>accurate</td><td>accurately</td></tr><tr><td>application / applicant</td><td>apply</td><td>applicable</td><td>-</td></tr><tr><td>attendance / attendee / attention</td><td>attend</td><td>attentive</td><td>attentively</td></tr></tbody></table></div><figcaption>ครอบครัวคำที่ควรจำเป็นชุด</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">คน</div><div class=\"tf-value\">-er / -or / -ant / -ee</div></div><div class=\"tense-formula\"><div class=\"tf-label\">สิ่ง / การ</div><div class=\"tf-value\">-tion / -ance / -ment</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ลักษณะ</div><div class=\"tf-value\">-ive / -able / -ful</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>ธุรกิจ</b> — compete / competition / competitive / competitively · produce / product / production / productive · manage / management / manager / manageable</p><p><b>การสื่อสาร</b> — inform / information / informative · communicate / communication / communicative · explain / explanation / explanatory</p><p><b>คุณภาพ</b> — rely / reliability / reliable / reliably · accurate / accuracy / accurately · consistent / consistency / consistently</p><p><b>การทำงาน</b> — apply / application / applicant / applicable · attend / attendance / attendee / attention / attentive</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Competition in the market is strong.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Competition in the market is strong.</div><div class=\"ex-th thai\">การแข่งขันในตลาดสูง</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"All applicants must take a test.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">All applicants must take a test.</div><div class=\"ex-th thai\">ผู้สมัครทุกคนต้องทำแบบทดสอบ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The supplier delivers reliably.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The supplier delivers reliably.</div><div class=\"ex-th thai\">ผู้จัดหาส่งของได้สม่ำเสมอ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Attendance is 95% this month.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Attendance is 95% this month.</div><div class=\"ex-th thai\">อัตราการมาทำงานเดือนนี้ 95%</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Thank you for your attend.</p><p class=\"ok\">✓ Thank you for your attention / attendance.</p><small>หลัง your ใช้ noun</small></div><div class=\"bv-m\"><p class=\"no\">✗ He is a good applicant (หมายถึงใบสมัคร)</p><p class=\"ok\">✓ application = ใบสมัคร</p><small>applicant = คน</small></div><div class=\"bv-m\"><p class=\"no\">✗ a manage team</p><p class=\"ok\">✓ a management team</p><small>ขยายคำนาม team ใช้ noun management</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ทำบัตรคำของตัวเอง: หน้าบัตรเขียนแกน (compete) หลังบัตรเขียนตารางสี่ช่อง ทบทวนวันละ 5 ครอบครัว</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The management team wants reliable suppliers and accurate data. Competition is strong, so we must stay competitive.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The <mark>management</mark> team wants <mark>reliable</mark> suppliers and <mark>accurate</mark> data. <mark>Competition</mark> is strong, so we must stay <mark>competitive</mark>.</div><div class=\"ts-th\">ทีมผู้บริหารต้องการผู้จัดหาที่ไว้ใจได้และข้อมูลที่แม่นยำ การแข่งขันสูง เราต้องรักษาความสามารถในการแข่งขัน</div></div></div></div>","easy":{"say":"จำครอบครัวคำที่ออกสอบบ่อยเป็นตาราง แล้วเลือกสมาชิกที่ชนิดตรงกับตำแหน่งในประโยค","eg":["compete · compet<b>ition</b> · compet<b>itive</b> · compet<b>itively</b>","แข่ง · การแข่งขัน · ที่แข่งขันได้ · อย่างแข่งขันได้"],"rule":"คน -er/-ant/-ee · สิ่ง -tion/-ance · ลักษณะ -ive/-able"}},{"id":"root","en":"Latin and Greek roots","th":"รากศัพท์ละติน-กรีก คืออะไร","intro":"คำอังกฤษประมาณครึ่งหนึ่งมาจากภาษาละตินและกรีก (ผ่านภาษาฝรั่งเศส) รากเหล่านี้ใช้เดี่ยวไม่ได้ แต่ปรากฏซ้ำในคำจำนวนมาก","r":[],"tips":[],"items":[{"id":"wf-root-0","p":0,"s":"ข้อใดคือ root ไม่ใช่ base?","gap":0,"o":{"A":"happy ใน unhappy","B":"port ใน export","C":"read ใน reread","D":"employ ใน employment"},"oth":{},"a":"B","x":"port ใช้เดี่ยวในความหมาย \"ขน\" ไม่ได้ จึงเป็น root","v":[]},{"id":"wf-root-1","p":0,"s":"root \"port\" แปลว่าอะไร?","gap":0,"o":{"A":"ประตูเรือ","B":"มอง","C":"ส่วน","D":"ขน / ถือ"},"oth":{},"a":"D","x":"port (ละติน portare) = ขน เช่น transport = ขนข้าม","v":[]},{"id":"wf-root-2","p":0,"s":"คำใดน่าจะมาจากละติน?","gap":0,"o":{"A":"go","B":"inquire","C":"eat","D":"ask"},"oth":{},"a":"B","x":"คำวิชาการและทางการมักมาจากละติน ส่วน ask, go, eat มาจากภาษาอังกฤษดั้งเดิม","v":[]},{"id":"wf-root-3","p":0,"s":"produce กับ product มีรากเดียวกันคือ duc / duct แปลว่าอะไร?","gap":0,"o":{"A":"มอง","B":"นำ / พาไป","C":"ส่ง","D":"ทำ"},"oth":{},"a":"B","x":"duc / duct (ละติน ducere) = นำ","v":[]},{"id":"wf-root-4","p":0,"s":"ทำไมรากศัพท์หนึ่งจึงมีหลายรูป เช่น mit / miss?","gap":0,"o":{"A":"ไม่มีเหตุผล","B":"เพราะภาษาละตินผันรูปกริยา","C":"เพราะสะกดผิด","D":"เพราะเป็นคนละราก"},"oth":{},"a":"B","x":"mittere (ส่ง) ผันเป็น missus จึงได้ทั้ง submit และ submission","v":[]},{"id":"wf-root-5","p":0,"s":"การใช้รากศัพท์เดาความหมายควรทำอย่างไร?","gap":0,"o":{"A":"ไม่ต้องดูบริบท","B":"ใช้ได้กับทุกคำ","C":"เชื่อความหมายรากเสมอ","D":"เดาจากราก แล้วตรวจกับบริบท"},"oth":{},"a":"D","x":"รากเป็นเบาะแส ความหมายจริงอาจเปลี่ยนไปแล้ว","v":[]},{"id":"wf-root-6","p":0,"s":"คำใดเป็นคำพื้นฐานที่แยกรากไม่ได้?","gap":0,"o":{"A":"house","B":"transport","C":"inspect","D":"describe"},"oth":{},"a":"A","x":"house มาจากภาษาอังกฤษโบราณ ไม่มีรากละติน-กรีกให้แยก","v":[]},{"id":"wf-root-7","p":0,"s":"\"inspect\" = in (เข้าไป) + spect (มอง) แปลตามรากว่าอะไร?","gap":0,"o":{"A":"มองเข้าไป = ตรวจสอบ","B":"มองออกไป","C":"มองไม่เห็น","D":"มองข้าม"},"oth":{},"a":"A","x":"spect = มอง","v":[]},{"id":"wf-root-8","p":0,"s":"ราก \"port\" ในคำว่า \"reporter\" (ผู้สื่อข่าว) แปลว่าอะไร?","gap":0,"o":{"A":"เสียง","B":"แตก","C":"ขน / ถือ","D":"พิษ"},"oth":{},"a":"C","x":"reporter = re- + port + -er ราก port มาจากละติน portare แปลว่า ขน / ถือ","v":[]},{"id":"wf-root-9","p":0,"s":"ราก \"spect\" ในคำว่า \"prospect\" (ความเป็นไปได้) แปลว่าอะไร?","gap":0,"o":{"A":"สัญญา / ตอบ","B":"แรก / สำคัญที่สุด","C":"นำ / ขน","D":"มอง / ดู"},"oth":{},"a":"D","x":"prospect = pro- + spect ราก spec / spect มาจากละติน specere แปลว่า มอง / ดู","v":[]},{"id":"wf-root-10","p":0,"s":"คำใดมีราก duc / duct (นำ / พาไป)?","gap":0,"o":{"A":"fault","B":"solid","C":"produce","D":"definitely"},"oth":{},"a":"C","x":"produce = pro- + duce","v":[]},{"id":"wf-root-11","p":0,"s":"ราก \"spec\" ในคำว่า \"specific\" (เฉพาะเจาะจง) แปลว่าอะไร?","gap":0,"o":{"A":"มอง / ดู","B":"ค้าขาย","C":"ค่า / แข็งแรง","D":"ดูแล / ใส่ใจ"},"oth":{},"a":"A","x":"specific = spec + i + fic ราก spec / spect มาจากละติน specere แปลว่า มอง / ดู","v":[]}],"grp":"Word Families — ครอบครัวคำและรากศัพท์","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">รากศัพท์เหมือน <b>DNA ของคำ</b> คำที่ดูไม่เหมือนกัน (export, portable, report) อาจมี DNA เดียวกัน (port = ขน) ประวัติศาสตร์อธิบายได้: ปี 1066 ชาวนอร์มันที่พูดฝรั่งเศสปกครองอังกฤษ คำละตินจำนวนมากจึงเข้ามาในภาษาอังกฤษ</div><figure class=\"bv bv-parts\"><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">export</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">ex</b><small>ออก</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">port</b><small>ขน</small></span></span><span class=\"wp-th\">ส่งออก</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">import</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">im</b><small>เข้า</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">port</b><small>ขน</small></span></span><span class=\"wp-th\">นำเข้า</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">transport</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">trans</b><small>ข้าม</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">port</b><small>ขน</small></span></span><span class=\"wp-th\">ขนส่ง</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">portable</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-r\"><b lang=\"en\">port</b><small>ขน</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">able</b><small>...ได้</small></span></span><span class=\"wp-th\">พกพาได้</span></div><figcaption>root เดียว (port = ขน) อยู่ในหลายคำ</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ที่มา</th><th>ลักษณะ</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>อังกฤษดั้งเดิม</td><td>คำพื้นฐาน สั้น ใช้ทุกวัน</td><td>go, eat, ask, house, work</td></tr><tr><td>ละติน (มักผ่านฝรั่งเศส)</td><td>คำทางการ ธุรกิจ กฎหมาย</td><td>inquire, produce, employ, contract</td></tr><tr><td>กรีก</td><td>วิทยาศาสตร์ เทคโนโลยี การแพทย์</td><td>telephone, technology, psychology</td></tr><tr><td>ภาษาอื่น</td><td>อาหาร สิ่งของเฉพาะ</td><td>tea (จีน), coffee (อาหรับ), tsunami (ญี่ปุ่น)</td></tr></tbody></table></div><figcaption>ในคลังคำของแอปนี้ ทุกคำที่รู้ที่มาจะบอก &quot;ที่มา&quot; ไว้ใต้คำ</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">root</div><div class=\"tf-value\">ส่วนละติน-กรีก ใช้เดี่ยวไม่ได้</div></div><div class=\"tense-formula\"><div class=\"tf-label\">base</div><div class=\"tf-value\">คำที่ใช้เดี่ยวได้</div></div><div class=\"tense-formula\"><div class=\"tf-label\">วิธีใช้</div><div class=\"tf-value\">เดาจากราก → ตรวจกับบริบท</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>root ต่างจาก base</b> — base เป็นคำที่ใช้เดี่ยวได้ (employ) / root เป็นส่วนจากละติน-กรีกที่ใช้เดี่ยวไม่ได้ (port = ขน, dict = พูด)<br><span class=\"bv-rx\"><b>port</b>: export, import, transport, portable <small>ส่งออก, นำเข้า, ขนส่ง, พกพาได้</small></span></p><p><b>คำทั่วไปส่วนใหญ่มาจากภาษาอังกฤษดั้งเดิม</b> — คำพื้นฐานอย่าง go, eat, house, work มาจากภาษาอังกฤษโบราณ แยกรากไม่ได้ / คำวิชาการ ธุรกิจ เทคนิค มักมาจากละติน-กรีก<br><span class=\"bv-rx\">ask (อังกฤษดั้งเดิม) / inquire (ละติน) <small>ถาม</small></span></p><p><b>รากหนึ่งมีได้หลายรูป</b> — รูปเปลี่ยนตามการผันในภาษาเดิม เช่น duc / duct (นำ), mit / miss (ส่ง), spec / spect (มอง)<br><span class=\"bv-rx\">pro<b>duce</b> / pro<b>duct</b>, sub<b>mit</b> / sub<b>miss</b>ion</span></p><p><b>ใช้รากเดา แต่ตรวจกับบริบทเสมอ</b> — ความหมายรากคือ \"เบาะแส\" ไม่ใช่คำแปลตรงตัว เพราะความหมายเปลี่ยนไปตามเวลา<br><span class=\"bv-rx\">in + vent (มา) = invent <small>สิ่งที่ &quot;มาพบ&quot; = ประดิษฐ์</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We export rice to Japan.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We export rice to Japan.</div><div class=\"ex-th thai\">เราส่งออกข้าวไปญี่ปุ่น</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please inspect the parts.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please inspect the parts.</div><div class=\"ex-th thai\">กรุณาตรวจชิ้นส่วน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"He described the problem.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">He described the problem.</div><div class=\"ex-th thai\">เขาอธิบายปัญหา (de + scribe = เขียนลง)</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The invention changed the industry.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The invention changed the industry.</div><div class=\"ex-th thai\">สิ่งประดิษฐ์นี้เปลี่ยนอุตสาหกรรม</div></div></div></div><h3 class=\"bv-h\">กับดักของการเดาจากราก</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ sport = s + port (ขน)</p><p class=\"ok\">✓ sport มาจาก disport (พาออกไปพักผ่อน) ความเชื่อมโยงอยู่ไกลมาก</p><small>ตัวอักษรเหมือนรากไม่ได้แปลว่ามีรากนั้นเสมอ</small></div><div class=\"bv-m\"><p class=\"no\">✗ ทุกคำแยกรากได้</p><p class=\"ok\">✓ คำพื้นฐานจากอังกฤษดั้งเดิมแยกไม่ได้</p><small>ในคลังคำ ราวครึ่งหนึ่งแยกส่วนได้ อีกครึ่งเป็นคำพื้นฐาน</small></div><div class=\"bv-m\"><p class=\"no\">✗ invent = มาข้างใน</p><p class=\"ok\">✓ invent = ประดิษฐ์</p><small>ความหมายรากเป็นเบาะแส ต้องตรวจความหมายจริง</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ทีมงานตรวจที่มาของคำในคลังจากฐานข้อมูลนิรุกติศาสตร์ (Wiktionary) ก่อนจะใส่ราก คำไหนไม่มีหลักฐานจะไม่ถูกเดารากให้ เพื่อไม่ให้จำผิด</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The company exports portable heaters. It imports parts from Korea and transports them by ship. Each unit is inspected before export.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The company <mark>exports</mark> <mark>portable</mark> heaters. It <mark>imports</mark> parts from Korea and <mark>transports</mark> them by ship. Each unit is <mark>inspected</mark> before <mark>export</mark>.</div><div class=\"ts-th\">บริษัทส่งออกฮีตเตอร์แบบพกพา นำเข้าชิ้นส่วนจากเกาหลีและขนส่งทางเรือ ทุกเครื่องได้รับการตรวจก่อนส่งออก</div></div></div></div>","easy":{"say":"รากศัพท์คือ DNA ของคำจากภาษาละติน-กรีก ใช้เดี่ยวไม่ได้ แต่อยู่ในหลายคำ เช่น port = ขน","eg":["ex<b>port</b> · im<b>port</b> · trans<b>port</b> · <b>port</b>able","ส่งออก · นำเข้า · ขนส่ง · พกพาได้"],"rule":"รากเป็นเบาะแส ตรวจกับบริบทเสมอ"}},{"id":"greek1","en":"Roots worth knowing (1)","th":"รากศัพท์น่ารู้ 1: micro, philo, phone, polis, psych, tele","intro":"รากกรีก 6 ตัวนี้อยู่ในคำวิทยาศาสตร์ เทคโนโลยี และชีวิตประจำวันจำนวนมาก รู้รากแล้วเดาคำใหม่ได้ทันที","r":[],"tips":[],"items":[{"id":"wf-greek1-0","p":0,"s":"\"microscope\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"เครื่องฟังเสียงเล็ก","B":"เครื่องมองไกล","C":"เครื่องวัดเล็ก","D":"เครื่องมองสิ่งเล็ก"},"oth":{},"a":"D","x":"micro = เล็ก + scope = มอง","v":[]},{"id":"wf-greek1-1","p":0,"s":"\"telescope\" ต่างจาก \"microscope\" อย่างไร?","gap":0,"o":{"A":"telescope มองไกล / microscope มองสิ่งเล็ก","B":"ทั้งสองใช้ฟัง","C":"telescope มองเล็ก / microscope มองไกล","D":"เหมือนกันทุกอย่าง"},"oth":{},"a":"A","x":"tele = ไกล / micro = เล็ก","v":[]},{"id":"wf-greek1-2","p":0,"s":"ราก \"phone\" ใน telephone และ microphone แปลว่าอะไร?","gap":0,"o":{"A":"โทร","B":"เครื่อง","C":"ไกล","D":"เสียง"},"oth":{},"a":"D","x":"phone (กรีก phone) = เสียง","v":[]},{"id":"wf-greek1-3","p":0,"s":"\"philosophy\" ประกอบด้วยรากใด?","gap":0,"o":{"A":"phi + losophy","B":"phil (เต็ม) + osophy (คิด)","C":"philo (รัก) + sophy (ปัญญา)","D":"philo (เมือง) + sophy (จิต)"},"oth":{},"a":"C","x":"ปรัชญา = ความรักในปัญญา","v":[]},{"id":"wf-greek1-4","p":0,"s":"\"metropolis\" แปลว่าอะไร?","gap":0,"o":{"A":"มหานคร","B":"ตำรวจ","C":"การเมือง","D":"นักการเมือง"},"oth":{},"a":"A","x":"metro (แม่) + polis (เมือง) = เมืองแม่ = มหานคร","v":[]},{"id":"wf-greek1-5","p":0,"s":"ราก \"psych\" ใน psychology แปลว่าอะไร?","gap":0,"o":{"A":"ร่างกาย","B":"ชีวิต","C":"จิตใจ","D":"เสียง"},"oth":{},"a":"C","x":"psych (กรีก psykhe) = จิตใจ","v":[]},{"id":"wf-greek1-6","p":0,"s":"\"telepathy\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"การมองไกล","B":"โทรศัพท์ทางไกล","C":"รู้สึกถึงกันจากที่ไกล (โทรจิต)","D":"การเดินทางไกล"},"oth":{},"a":"C","x":"tele (ไกล) + pathy (ความรู้สึก)","v":[]},{"id":"wf-greek1-7","p":0,"s":"\"philanthropy\" หมายถึงอะไร?","gap":0,"o":{"A":"การปกครองเมือง","B":"การศึกษามนุษย์","C":"การกุศล (ความรักต่อมนุษย์)","D":"ความเกลียดมนุษย์"},"oth":{},"a":"C","x":"phil (รัก) + anthrop (มนุษย์) + y","v":[]},{"id":"wf-greek1-8","p":0,"s":"คำใดมีราก micro (เล็ก)?","gap":0,"o":{"A":"microfiber","B":"military","C":"reply","D":"collaborate"},"oth":{},"a":"A","x":"microfiber = micro + fiber","v":[]},{"id":"wf-greek1-9","p":0,"s":"ราก \"psycho\" ในคำว่า \"psychologist\" (นักจิตวิทยา) แปลว่าอะไร?","gap":0,"o":{"A":"จุด / แทง","B":"พลัง","C":"จิตใจ","D":"ตา / การมองเห็น"},"oth":{},"a":"C","x":"psychologist = psycho + logy + -ist ราก psych มาจากกรีก psykhe แปลว่า จิตใจ","v":[]},{"id":"wf-greek1-10","p":0,"s":"ราก \"micro\" ในคำว่า \"microscope\" (กล้องจุลทรรศน์) แปลว่าอะไร?","gap":0,"o":{"A":"เล็ก","B":"ดอกไม้","C":"ดูแล / ใส่ใจ","D":"มีอำนาจ / ทำได้"},"oth":{},"a":"A","x":"microscope = micro + scope ราก micro มาจากกรีก mikros แปลว่า เล็ก","v":[]}],"grp":"Word Families — ครอบครัวคำและรากศัพท์","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">รากกรีก 6 ตัวนี้เหมือน <b>ตัวอักษรรหัส</b> ที่ต่อกันได้: tele (ไกล) + phone (เสียง) = telephone, micro (เล็ก) + phone (เสียง) = microphone, tele (ไกล) + scope (มอง) = telescope ต่อรากสองตัว ได้คำใหม่หนึ่งคำ</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ราก</th><th>ความหมาย</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>micro-</td><td>เล็ก</td><td>microscope, microwave</td></tr><tr><td>philo-</td><td>รัก</td><td>philosophy, philanthropy</td></tr><tr><td>phone</td><td>เสียง</td><td>telephone, microphone</td></tr><tr><td>polis</td><td>เมือง</td><td>politics, metropolis</td></tr><tr><td>psych</td><td>จิต</td><td>psychology, psychic</td></tr><tr><td>tele-</td><td>ไกล</td><td>telescope, telepathy</td></tr></tbody></table></div><figcaption>รากศัพท์น่ารู้ 6 ตัว</figcaption></figure><figure class=\"bv bv-parts\"><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">telephone</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-r\"><b lang=\"en\">tele</b><small>ไกล</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">phone</b><small>เสียง</small></span></span><span class=\"wp-th\">เสียงจากที่ไกล = โทรศัพท์</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">microphone</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-r\"><b lang=\"en\">micro</b><small>เล็ก</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">phone</b><small>เสียง</small></span></span><span class=\"wp-th\">ทำเสียงเล็กให้ดัง = ไมโครโฟน</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">telescope</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-r\"><b lang=\"en\">tele</b><small>ไกล</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">scope</b><small>มอง</small></span></span><span class=\"wp-th\">มองไกล = กล้องโทรทรรศน์</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">psychology</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-r\"><b lang=\"en\">psycho</b><small>จิต</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">logy</b><small>วิชา</small></span></span><span class=\"wp-th\">วิชาเรื่องจิต = จิตวิทยา</span></div><figcaption>ต่อรากสองตัว = คำใหม่</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ต่อราก</div><div class=\"tf-value\">ราก + ราก (tele + phone)</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ราก + suffix</div><div class=\"tf-value\">psych + ic = psychic</div></div><div class=\"tense-formula\"><div class=\"tf-label\">รากเดียวหลายคำ</div><div class=\"tf-value\">phone: telephone, microphone, headphones</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>micro- = เล็ก</b> — microscope (กล้องจุลทรรศน์ = มองสิ่งเล็ก), microwave (คลื่นสั้นมาก), microchip, microphone<br><span class=\"bv-rx\">Look at the cells under a <b>micro</b>scope. <small>ดูเซลล์ด้วยกล้องจุลทรรศน์</small></span></p><p><b>philo- / phil = รัก</b> — philosophy (รัก + ปัญญา = ปรัชญา), philanthropy (รัก + มนุษย์ = การกุศล)<br><span class=\"bv-rx\">She studies <b>philo</b>sophy. <small>เธอเรียนปรัชญา</small></span></p><p><b>phone = เสียง</b> — telephone (ไกล + เสียง), microphone (เล็ก + เสียง = ขยายเสียงเล็ก), headphones, phonics<br><span class=\"bv-rx\">Please speak into the <b>micro</b><b>phone</b>. <small>กรุณาพูดใส่ไมโครโฟน</small></span></p><p><b>polis / polit = เมือง พลเมือง</b> — politics (เรื่องของเมือง = การเมือง), metropolis (เมืองแม่ = มหานคร), police, policy<br><span class=\"bv-rx\">Bangkok is a <b>metropolis</b>. <small>กรุงเทพฯ เป็นมหานคร</small></span></p><p><b>psych = จิตใจ</b> — psychology (วิชาเรื่องจิต = จิตวิทยา), psychic (เกี่ยวกับพลังจิต)<br><span class=\"bv-rx\">He has a degree in <b>psych</b>ology. <small>เขาจบจิตวิทยา</small></span></p><p><b>tele- = ไกล</b> — telescope (มองไกล = กล้องโทรทรรศน์), telepathy (รู้สึกไกล = โทรจิต), television, telephone<br><span class=\"bv-rx\">They watched the stars through a <b>tele</b>scope. <small>พวกเขาดูดาวผ่านกล้องโทรทรรศน์</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Heat the food in the microwave.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Heat the food in the microwave.</div><div class=\"ex-th thai\">อุ่นอาหารในไมโครเวฟ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The meeting is about local politics.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The meeting is about local politics.</div><div class=\"ex-th thai\">การประชุมเกี่ยวกับการเมืองท้องถิ่น</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"A psychologist helps people with stress.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">A psychologist helps people with stress.</div><div class=\"ex-th thai\">นักจิตวิทยาช่วยคนที่มีความเครียด</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The microphone is not working.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The microphone is not working.</div><div class=\"ex-th thai\">ไมโครโฟนไม่ทำงาน</div></div></div></div><h3 class=\"bv-h\">ระวังความหมาย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ microwave = คลื่นเล็ก (ขนาดเตา)</p><p class=\"ok\">✓ microwave = คลื่นไมโครเวฟ (ความยาวคลื่นสั้น)</p><small>micro บอกขนาดของคลื่น ไม่ใช่ขนาดเตา</small></div><div class=\"bv-m\"><p class=\"no\">✗ politics = ตำรวจ</p><p class=\"ok\">✓ politics = การเมือง / police = ตำรวจ</p><small>มาจากรากเดียวกัน (polis) แต่ความหมายต่างกัน</small></div><div class=\"bv-m\"><p class=\"no\">✗ phone = โทรศัพท์เสมอ</p><p class=\"ok\">✓ phone ในฐานะราก = เสียง</p><small>headphones, phonics ไม่ใช่โทรศัพท์</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> คำเหล่านี้หลายคำไม่มีในคลังคำ 5,478 คำ (เช่น telepathy, philanthropy) แต่รากเดียวกันช่วยให้อ่านคำใหม่ได้ ลองค้นหา &quot;tele&quot; ในหน้าคลังคำเพื่อดูคำที่มีอยู่</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"A psychologist and a philosopher talked about politics on television. They used a microphone so people in the metropolis could hear.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">A <mark>psychologist</mark> and a <mark>philosopher</mark> talked about <mark>politics</mark> on <mark>television</mark>. They used a <mark>microphone</mark> so people in the <mark>metropolis</mark> could hear.</div><div class=\"ts-th\">นักจิตวิทยากับนักปรัชญาคุยเรื่องการเมืองทางโทรทัศน์ พวกเขาใช้ไมโครโฟนเพื่อให้คนในมหานครได้ยิน</div></div></div></div>","easy":{"say":"รากกรีก 6 ตัว: micro เล็ก · philo รัก · phone เสียง · polis เมือง · psych จิต · tele ไกล ต่อสองรากได้คำใหม่","eg":["<b>tele</b> + <b>phone</b> = telephone","ไกล + เสียง = โทรศัพท์"],"rule":"micro เล็ก · philo รัก · phone เสียง · polis เมือง · psych จิต · tele ไกล"}},{"id":"greek2","en":"Roots worth knowing (2): science words","th":"รากศัพท์น่ารู้ 2: graph, scope, logy, photo, bio, geo, auto, chron","intro":"รากกรีกชุดนี้สร้างคำวิทยาศาสตร์และเทคโนโลยีจำนวนมาก ต่อกับรากชุดแรกได้อีก","r":[],"tips":[],"items":[{"id":"wf-greek2-0","p":0,"s":"\"photograph\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"วิชาแสง","B":"เขียนด้วยแสง","C":"มองไกล","D":"วาดด้วยมือ"},"oth":{},"a":"B","x":"photo (แสง) + graph (เขียน)","v":[]},{"id":"wf-greek2-1","p":0,"s":"\"geography\" คือวิชาอะไร?","gap":0,"o":{"A":"ภูมิศาสตร์ (เขียนเรื่องโลก)","B":"ธรณีวิทยา","C":"ชีววิทยา","D":"ประวัติศาสตร์"},"oth":{},"a":"A","x":"geo (โลก) + graphy (การเขียน)","v":[]},{"id":"wf-greek2-2","p":0,"s":"\"biology\" คือวิชาอะไร?","gap":0,"o":{"A":"ฟิสิกส์","B":"ภูมิศาสตร์","C":"ชีววิทยา","D":"จิตวิทยา"},"oth":{},"a":"C","x":"bio (ชีวิต) + logy (วิชา)","v":[]},{"id":"wf-greek2-3","p":0,"s":"\"autograph\" คืออะไร?","gap":0,"o":{"A":"รถยนต์","B":"ลายเซ็นที่เขียนเอง","C":"กราฟอัตโนมัติ","D":"รูปถ่ายอัตโนมัติ"},"oth":{},"a":"B","x":"auto (ตัวเอง) + graph (เขียน)","v":[]},{"id":"wf-greek2-4","p":0,"s":"เครื่องวัดอุณหภูมิเรียกว่าอะไร?","gap":0,"o":{"A":"thermometer","B":"geometer","C":"hydrometer","D":"chronometer"},"oth":{},"a":"A","x":"therm (ร้อน) + meter (วัด)","v":[]},{"id":"wf-greek2-5","p":0,"s":"\"synchronize\" หมายถึงอะไร?","gap":0,"o":{"A":"มองพร้อมกัน","B":"ทำให้ร้อนพร้อมกัน","C":"ทำให้เวลาตรงกัน","D":"เขียนพร้อมกัน"},"oth":{},"a":"C","x":"syn (ด้วยกัน) + chron (เวลา) + ize (ทำให้)","v":[]},{"id":"wf-greek2-6","p":0,"s":"\"hydraulic\" เกี่ยวกับอะไร?","gap":0,"o":{"A":"ลม","B":"แสง","C":"ไฟฟ้า","D":"ของเหลว / น้ำ (ระบบไฮดรอลิก)"},"oth":{},"a":"D","x":"hydr (น้ำ) = ระบบที่ใช้แรงดันของเหลว","v":[]},{"id":"wf-greek2-7","p":0,"s":"\"technology\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"วิชาเรื่องฝีมือการทำ","B":"วิชาเรื่องชีวิต","C":"วิชาเรื่องโลก","D":"การเขียนด้วยแสง"},"oth":{},"a":"A","x":"techn (ฝีมือ / ศิลปะการทำ) + logy (วิชา)","v":[]},{"id":"wf-greek2-8","p":0,"s":"ราก \"logy\" ในคำว่า \"psychologist\" (นักจิตวิทยา) แปลว่าอะไร?","gap":0,"o":{"A":"การเรียนรู้","B":"กฎ / มาตรฐาน","C":"คำพูด / วิชา","D":"ร้อง / สำรวจ"},"oth":{},"a":"C","x":"psychologist = psycho + logy + -ist ราก log / logy มาจากกรีก logos แปลว่า คำพูด / วิชา","v":[]},{"id":"wf-greek2-9","p":0,"s":"คำใดมีราก photo (แสง)?","gap":0,"o":{"A":"playwright","B":"investigate","C":"photograph","D":"editorial"},"oth":{},"a":"C","x":"photograph = photo + graph","v":[]},{"id":"wf-greek2-10","p":0,"s":"คำใดมีราก auto (ตัวเอง)?","gap":0,"o":{"A":"reduction","B":"superior","C":"automatic","D":"sister"},"oth":{},"a":"C","x":"automatic = automat + -ic","v":[]}],"grp":"Word Families — ครอบครัวคำและรากศัพท์","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">รากชุดนี้เหมือน <b>ชิ้นส่วนห้องแล็บ</b>: graph (เขียน) scope (มอง) meter (วัด) logy (วิชา) เป็น \"เครื่องมือ\" ส่วน photo (แสง) bio (ชีวิต) geo (โลก) therm (ร้อน) เป็น \"สิ่งที่ศึกษา\" ต่อกันได้เกือบทุกแบบ</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>สิ่งที่ศึกษา ↓ / เครื่องมือ →</th><th>-graph(y) เขียน</th><th>-logy วิชา</th><th>-meter วัด</th></tr></thead><tbody><tr><td>photo แสง</td><td>photograph</td><td>-</td><td>photometer</td></tr><tr><td>bio ชีวิต</td><td>biography</td><td>biology</td><td>-</td></tr><tr><td>geo โลก</td><td>geography</td><td>geology</td><td>geometry</td></tr><tr><td>therm ร้อน</td><td>-</td><td>-</td><td>thermometer</td></tr><tr><td>psych จิต</td><td>-</td><td>psychology</td><td>-</td></tr><tr><td>techn ฝีมือ</td><td>-</td><td>technology</td><td>-</td></tr></tbody></table></div><figcaption>ตารางต่อราก: แถว × คอลัมน์ = คำ</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ศึกษา</div><div class=\"tf-value\">สิ่งที่ศึกษา + -logy</div></div><div class=\"tense-formula\"><div class=\"tf-label\">บันทึก</div><div class=\"tf-value\">สิ่งที่บันทึก + -graph</div></div><div class=\"tense-formula\"><div class=\"tf-label\">วัด</div><div class=\"tf-value\">สิ่งที่วัด + -meter</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>graph / gram = เขียน วาด</b> — photograph, paragraph, diagram, program, autograph<br><span class=\"bv-rx\">Draw a <b>dia</b><b>gram</b> of the circuit. <small>วาดแผนภาพวงจร</small></span></p><p><b>scope = มอง / logy = วิชา</b> — microscope, telescope / biology, technology, psychology<br><span class=\"bv-rx\"><b>Bio</b><b>logy</b> is the study of life. <small>ชีววิทยาคือการศึกษาสิ่งมีชีวิต</small></span></p><p><b>photo = แสง / bio = ชีวิต / geo = โลก</b> — photograph (เขียนด้วยแสง), biography (เขียนเรื่องชีวิต), geography (เขียนเรื่องโลก)<br><span class=\"bv-rx\">a <b>bio</b><b>graphy</b> of Steve Jobs <small>ชีวประวัติ</small></span></p><p><b>auto = ตัวเอง / chron = เวลา / therm = ร้อน / hydr = น้ำ</b> — automatic, autograph / chronic, synchronize / thermometer, thermal / hydraulic, dehydrate<br><span class=\"bv-rx\"><b>Syn</b><b>chron</b>ize the clocks. <small>ตั้งนาฬิกาให้ตรงกัน</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Take a photograph of the defect.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Take a photograph of the defect.</div><div class=\"ex-th thai\">ถ่ายรูปจุดบกพร่อง</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The program runs automatically.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The program runs automatically.</div><div class=\"ex-th thai\">โปรแกรมทำงานอัตโนมัติ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The hydraulic press is very strong.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The hydraulic press is very strong.</div><div class=\"ex-th thai\">เครื่องอัดไฮดรอลิกแรงมาก</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Check the thermometer every hour.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Check the thermometer every hour.</div><div class=\"ex-th thai\">ตรวจเทอร์โมมิเตอร์ทุกชั่วโมง</div></div></div></div><h3 class=\"bv-h\">ระวังความหมาย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ geometry = ภูมิศาสตร์</p><p class=\"ok\">✓ geometry = เรขาคณิต (วัดโลก)</p><small>geography = ภูมิศาสตร์</small></div><div class=\"bv-m\"><p class=\"no\">✗ biography = วิชาชีววิทยา</p><p class=\"ok\">✓ biography = ชีวประวัติ</p><small>-graphy = การเขียน / -logy = วิชา</small></div><div class=\"bv-m\"><p class=\"no\">✗ program มาจาก pro + gram = ก่อน + น้ำหนัก</p><p class=\"ok\">✓ pro (ล่วงหน้า) + gram (เขียน) = สิ่งที่เขียนไว้ล่วงหน้า</p><small>gram ในที่นี้ = สิ่งที่เขียน ไม่ใช่หน่วยกรัม</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> คำลงท้าย -logy เน้นเสียงพยางค์ก่อน -logy เสมอ: bi-O-lo-gy, tech-NO-lo-gy, psy-CHO-lo-gy</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"In biology class, we used a microscope and took a photograph of a cell. Then we drew a diagram and checked the thermometer.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">In <mark>biology</mark> class, we used a <mark>microscope</mark> and took a <mark>photograph</mark> of a cell. Then we drew a <mark>diagram</mark> and checked the <mark>thermometer</mark>.</div><div class=\"ts-th\">ในชั้นเรียนชีววิทยา เราใช้กล้องจุลทรรศน์และถ่ายรูปเซลล์ จากนั้นวาดแผนภาพและดูเทอร์โมมิเตอร์</div></div></div></div>","easy":{"say":"รากวิทยาศาสตร์ต่อกันเหมือนตาราง: สิ่งที่ศึกษา (photo แสง, bio ชีวิต, geo โลก) + เครื่องมือ (graph เขียน, logy วิชา, meter วัด)","eg":["<b>bio</b> + <b>logy</b> = biology · <b>photo</b> + <b>graph</b> = photograph","ชีวิต + วิชา · แสง + เขียน"],"rule":"สิ่งที่ศึกษา + -logy / -graph / -meter"}},{"id":"move","en":"Latin roots of movement","th":"รากละตินเรื่องการเคลื่อนที่: port, duc, mit, mov, ced, ven, tract, fer","intro":"รากเหล่านี้บอกการเคลื่อนที่: ขน นำ ส่ง เคลื่อน ไป มา ดึง ใช้มากในคำธุรกิจ","r":[],"tips":[],"items":[{"id":"wf-move-0","p":0,"s":"\"transmit\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"ขนข้าม","B":"มาข้าม","C":"ดึงข้าม","D":"ส่งข้าม = ส่งผ่าน"},"oth":{},"a":"D","x":"trans (ข้าม) + mit (ส่ง)","v":[]},{"id":"wf-move-1","p":0,"s":"\"extract\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"ขนออก","B":"ดึงออก","C":"ส่งออก","D":"มาออก"},"oth":{},"a":"B","x":"ex (ออก) + tract (ดึง)","v":[]},{"id":"wf-move-2","p":0,"s":"\"prevent\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"ดึงก่อน","B":"ไปก่อน","C":"ส่งก่อน","D":"มาก่อน = ป้องกัน"},"oth":{},"a":"D","x":"pre (ก่อน) + vent (มา) = มาขวางไว้ก่อน","v":[]},{"id":"wf-move-3","p":0,"s":"Please _____ the form by email.","gap":1,"o":{"A":"subtract","B":"subject","C":"subway","D":"submit"},"oth":{},"a":"D","x":"sub + mit = ส่ง (ยื่น)","v":[]},{"id":"wf-move-4","p":0,"s":"คำใดมีราก \"duc\" (นำ)?","gap":0,"o":{"A":"intrude","B":"interview","C":"introvert","D":"introduce"},"oth":{},"a":"D","x":"intro (เข้าไป) + duce (นำ) = แนะนำ","v":[]},{"id":"wf-move-5","p":0,"s":"The cost must not _____ the budget.","gap":1,"o":{"A":"accede","B":"concede","C":"exceed","D":"excess only"},"oth":{},"a":"C","x":"ex (ออกไป) + ceed (ไป) = เกิน","v":[]},{"id":"wf-move-6","p":0,"s":"คำใดมีราก \"mov / mot\" (เคลื่อน)?","gap":0,"o":{"A":"propose","B":"promote","C":"promise","D":"protect"},"oth":{},"a":"B","x":"pro (ไปข้างหน้า) + mote (เคลื่อน) = ส่งเสริม / เลื่อนตำแหน่ง","v":[]},{"id":"wf-move-7","p":0,"s":"\"transfer\" กับ \"transport\" ต่างกันที่รากใด?","gap":0,"o":{"A":"ไม่มีรากเหมือนกันเลย","B":"fer (นำ) / port (ขน) ความหมายใกล้กัน","C":"ทั้งสองไม่มีราก","D":"trans- ต่างกัน"},"oth":{},"a":"B","x":"ทั้งสองขึ้นต้น trans- (ข้าม) ส่วนรากหลังคือ fer และ port","v":[]},{"id":"wf-move-8","p":0,"s":"คำใดมีราก fer (นำ / ขน)?","gap":0,"o":{"A":"forgive","B":"referral","C":"transporter","D":"cigarette"},"oth":{},"a":"B","x":"referral = re- + fer + -al","v":[]},{"id":"wf-move-9","p":0,"s":"คำใดมีราก mit / miss (ส่ง / ปล่อย)?","gap":0,"o":{"A":"movement","B":"projection","C":"baggage","D":"submit"},"oth":{},"a":"D","x":"submit = sub- + mit","v":[]},{"id":"wf-move-10","p":0,"s":"ราก \"duce\" ในคำว่า \"produce\" (ผลผลิต (ผักผลไม้)) แปลว่าอะไร?","gap":0,"o":{"A":"มือ","B":"กด / บีบ","C":"นำ / พาไป","D":"จิตใจ"},"oth":{},"a":"C","x":"produce = pro- + duce ราก duc / duct มาจากละติน ducere แปลว่า นำ / พาไป","v":[]},{"id":"wf-move-11","p":0,"s":"ราก \"tract\" ในคำว่า \"contract\" (สัญญา) แปลว่าอะไร?","gap":0,"o":{"A":"อำพัน → ไฟฟ้า","B":"ดึง / ลาก","C":"เชื่อม","D":"โยน / พุ่ง"},"oth":{},"a":"B","x":"contract = con- + tract ราก tract มาจากละติน trahere แปลว่า ดึง / ลาก","v":[]}],"grp":"Word Families — ครอบครัวคำและรากศัพท์","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">รากชุดนี้เหมือน <b>รถขนส่ง</b> หลายแบบ: port ขน, duc นำทาง, mit ส่งไป, mov เคลื่อน, ced ไป, ven มา, tract ลาก, fer พาไป ต่อกับ prefix ทิศทาง (ex- ออก, im- เข้า, trans- ข้าม, re- กลับ) ได้คำนับร้อย</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>prefix ↓ / ราก →</th><th>port ขน</th><th>duc นำ</th><th>mit ส่ง</th><th>tract ดึง</th><th>fer นำพา</th></tr></thead><tbody><tr><td>ex- ออก</td><td>export</td><td>educe</td><td>emit</td><td>extract</td><td>-</td></tr><tr><td>im- / in- เข้า</td><td>import</td><td>induce</td><td>-</td><td>-</td><td>infer</td></tr><tr><td>trans- ข้าม</td><td>transport</td><td>-</td><td>transmit</td><td>-</td><td>transfer</td></tr><tr><td>re- กลับ</td><td>report</td><td>reduce</td><td>remit</td><td>retract</td><td>refer</td></tr><tr><td>pro- ไปข้างหน้า</td><td>-</td><td>produce</td><td>promise*</td><td>protract</td><td>proffer</td></tr><tr><td>con- / com- ร่วม</td><td>comport</td><td>conduct</td><td>commit</td><td>contract</td><td>confer</td></tr></tbody></table></div><figcaption>prefix ทิศทาง × รากการเคลื่อนที่ (* promise มาจาก pro + mittere)</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ขน / นำ</div><div class=\"tf-value\">port · duc · fer</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ส่ง / เคลื่อน</div><div class=\"tf-value\">mit · mov</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ไป / มา / ดึง</div><div class=\"tf-value\">ced · ven · tract</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>port = ขน / duc, duct = นำ</b> — export, support, report / produce, reduce, conduct, introduce<br><span class=\"bv-rx\">We <b>re</b><b>duce</b> waste. <small>เราลดของเสีย (re + duce = นำกลับ = ลด)</small></span></p><p><b>mit, miss = ส่ง / mov, mot = เคลื่อน</b> — submit, permit, transmit, mission / move, remove, motor, promote<br><span class=\"bv-rx\">Please <b>sub</b><b>mit</b> the report. <small>กรุณาส่งรายงาน</small></span></p><p><b>ced, cess = ไป / ven, vent = มา</b> — process, proceed, access, exceed / event, prevent, convention, adventure<br><span class=\"bv-rx\">The project will <b>pro</b><b>ceed</b>. <small>โครงการจะดำเนินต่อ</small></span></p><p><b>tract = ดึง / fer = นำ ขน</b> — contract, attract, extract / transfer, refer, offer, prefer<br><span class=\"bv-rx\"><b>Trans</b><b>fer</b> the file to the server. <small>โอนไฟล์ไปเซิร์ฟเวอร์</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We need to reduce costs.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We need to reduce costs.</div><div class=\"ex-th thai\">เราต้องลดต้นทุน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The contract was signed yesterday.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The contract was signed yesterday.</div><div class=\"ex-th thai\">สัญญาลงนามเมื่อวาน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please refer to page 5.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please refer to page 5.</div><div class=\"ex-th thai\">กรุณาดูหน้า 5</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Safety glasses prevent eye injuries.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Safety glasses prevent eye injuries.</div><div class=\"ex-th thai\">แว่นนิรภัยป้องกันการบาดเจ็บที่ตา</div></div></div></div><h3 class=\"bv-h\">ระวังความหมาย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ produce = ผลิต จึง product = ผู้ผลิต</p><p class=\"ok\">✓ product = ผลิตภัณฑ์ / producer = ผู้ผลิต</p><small>รากเดียวกันแต่คนละคำ</small></div><div class=\"bv-m\"><p class=\"no\">✗ succeed = ส่งต่อ</p><p class=\"ok\">✓ succeed = ประสบความสำเร็จ / สืบทอด</p><small>sub + ced = ไปตาม เดิมแปลว่าสืบทอด</small></div><div class=\"bv-m\"><p class=\"no\">✗ contract แปลว่า ติดต่อ</p><p class=\"ok\">✓ contract = สัญญา / หดตัว / contact = ติดต่อ</p><small>สะกดใกล้กันแต่คนละคำ</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> เวลาเจอคำธุรกิจยาวๆ ให้หา prefix ทิศทางกับรากการเคลื่อนที่ เช่น proceed = pro (ไปข้างหน้า) + ceed (ไป) = ดำเนินต่อไป</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The supplier submitted a proposal to reduce costs. We transferred the order, and the project can now proceed.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The supplier <mark>sub</mark>mitted a <mark>pro</mark>posal to <mark>re</mark>duce costs. We <mark>trans</mark>ferred the order, and the <mark>pro</mark>ject can now <mark>pro</mark>ceed.</div><div class=\"ts-th\">ผู้จัดหายื่นข้อเสนอเพื่อลดต้นทุน เราโอนคำสั่งซื้อไป และตอนนี้โครงการดำเนินต่อได้</div></div></div></div>","easy":{"say":"รากการเคลื่อนที่: port ขน · duc นำ · mit ส่ง · mov เคลื่อน · ced ไป · ven มา · tract ดึง · fer นำพา ต่อกับ prefix ทิศทาง","eg":["ex + <b>port</b> · re + <b>duce</b> · sub + <b>mit</b>","ส่งออก · ลด · ส่ง (ยื่น)"],"rule":"prefix ทิศทาง + รากการเคลื่อนที่ = คำธุรกิจนับร้อย"}},{"id":"sense","en":"Latin roots of seeing, saying and writing","th":"รากละตินเรื่องการมอง พูด ฟัง เขียน: vis, spec, aud, dict, voc, scrib","intro":"รากของประสาทสัมผัสและการสื่อสาร พบในคำเกี่ยวกับการตรวจ การรายงาน และการประชุม","r":[],"tips":[],"items":[{"id":"wf-sense-0","p":0,"s":"\"inspect\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"พูดเข้าไป","B":"ฟังเข้าไป","C":"มองเข้าไป = ตรวจสอบ","D":"เขียนเข้าไป"},"oth":{},"a":"C","x":"in + spect (มอง)","v":[]},{"id":"wf-sense-1","p":0,"s":"\"audit\" เกี่ยวกับรากใด?","gap":0,"o":{"A":"aud = ฟัง (เดิมคือการฟังรายงานบัญชี)","B":"vis = มอง","C":"scrib = เขียน","D":"dict = พูด"},"oth":{},"a":"A","x":"การตรวจบัญชีสมัยก่อนอ่านออกเสียงให้ผู้ตรวจฟัง","v":[]},{"id":"wf-sense-2","p":0,"s":"\"predict\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"มองก่อน","B":"เขียนก่อน","C":"พูดก่อน = ทำนาย","D":"ฟังก่อน"},"oth":{},"a":"C","x":"pre (ก่อน) + dict (พูด)","v":[]},{"id":"wf-sense-3","p":0,"s":"\"describe\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"ฟังลง","B":"เขียนลง = บรรยาย","C":"มองลง","D":"พูดลง"},"oth":{},"a":"B","x":"de (ลง) + scribe (เขียน)","v":[]},{"id":"wf-sense-4","p":0,"s":"คำใดมีราก \"vis / vid\" (มอง)?","gap":0,"o":{"A":"supply","B":"suppose","C":"support","D":"supervise"},"oth":{},"a":"D","x":"super (เหนือ) + vise (มอง)","v":[]},{"id":"wf-sense-5","p":0,"s":"Please _____ to our newsletter.","gap":1,"o":{"A":"inscribe","B":"describe","C":"subscribe","D":"prescribe"},"oth":{},"a":"C","x":"subscribe = ลงชื่อรับ (sub + scribe = เขียนชื่อไว้ข้างใต้)","v":[]},{"id":"wf-sense-6","p":0,"s":"\"vocabulary\" เกี่ยวกับราก \"voc\" ซึ่งแปลว่าอะไร?","gap":0,"o":{"A":"ฟัง","B":"มอง","C":"เสียง / เรียก","D":"เขียน"},"oth":{},"a":"C","x":"voc = เสียง เรียก (vocabulary = คำที่ใช้เรียกสิ่งต่างๆ)","v":[]},{"id":"wf-sense-7","p":0,"s":"\"evident\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"มองเห็นได้ชัด","B":"ฟังออก","C":"เขียนออกมา","D":"พูดออกมา"},"oth":{},"a":"A","x":"e (ออก) + vid (มอง) + ent = เห็นชัด","v":[]},{"id":"wf-sense-8","p":0,"s":"คำใดมีราก scrib / script (เขียน)?","gap":0,"o":{"A":"sequence","B":"seaside","C":"prescription","D":"implement"},"oth":{},"a":"C","x":"prescription = pre- + script + -ion","v":[]},{"id":"wf-sense-9","p":0,"s":"ราก \"scribe\" ในคำว่า \"transcribe\" (ถอดความ) แปลว่าอะไร?","gap":0,"o":{"A":"กด / บีบ","B":"จบ / ขอบเขต","C":"ยืน / ตั้งอยู่","D":"เขียน"},"oth":{},"a":"D","x":"transcribe = tran- + scribe ราก scrib / script มาจากละติน scribere แปลว่า เขียน","v":[]},{"id":"wf-sense-10","p":0,"s":"ราก \"graph\" ในคำว่า \"autograph\" (เซ็นชื่อ) แปลว่าอะไร?","gap":0,"o":{"A":"นำ / พาไป","B":"ทำ / สร้าง","C":"หัวเราะ","D":"เขียน / วาด"},"oth":{},"a":"D","x":"autograph = auto + graph ราก graph / gram มาจากกรีก graphein แปลว่า เขียน / วาด","v":[]},{"id":"wf-sense-11","p":0,"s":"คำใดมีราก graph / gram (เขียน / วาด)?","gap":0,"o":{"A":"banking","B":"provision","C":"photographic","D":"developer"},"oth":{},"a":"C","x":"photographic = photo + graph + -ic","v":[]}],"grp":"Word Families — ครอบครัวคำและรากศัพท์","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">รากชุดนี้คือ <b>ตา หู ปาก มือ</b> ของภาษา: vis / spec = ตา (มอง), aud = หู (ฟัง), dict / voc = ปาก (พูด), scrib / script = มือ (เขียน) คำเกี่ยวกับการตรวจและรายงานมาจากรากเหล่านี้เกือบทั้งหมด</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ราก</th><th>อวัยวะ</th><th>คำในงาน</th></tr></thead><tbody><tr><td>vis / vid</td><td>👁 มอง</td><td>supervise, review, provide, video</td></tr><tr><td>spec / spect</td><td>👁 มอง</td><td>inspect, inspection, specification, expect</td></tr><tr><td>aud</td><td>👂 ฟัง</td><td>audit, auditor, audio</td></tr><tr><td>dict</td><td>👄 พูด</td><td>predict, dictate, contradict</td></tr><tr><td>voc</td><td>👄 เสียง</td><td>vocal, advocate</td></tr><tr><td>scrib / script</td><td>✍ เขียน</td><td>describe, description, subscribe, script</td></tr></tbody></table></div><figcaption>รากของประสาทสัมผัส</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">มอง</div><div class=\"tf-value\">vis · vid · spec · spect</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ฟัง / พูด</div><div class=\"tf-value\">aud · dict · voc</div></div><div class=\"tense-formula\"><div class=\"tf-label\">เขียน</div><div class=\"tf-value\">scrib · script · graph</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>vis, vid / spec, spect = มอง</b> — vision, visible, video, provide, review / inspect, respect, expect, specify<br><span class=\"bv-rx\">Please <b>re</b><b>view</b> the drawing. <small>กรุณาทบทวนแบบ</small></span></p><p><b>aud = ฟัง</b> — audio, audience, audit, auditorium<br><span class=\"bv-rx\">The <b>aud</b>it is next week. <small>การตรวจประเมินคือสัปดาห์หน้า</small></span></p><p><b>dict = พูด / voc = เสียง เรียก</b> — predict, dictionary, contradict / vocal, advocate, vocabulary<br><span class=\"bv-rx\">Can you <b>pre</b><b>dict</b> the demand? <small>คุณทำนายความต้องการได้ไหม</small></span></p><p><b>scrib, script = เขียน</b> — describe, prescribe, subscribe, script, manuscript<br><span class=\"bv-rx\"><b>De</b><b>scribe</b> the problem. <small>อธิบายปัญหา</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The inspector found three defects.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The inspector found three defects.</div><div class=\"ex-th thai\">ผู้ตรวจพบของเสียสามชิ้น</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The auditor reviewed our records.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The auditor reviewed our records.</div><div class=\"ex-th thai\">ผู้ตรวจประเมินทบทวนบันทึกของเรา</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please describe the failure mode.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please describe the failure mode.</div><div class=\"ex-th thai\">กรุณาอธิบายลักษณะความเสียหาย</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The supervisor will provide training.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The supervisor will provide training.</div><div class=\"ex-th thai\">หัวหน้างานจะจัดการฝึกอบรม</div></div></div></div><h3 class=\"bv-h\">ระวังความหมาย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ specification = การมองพิเศษ</p><p class=\"ok\">✓ specification = ข้อกำหนด</p><small>มาจาก specify (ระบุให้ชัด) ความหมายเปลี่ยนไปแล้ว</small></div><div class=\"bv-m\"><p class=\"no\">✗ audit = การฟังเพลง</p><p class=\"ok\">✓ audit = การตรวจสอบ (บัญชี / ระบบ)</p><small>รากเป็นเบาะแสเชิงประวัติศาสตร์</small></div><div class=\"bv-m\"><p class=\"no\">✗ provide = มองไปข้างหน้า</p><p class=\"ok\">✓ provide = จัดหาให้</p><small>ความหมายเดิม &quot;มองการณ์ไกลแล้วเตรียมไว้&quot; กลายเป็น &quot;จัดหา&quot;</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> คำในงานคุณภาพหลายคำมาจากรากเหล่านี้: inspection (มองเข้าไป) audit (ฟัง) specification (ระบุ) describe (เขียนลง) จำรากแล้วจำคำได้ง่ายขึ้น</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The auditor inspected the line and reviewed our specifications. She described two issues and predicted more if we did not act.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The <mark>auditor</mark> <mark>inspected</mark> the line and <mark>reviewed</mark> our <mark>specifications</mark>. She <mark>described</mark> two issues and <mark>predicted</mark> more if we did not act.</div><div class=\"ts-th\">ผู้ตรวจประเมินตรวจไลน์และทบทวนข้อกำหนดของเรา เธออธิบายปัญหาสองข้อ และคาดว่าจะมีอีกถ้าเราไม่แก้</div></div></div></div>","easy":{"say":"รากชุดนี้คือ ตา หู ปาก มือ: vis/spec มอง · aud ฟัง · dict/voc พูด · scrib/script เขียน","eg":["in + <b>spect</b> · <b>aud</b>it · pre + <b>dict</b> · de + <b>scribe</b>","ตรวจ · ตรวจประเมิน · ทำนาย · บรรยาย"],"rule":"ตา vis/spec · หู aud · ปาก dict/voc · มือ scrib"}},{"id":"make","en":"Latin roots of making and holding","th":"รากละตินเรื่องการทำ วาง ยืน ถือ: fac, struct, form, pos, sta, tain, cap","intro":"รากเหล่านี้เป็นรากที่มีคำในคลังมากที่สุด เพราะการทำ การวาง การถือ เป็นเรื่องพื้นฐานของทุกงาน","r":[],"tips":[],"items":[{"id":"wf-make-0","p":0,"s":"\"manufacture\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"จับด้วยมือ","B":"มองด้วยมือ","C":"เขียนด้วยมือ","D":"ทำด้วยมือ = ผลิต"},"oth":{},"a":"D","x":"manu (มือ) + fac (ทำ) + ture","v":[]},{"id":"wf-make-1","p":0,"s":"\"component\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"สิ่งที่ถือร่วมกัน","B":"สิ่งที่ทำร่วมกัน","C":"สิ่งที่ยืนร่วมกัน","D":"สิ่งที่วางรวมกัน = ชิ้นส่วนประกอบ"},"oth":{},"a":"D","x":"com (ร่วม) + pon (วาง) + ent","v":[]},{"id":"wf-make-2","p":0,"s":"\"maintain\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"ถือไว้ในมือ = รักษา บำรุง","B":"ทำด้วยมือ","C":"ยืนในมือ","D":"วางไว้ในมือ"},"oth":{},"a":"A","x":"main (มือ) + tain (ถือ)","v":[]},{"id":"wf-make-3","p":0,"s":"\"capacity\" เกี่ยวกับรากใด?","gap":0,"o":{"A":"sta = ยืน","B":"cap = จับ รับ (ความจุ = รับได้เท่าไร)","C":"form = รูปร่าง","D":"fac = ทำ"},"oth":{},"a":"B","x":"capacity = ความสามารถในการรับ","v":[]},{"id":"wf-make-4","p":0,"s":"\"stable\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"ยืนได้ = มั่นคง","B":"ทำได้","C":"ถือได้","D":"วางได้"},"oth":{},"a":"A","x":"sta (ยืน) + ble (ได้)","v":[]},{"id":"wf-make-5","p":0,"s":"คำใดมีราก \"struct\" (สร้าง)?","gap":0,"o":{"A":"contraction","B":"construction","C":"conduction","D":"connection"},"oth":{},"a":"B","x":"con + struct + ion = การก่อสร้าง","v":[]},{"id":"wf-make-6","p":0,"s":"\"efficient\" มีราก \"fic\" แปลว่าอะไร?","gap":0,"o":{"A":"ไป","B":"มอง","C":"ทำ","D":"ถือ"},"oth":{},"a":"C","x":"ef (ออก) + fic (ทำ) + ient = ทำออกมาได้ดี = มีประสิทธิภาพ","v":[]},{"id":"wf-make-7","p":0,"s":"The box _____ 12 bottles.","gap":1,"o":{"A":"retains","B":"contains","C":"obtains","D":"maintains"},"oth":{},"a":"B","x":"con (ร่วมกัน) + tain (ถือ) = บรรจุ","v":[]},{"id":"wf-make-8","p":0,"s":"ราก \"stat\" ในคำว่า \"station\" (สถานี) แปลว่าอะไร?","gap":0,"o":{"A":"แน่นอน / แยกแยะ","B":"ยืน / ตั้งอยู่","C":"บ้าน / ปกครอง","D":"ตก / เกิดขึ้น"},"oth":{},"a":"B","x":"station = stat + -ion ราก sta / sist / stit มาจากละติน stare แปลว่า ยืน / ตั้งอยู่","v":[]},{"id":"wf-make-9","p":0,"s":"ราก \"pose\" ในคำว่า \"purpose\" (จุดประสงค์) แปลว่าอะไร?","gap":0,"o":{"A":"เชื่อใจ","B":"ดูแล / ใส่ใจ","C":"มอง / ดู","D":"วาง"},"oth":{},"a":"D","x":"purpose = pur + pose ราก pos / pon มาจากละติน ponere แปลว่า วาง","v":[]},{"id":"wf-make-10","p":0,"s":"ราก \"tain\" ในคำว่า \"contain\" (มี…อยู่ข้างใน) แปลว่าอะไร?","gap":0,"o":{"A":"พูด / บอก","B":"เพาะปลูก / ดูแล","C":"ถือ / เก็บไว้","D":"ดิน / มนุษย์"},"oth":{},"a":"C","x":"contain = con- + tain ราก tain / ten / tin มาจากละติน tenere แปลว่า ถือ / เก็บไว้","v":[]},{"id":"wf-make-11","p":0,"s":"ราก \"struct\" ในคำว่า \"construct\" (สร้าง) แปลว่าอะไร?","gap":0,"o":{"A":"แม่","B":"สร้าง","C":"ยก / เบา","D":"ดวงดาว"},"oth":{},"a":"B","x":"construct = con- + struct ราก struct มาจากละติน struere แปลว่า สร้าง","v":[]}],"grp":"Word Families — ครอบครัวคำและรากศัพท์","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">รากชุดนี้เหมือน <b>เครื่องมือช่าง</b> ในกล่อง: fac ทำ · struct สร้าง · form ขึ้นรูป · pos วาง · sta ตั้ง · tain ถือ · cap จับ คำในโรงงานแทบทุกคำมีรากเหล่านี้ (factory, structure, component, maintenance, capacity)</div><figure class=\"bv bv-parts\"><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">manufacture</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-r\"><b lang=\"en\">manu</b><small>มือ</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">fac</b><small>ทำ</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ture</b><small>การ...</small></span></span><span class=\"wp-th\">การผลิต</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">maintenance</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-r\"><b lang=\"en\">main</b><small>มือ</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">ten</b><small>ถือ</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ance</b><small>การ...</small></span></span><span class=\"wp-th\">การบำรุงรักษา</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">component</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">com</b><small>ร่วม</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">pon</b><small>วาง</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ent</b><small>สิ่ง</small></span></span><span class=\"wp-th\">ชิ้นส่วนประกอบ</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">construction</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">con</b><small>ร่วม</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">struct</b><small>สร้าง</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ion</b><small>การ...</small></span></span><span class=\"wp-th\">การก่อสร้าง</span></div><figcaption>คำในโรงงานแยกเป็นรากที่รู้ความหมาย</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ราก</th><th>ความหมาย</th><th>คำในคลัง</th></tr></thead><tbody><tr><td>fac / fect / fic</td><td>ทำ</td><td>factory, effect, efficient, office, perfect</td></tr><tr><td>struct</td><td>สร้าง</td><td>structure, instruct, construction</td></tr><tr><td>form</td><td>รูปร่าง</td><td>format, inform, transform, uniform</td></tr><tr><td>pos / pon</td><td>วาง</td><td>position, component, propose, deposit</td></tr><tr><td>sta / sist</td><td>ยืน</td><td>status, stable, assist, constant</td></tr><tr><td>tain / ten</td><td>ถือ</td><td>contain, maintain, obtain</td></tr><tr><td>cap / cept / ceive</td><td>จับ / รับ</td><td>capacity, accept, receive</td></tr></tbody></table></div><figcaption>รากที่มีคำในคลังมากที่สุด</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ทำ / สร้าง</div><div class=\"tf-value\">fac · struct · form</div></div><div class=\"tense-formula\"><div class=\"tf-label\">วาง / ยืน</div><div class=\"tf-value\">pos · pon · sta · sist</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ถือ / จับ</div><div class=\"tf-value\">tain · ten · cap · cept</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>fac, fact, fect, fic = ทำ</b> — factory, manufacture, effect, perfect, efficient, office<br><span class=\"bv-rx\">The <b>fact</b>ory runs 24 hours. <small>โรงงานเดิน 24 ชั่วโมง</small></span></p><p><b>struct = สร้าง / form = รูปร่าง</b> — structure, construction, instruct / format, inform, transform, uniform<br><span class=\"bv-rx\">Follow the <b>in</b><b>struct</b>ions. <small>ทำตามคำแนะนำ</small></span></p><p><b>pos, pon = วาง / sta, sist = ยืน</b> — position, propose, component, deposit / status, stable, assist, constant, establish<br><span class=\"bv-rx\">Each <b>com</b><b>pon</b>ent is tested. <small>ทุกชิ้นส่วนได้รับการทดสอบ</small></span></p><p><b>tain, ten = ถือ / cap, cept = จับ รับ</b> — contain, maintain, obtain, retain / capture, accept, receive, capacity<br><span class=\"bv-rx\">We <b>main</b><b>tain</b> the machines monthly. <small>เราบำรุงรักษาเครื่องทุกเดือน</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The factory produces 10,000 units a day.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The factory produces 10,000 units a day.</div><div class=\"ex-th thai\">โรงงานผลิตวันละ 10,000 ชิ้น</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Each component has a part number.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Each component has a part number.</div><div class=\"ex-th thai\">ทุกชิ้นส่วนมีหมายเลขชิ้นส่วน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Maintenance is scheduled for Sunday.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Maintenance is scheduled for Sunday.</div><div class=\"ex-th thai\">การบำรุงรักษากำหนดไว้วันอาทิตย์</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We accept credit cards.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We accept credit cards.</div><div class=\"ex-th thai\">เรารับบัตรเครดิต</div></div></div></div><h3 class=\"bv-h\">ระวังความหมาย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ except = รับ</p><p class=\"ok\">✓ except = ยกเว้น / accept = รับ</p><small>ex (ออก) + cept (จับ) = หยิบออก = ยกเว้น</small></div><div class=\"bv-m\"><p class=\"no\">✗ affect = effect</p><p class=\"ok\">✓ affect (v.) = มีผลต่อ / effect (n.) = ผล</p><small>รากเดียวกัน แต่หน้าที่ต่างกัน</small></div><div class=\"bv-m\"><p class=\"no\">✗ maintain = main + tain = ถือหลัก</p><p class=\"ok\">✓ main ในที่นี้ = มือ (ฝรั่งเศส main)</p><small>ไม่ใช่ main ที่แปลว่า &quot;หลัก&quot;</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> affect กับ effect ออกสอบบ่อย: The heat &lt;b&gt;affects&lt;/b&gt; (v.) the parts. / The heat has an &lt;b&gt;effect&lt;/b&gt; (n.) on the parts.</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The factory maintains a stable production capacity. Every component is inspected before assembly.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The <mark>factory</mark> <mark>maintains</mark> a <mark>stable</mark> <mark>production</mark> <mark>capacity</mark>. Every <mark>component</mark> is <mark>inspected</mark> before <mark>assembly</mark>.</div><div class=\"ts-th\">โรงงานรักษากำลังการผลิตให้คงที่ ทุกชิ้นส่วนได้รับการตรวจก่อนประกอบ</div></div></div></div>","easy":{"say":"รากที่เจอบ่อยที่สุดคือเครื่องมือช่าง: fac ทำ · struct สร้าง · form รูปร่าง · pos วาง · sta ยืน · tain ถือ · cap จับ","eg":["<b>manu</b> + <b>fac</b> + ture = manufacture","มือ + ทำ = การผลิต"],"rule":"คำในโรงงานส่วนใหญ่มาจากรากเหล่านี้"}},{"id":"numroot","en":"Roots for numbers and size","th":"รากบอกจำนวนและขนาด: cent, mill, ann, prim, equ, magn, min","intro":"รากตัวเลขและขนาดอยู่ในคำบอกปริมาณ เวลา และการเปรียบเทียบที่ใช้ในรายงาน","r":[],"tips":[],"items":[{"id":"wf-numroot-0","p":0,"s":"\"annual\" แปลว่าอะไร?","gap":0,"o":{"A":"ร้อยปี","B":"พันปี","C":"ประจำปี","D":"ประจำเดือน"},"oth":{},"a":"C","x":"ann = ปี","v":[]},{"id":"wf-numroot-1","p":0,"s":"\"percent\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"ต่อหนึ่ง","B":"ต่อร้อย","C":"ต่อพัน","D":"ต่อปี"},"oth":{},"a":"B","x":"per (ต่อ) + cent (ร้อย)","v":[]},{"id":"wf-numroot-2","p":0,"s":"\"majority\" แปลว่าอะไร?","gap":0,"o":{"A":"หัวหน้า","B":"ส่วนน้อย","C":"ส่วนใหญ่","D":"ตรงกลาง"},"oth":{},"a":"C","x":"maj (ใหญ่) + or + ity","v":[]},{"id":"wf-numroot-3","p":0,"s":"ตรงข้ามของ \"maximum\" คือคำใด?","gap":0,"o":{"A":"medium","B":"minimum","C":"minor","D":"majority"},"oth":{},"a":"B","x":"max ใหญ่ที่สุด / min เล็กที่สุด","v":[]},{"id":"wf-numroot-4","p":0,"s":"\"equivalent\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"มีค่าเท่ากัน","B":"เล็กกว่า","C":"ใหญ่กว่า","D":"มาก่อน"},"oth":{},"a":"A","x":"equi (เท่ากัน) + val (ค่า) + ent","v":[]},{"id":"wf-numroot-5","p":0,"s":"\"primary\" แปลว่าอะไร?","gap":0,"o":{"A":"สุดท้าย","B":"รอง","C":"ทุกปี","D":"หลัก / อันดับแรก"},"oth":{},"a":"D","x":"prim = แรก","v":[]},{"id":"wf-numroot-6","p":0,"s":"1 millimeter = ? meter","gap":0,"o":{"A":"100","B":"0.001","C":"1,000","D":"0.01"},"oth":{},"a":"B","x":"mill(i) = หนึ่งในพัน","v":[]},{"id":"wf-numroot-7","p":0,"s":"\"century\" คือกี่ปี?","gap":0,"o":{"A":"100 ปี","B":"10 ปี","C":"1 ปี","D":"1,000 ปี"},"oth":{},"a":"A","x":"cent = ร้อย","v":[]},{"id":"wf-numroot-8","p":0,"s":"ราก \"maj\" ในคำว่า \"major\" (สำคัญ) แปลว่าอะไร?","gap":0,"o":{"A":"แรก / สำคัญที่สุด","B":"ล้อ / หมุน","C":"เต็ม","D":"ใหญ่"},"oth":{},"a":"D","x":"major = maj + -or ราก magn / maj / max มาจากละติน magnus แปลว่า ใหญ่","v":[]},{"id":"wf-numroot-9","p":0,"s":"ราก \"centu\" ในคำว่า \"century\" (ศตวรรษ) แปลว่าอะไร?","gap":0,"o":{"A":"หัวเราะ","B":"ต่อ / ใส่","C":"ร้อย","D":"เกาะ"},"oth":{},"a":"C","x":"century = centu + -ry ราก cent มาจากละติน centum แปลว่า ร้อย","v":[]},{"id":"wf-numroot-10","p":0,"s":"คำใดมีราก prim / prin (แรก / สำคัญที่สุด)?","gap":0,"o":{"A":"association","B":"principle","C":"biology","D":"workshop"},"oth":{},"a":"B","x":"principle = prin + ciple","v":[]}],"grp":"Word Families — ครอบครัวคำและรากศัพท์","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">รากชุดนี้เหมือน \"<b>ไม้บรรทัด</b>\" ของภาษา ใช้วัดจำนวน (cent ร้อย, mill พัน) เวลา (ann ปี) ลำดับ (prim แรก) และขนาด (magn ใหญ่, min เล็ก) เวลาอ่านรายงานตัวเลข รากเหล่านี้โผล่มาทุกหน้า</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ราก</th><th>ความหมาย</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>cent</td><td>ร้อย</td><td>percent, century, centimeter</td></tr><tr><td>mill</td><td>พัน</td><td>million, millimeter, millennium</td></tr><tr><td>ann / enn</td><td>ปี</td><td>annual, anniversary, biennial</td></tr><tr><td>prim / prin</td><td>แรก / หลัก</td><td>primary, prime, principle</td></tr><tr><td>equ</td><td>เท่ากัน</td><td>equal, equivalent, adequate</td></tr><tr><td>magn / maj / max</td><td>ใหญ่</td><td>major, majority, maximum</td></tr><tr><td>min</td><td>เล็ก</td><td>minor, minimum, minority</td></tr></tbody></table></div><figcaption>รากตัวเลขและขนาด</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">จำนวน</div><div class=\"tf-value\">cent 100 · mill 1,000</div></div><div class=\"tense-formula\"><div class=\"tf-label\">เวลา</div><div class=\"tf-value\">ann = ปี</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ขนาด</div><div class=\"tf-value\">max ใหญ่สุด ↔ min เล็กสุด</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>cent = ร้อย / mill = พัน</b> — percent, century, centimeter / million, millimeter, millennium<br><span class=\"bv-rx\">Sales rose 5 <b>per</b><b>cent</b>. <small>ยอดขายเพิ่ม 5 เปอร์เซ็นต์ (ต่อร้อย)</small></span></p><p><b>ann, enn = ปี</b> — annual, anniversary, annually, biennial<br><span class=\"bv-rx\">the <b>ann</b>ual report <small>รายงานประจำปี</small></span></p><p><b>prim, prin = แรก / equ = เท่ากัน</b> — primary, prime, principle / equal, equivalent, adequate<br><span class=\"bv-rx\"><b>Equ</b>al pay for equal work. <small>ค่าจ้างเท่ากันสำหรับงานเท่ากัน</small></span></p><p><b>magn, maj, max = ใหญ่ / min = เล็ก</b> — major, majority, maximum, magnify / minor, minimum, minute (เล็กมาก), minister<br><span class=\"bv-rx\">the <b>max</b>imum load <small>น้ำหนักบรรทุกสูงสุด</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The annual meeting is in March.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The annual meeting is in March.</div><div class=\"ex-th thai\">การประชุมประจำปีคือเดือนมีนาคม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The maximum temperature is 85 °C.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The maximum temperature is 85 °C.</div><div class=\"ex-th thai\">อุณหภูมิสูงสุดคือ 85 องศาเซลเซียส</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The majority of staff agreed.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The majority of staff agreed.</div><div class=\"ex-th thai\">พนักงานส่วนใหญ่เห็นด้วย</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Our primary goal is safety.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Our primary goal is safety.</div><div class=\"ex-th thai\">เป้าหมายหลักของเราคือความปลอดภัย</div></div></div></div><h3 class=\"bv-h\">ระวังความหมาย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ equipment มาจาก equ (เท่ากัน)</p><p class=\"ok\">✓ equipment มาจาก equip (จัดเตรียมเรือ) ไม่เกี่ยวกับ equ</p><small>ตัวอักษรเหมือนกันไม่ได้แปลว่ารากเดียวกัน</small></div><div class=\"bv-m\"><p class=\"no\">✗ minute (นาที) กับ minute (เล็กมาก) คนละราก</p><p class=\"ok\">✓ ทั้งสองมาจาก min (เล็ก)</p><small>นาที = ส่วนเล็กๆ ของชั่วโมง (ออกเสียงต่างกัน MIN-it / my-NYOOT)</small></div><div class=\"bv-m\"><p class=\"no\">✗ per cent = ต่อพัน</p><p class=\"ok\">✓ per cent = ต่อร้อย</p><small>cent = ร้อย</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ในรายงานภาษาอังกฤษ ใช้ &quot;the majority of + พหูพจน์&quot; และ &quot;a minimum of + ตัวเลข&quot; เช่น a minimum of 3 samples</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"In the annual report, the majority of products met the minimum standard. Sales rose 12 percent, the maximum in a century of history.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">In the <mark>annual</mark> report, the <mark>majority</mark> of products met the <mark>minimum</mark> standard. Sales rose 12 <mark>percent</mark>, the <mark>maximum</mark> in a <mark>century</mark> of history.</div><div class=\"ts-th\">ในรายงานประจำปี ผลิตภัณฑ์ส่วนใหญ่ผ่านมาตรฐานขั้นต่ำ ยอดขายเพิ่ม 12 เปอร์เซ็นต์ สูงที่สุดในประวัติศาสตร์ร้อยปี</div></div></div></div>","easy":{"say":"รากไม้บรรทัด: cent ร้อย · mill พัน · ann ปี · prim แรก · equ เท่ากัน · max/magn ใหญ่ · min เล็ก","eg":["per + <b>cent</b> · <b>ann</b>ual · <b>max</b>imum","ต่อร้อย · ประจำปี · สูงสุด"],"rule":"ตัวเลขและขนาดในรายงานมาจากรากเหล่านี้"}},{"id":"techroot","en":"Roots in technical English","th":"รากศัพท์ในงานเทคนิค: electr, mechan, therm, hydr, press, flex, rupt, junct","intro":"รากเหล่านี้อยู่ในคำวิศวกรรม ไฟฟ้า และเครื่องกล รู้ราก อ่านคู่มือและ spec ได้เร็วขึ้นมาก","r":[],"tips":[],"items":[{"id":"wf-techroot-0","p":0,"s":"ราก \"electr\" มาจากคำกรีกที่แปลว่าอะไร?","gap":0,"o":{"A":"อำพัน (ที่ถูแล้วเกิดไฟฟ้าสถิต)","B":"ฟ้าผ่า","C":"แม่เหล็ก","D":"ทองแดง"},"oth":{},"a":"A","x":"ชาวกรีกพบว่าถูอำพัน (elektron) แล้วดูดเศษฝุ่นได้","v":[]},{"id":"wf-techroot-1","p":0,"s":"\"thermal\" เกี่ยวกับอะไร?","gap":0,"o":{"A":"แรงดัน","B":"ความร้อน","C":"ไฟฟ้า","D":"น้ำ"},"oth":{},"a":"B","x":"therm = ร้อน","v":[]},{"id":"wf-techroot-2","p":0,"s":"\"hydraulic press\" ใช้แรงจากอะไร?","gap":0,"o":{"A":"ลม","B":"ของเหลว","C":"แสง","D":"ไฟฟ้า"},"oth":{},"a":"B","x":"hydr = น้ำ / ของเหลว","v":[]},{"id":"wf-techroot-3","p":0,"s":"\"compress\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"กดรวมกัน = อัด","B":"งอรวมกัน","C":"แตกรวมกัน","D":"เชื่อมรวมกัน"},"oth":{},"a":"A","x":"com (ร่วม) + press (กด)","v":[]},{"id":"wf-techroot-4","p":0,"s":"\"interrupt\" แปลตามรากว่าอะไร?","gap":0,"o":{"A":"แตกตรงกลาง = ขัดจังหวะ","B":"งอตรงกลาง","C":"เชื่อมตรงกลาง","D":"กดตรงกลาง"},"oth":{},"a":"A","x":"inter (ระหว่าง) + rupt (แตก)","v":[]},{"id":"wf-techroot-5","p":0,"s":"\"flexible\" แปลว่าอะไร?","gap":0,"o":{"A":"กดได้","B":"แตกง่าย","C":"งอได้ / ยืดหยุ่น","D":"ร้อนได้"},"oth":{},"a":"C","x":"flex (งอ) + ible (ได้)","v":[]},{"id":"wf-techroot-6","p":0,"s":"จุดที่สายไฟหลายเส้นต่อกันเรียกว่าอะไร?","gap":0,"o":{"A":"reflection","B":"function","C":"junction","D":"pressure"},"oth":{},"a":"C","x":"junct = เชื่อม","v":[]},{"id":"wf-techroot-7","p":0,"s":"\"mechanism\" แปลว่าอะไร?","gap":0,"o":{"A":"กลไก","B":"ช่างเครื่อง","C":"เครื่องวัด","D":"ไฟฟ้า"},"oth":{},"a":"A","x":"mechan (เครื่องจักร) + ism","v":[]},{"id":"wf-techroot-8","p":0,"s":"ราก \"press\" ในคำว่า \"pressure\" (ความดัน) แปลว่าอะไร?","gap":0,"o":{"A":"แตก / หัก","B":"หนัก","C":"ตัด / แบ่ง","D":"กด / บีบ"},"oth":{},"a":"D","x":"pressure = press + -ure ราก press มาจากละติน premere แปลว่า กด / บีบ","v":[]},{"id":"wf-techroot-9","p":0,"s":"ราก \"press\" ในคำว่า \"impressive\" (น่าประทับใจ) แปลว่าอะไร?","gap":0,"o":{"A":"หัวใจ","B":"เป็นพยาน / ยืนยัน","C":"แรก / สำคัญที่สุด","D":"กด / บีบ"},"oth":{},"a":"D","x":"impressive = im- + press + -ive ราก press มาจากละติน premere แปลว่า กด / บีบ","v":[]},{"id":"wf-techroot-10","p":0,"s":"ราก \"metre\" ในคำว่า \"kilometre\" (กิโลเมตร) แปลว่าอะไร?","gap":0,"o":{"A":"กด / บีบ","B":"วัด","C":"ทดสอบ / พิสูจน์","D":"เคลื่อนที่"},"oth":{},"a":"B","x":"kilometre = kilo- + metre ราก meter / metr มาจากกรีก metron แปลว่า วัด","v":[]}],"grp":"Word Families — ครอบครัวคำและรากศัพท์","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">สำหรับคนทำงานโรงงานอิเล็กทรอนิกส์ รากชุดนี้คือ \"<b>ภาษาเครื่อง</b>\": electr ไฟฟ้า · mechan เครื่องกล · therm ร้อน · hydr ของเหลว · press กด · flex งอ · rupt แตก · junct เชื่อม เจอในคู่มือ spec และรายงานทุกวัน</div><figure class=\"bv bv-parts\"><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">electrician</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-r\"><b lang=\"en\">electr</b><small>ไฟฟ้า</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ic</b><small>เกี่ยวกับ</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">ian</b><small>ผู้...</small></span></span><span class=\"wp-th\">ช่างไฟฟ้า</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">thermostat</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-r\"><b lang=\"en\">thermo</b><small>ร้อน</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">stat</b><small>ยืน / คงที่</small></span></span><span class=\"wp-th\">อุปกรณ์รักษาอุณหภูมิให้คงที่</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">interrupt</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">inter</b><small>ระหว่าง</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">rupt</b><small>แตก</small></span></span><span class=\"wp-th\">ขัดจังหวะ</span></div><div class=\"wp-row\"><b class=\"wp-w\" lang=\"en\">compressor</b><span class=\"wp-eq\">=</span><span class=\"wp-chips\"><span class=\"wp wp-p\"><b lang=\"en\">com</b><small>ร่วม</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-r\"><b lang=\"en\">press</b><small>กด</small></span><i class=\"wp-plus\">+</i><span class=\"wp wp-s\"><b lang=\"en\">or</b><small>สิ่งที่...</small></span></span><span class=\"wp-th\">เครื่องอัด</span></div><figcaption>คำเทคนิคแยกเป็นส่วนที่เข้าใจได้</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ราก</th><th>ความหมาย</th><th>คำในงาน</th></tr></thead><tbody><tr><td>electr</td><td>ไฟฟ้า</td><td>electrical, electronic, electrode</td></tr><tr><td>mechan / machin</td><td>เครื่องจักร</td><td>mechanical, mechanism, machinery</td></tr><tr><td>therm</td><td>ร้อน</td><td>thermal, thermometer, thermostat</td></tr><tr><td>hydr</td><td>ของเหลว</td><td>hydraulic, dehydrate</td></tr><tr><td>press</td><td>กด</td><td>pressure, compress, compressor</td></tr><tr><td>flex / flect</td><td>งอ</td><td>flexible, reflect</td></tr><tr><td>rupt</td><td>แตก</td><td>interrupt, disrupt, rupture</td></tr><tr><td>junct / join</td><td>เชื่อม</td><td>junction, joint</td></tr></tbody></table></div><figcaption>รากในงานเทคนิค</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ไฟฟ้า / เครื่องกล</div><div class=\"tf-value\">electr · mechan</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ร้อน / ของเหลว / แรงดัน</div><div class=\"tf-value\">therm · hydr · press</div></div><div class=\"tense-formula\"><div class=\"tf-label\">งอ / แตก / เชื่อม</div><div class=\"tf-value\">flex · rupt · junct</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>electr = ไฟฟ้า (จากคำกรีก &quot;อำพัน&quot;)</b> — electric, electrical, electronic, electrician, electrode<br><span class=\"bv-rx\">Static <b>electr</b>icity can damage chips. <small>ไฟฟ้าสถิตทำให้ชิปเสียหายได้</small></span></p><p><b>mechan / machin = เครื่องจักร / therm = ร้อน / hydr = น้ำ</b> — mechanic, mechanism, machinery / thermal, thermostat / hydraulic, dehydrate<br><span class=\"bv-rx\">a <b>therm</b>al sensor <small>เซนเซอร์ความร้อน</small></span></p><p><b>press = กด / flex, flect = งอ / rupt = แตก</b> — pressure, compress / flexible, reflect / interrupt, disrupt, rupture<br><span class=\"bv-rx\">Do not <b>inter</b><b>rupt</b> the test. <small>อย่าขัดจังหวะการทดสอบ</small></span></p><p><b>junct / join = เชื่อม / meter = วัด / volt, watt = ชื่อคน</b> — junction, joint / thermometer, multimeter / volt (Volta), watt (Watt)<br><span class=\"bv-rx\">Check the <b>junct</b>ion box. <small>ตรวจกล่องต่อสาย</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Wear an ESD strap to prevent static electricity.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Wear an ESD strap to prevent static electricity.</div><div class=\"ex-th thai\">ใส่สายรัดข้อมือกันไฟฟ้าสถิต</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Check the pressure gauge before starting.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Check the pressure gauge before starting.</div><div class=\"ex-th thai\">ตรวจเกจวัดแรงดันก่อนเริ่ม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The flexible cable bends easily.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The flexible cable bends easily.</div><div class=\"ex-th thai\">สายแบบยืดหยุ่นงอได้ง่าย</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"A power interruption stopped the line.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">A power interruption stopped the line.</div><div class=\"ex-th thai\">ไฟดับชั่วขณะทำให้ไลน์หยุด</div></div></div></div><h3 class=\"bv-h\">ระวังการใช้คำ</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ electric engineer</p><p class=\"ok\">✓ electrical engineer</p><small>ตำแหน่งงานใช้ electrical</small></div><div class=\"bv-m\"><p class=\"no\">✗ a mechanic problem</p><p class=\"ok\">✓ a mechanical problem</p><small>คน = mechanic / adj. = mechanical</small></div><div class=\"bv-m\"><p class=\"no\">✗ pressure = การกด (ด้วยนิ้ว)</p><p class=\"ok\">✓ pressure = แรงดัน / ความกดดัน</p><small>ในงานเทคนิคใช้ pressure = แรงดัน (bar, psi)</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> หน่วยไฟฟ้าหลายหน่วยตั้งตามชื่อนักวิทยาศาสตร์: volt (Volta), ampere (Ampère), watt (Watt), ohm (Ohm) เขียนชื่อหน่วยตัวพิมพ์เล็ก แต่สัญลักษณ์ใช้ตัวพิมพ์ใหญ่ (V, A, W, Ω)</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The electrician found a loose joint in the junction box. The interruption caused a pressure drop in the hydraulic system.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The <mark>electrician</mark> found a loose <mark>joint</mark> in the <mark>junction</mark> box. The <mark>interruption</mark> caused a <mark>pressure</mark> drop in the <mark>hydraulic</mark> system.</div><div class=\"ts-th\">ช่างไฟพบจุดต่อหลวมในกล่องต่อสาย ไฟที่ขาดช่วงทำให้แรงดันในระบบไฮดรอลิกตก</div></div></div></div>","easy":{"say":"รากงานเทคนิค: electr ไฟฟ้า · mechan เครื่องจักร · therm ร้อน · hydr ของเหลว · press กด · flex งอ · rupt แตก · junct เชื่อม","eg":["inter + <b>rupt</b> · com + <b>press</b> · <b>therm</b>al","ขัดจังหวะ · อัด · ทางความร้อน"],"rule":"คู่มือและ spec ใช้รากเหล่านี้ทุกหน้า"}},{"id":"guess","en":"Guessing meaning from parts and context","th":"เดาความหมายจากส่วนประกอบและบริบท","intro":"เมื่อเจอคำที่ไม่รู้ ใช้สองเครื่องมือร่วมกัน: ส่วนประกอบของคำ (prefix, root, suffix) และบริบทรอบคำ","r":[],"tips":[],"items":[{"id":"wf-guess-0","p":0,"s":"\"The material is nonflammable, so it is safe near fire.\" nonflammable แปลว่าอะไร?","gap":0,"o":{"A":"ติดไฟง่าย","B":"ละลายง่าย","C":"ระเบิดได้","D":"ไม่ติดไฟ"},"oth":{},"a":"D","x":"non- (ไม่) + flammable (ติดไฟได้) และบริบท \"safe near fire\" ยืนยัน","v":[]},{"id":"wf-guess-1","p":0,"s":"\"The new process is irreversible; we cannot go back.\" irreversible แปลว่าอะไร?","gap":0,"o":{"A":"ย้อนกลับได้","B":"หมุนได้","C":"ทำซ้ำได้","D":"ย้อนกลับไม่ได้"},"oth":{},"a":"D","x":"ir- (ไม่) + revers(e) (ย้อน) + -ible (ได้)","v":[]},{"id":"wf-guess-2","p":0,"s":"คำใดเป็น \"คำลวง\" ที่แยกส่วนแบบตัวอักษรแล้วได้ความหมายผิด?","gap":0,"o":{"A":"carpet","B":"rewrite","C":"teacher","D":"unhappy"},"oth":{},"a":"A","x":"carpet (พรม) ไม่ได้มาจาก car + pet","v":[]},{"id":"wf-guess-3","p":0,"s":"\"The supplier is renowned for quality.\" renowned น่าจะเป็นคำชนิดใด?","gap":0,"o":{"A":"adjective","B":"preposition","C":"adverb","D":"verb"},"oth":{},"a":"A","x":"is + __ + for → adjective (renowned = มีชื่อเสียง)","v":[]},{"id":"wf-guess-4","p":0,"s":"\"Please preheat the oven; then bake for 20 minutes.\" preheat แปลว่าอะไร?","gap":0,"o":{"A":"ไม่อุ่น","B":"อุ่นก่อน","C":"อุ่นมากเกิน","D":"อุ่นซ้ำ"},"oth":{},"a":"B","x":"pre- = ก่อน และบริบทบอกลำดับ \"then bake\"","v":[]},{"id":"wf-guess-5","p":0,"s":"เมื่อความหมายจากรากขัดกับบริบท ควรเชื่ออะไร?","gap":0,"o":{"A":"เสียง","B":"ตัวสะกด","C":"ราก","D":"บริบท"},"oth":{},"a":"D","x":"ความหมายของคำเปลี่ยนไปตามเวลา บริบทบอกความหมายปัจจุบัน","v":[]},{"id":"wf-guess-6","p":0,"s":"\"The results were inconclusive, so we will test again.\" inconclusive แปลว่าอะไร?","gap":0,"o":{"A":"ยังสรุปไม่ได้","B":"รวมอยู่ด้วย","C":"ถูกตัดออก","D":"สรุปได้ชัดเจน"},"oth":{},"a":"A","x":"in- (ไม่) + conclus (สรุป) + -ive และบริบท \"test again\"","v":[]},{"id":"wf-guess-7","p":0,"s":"\"discuss\" แยกเป็น dis- + cuss ได้ไหม?","gap":0,"o":{"A":"ได้ แปลว่า ไม่คุย","B":"ไม่ได้ ใช้ทั้งคำ (dis เป็นส่วนของรากละติน discutere)","C":"ได้ แปลว่า แยกด่า","D":"ได้ แปลว่า ไม่ด่า"},"oth":{},"a":"B","x":"การแยก dis + cuss ไม่ได้ความหมาย จึงต้องจำทั้งคำ","v":[]}],"grp":"Word Families — ครอบครัวคำและรากศัพท์","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">การเดาความหมายเหมือน <b>นักสืบ</b>: ส่วนประกอบของคำคือ \"รอยนิ้วมือ\" บริบทคือ \"พยาน\" ใช้แค่รอยนิ้วมืออาจจับผิดคน ต้องมีพยานยืนยันด้วยเสมอ</div><figure class=\"bv bv-steps\"><ol><li>ดูตำแหน่งและ suffix → รู้ชนิดของคำ</li><li>แยก prefix / root / suffix ที่รู้จัก</li><li>เดาความหมายคร่าวๆ</li><li>อ่านคำรอบข้างและคำเชื่อมเพื่อยืนยัน</li><li>ถ้าขัดกัน เชื่อบริบท แล้วเปิดพจนานุกรม</li></ol><figcaption>ห้าขั้นของนักสืบคำศัพท์</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>คำลวง</th><th>ดูเหมือน</th><th>จริงๆ</th></tr></thead><tbody><tr><td>carpet</td><td>car + pet</td><td>พรม (คำเดียว)</td></tr><tr><td>sport</td><td>s + port (ขน)</td><td>กีฬา (จาก disport)</td></tr><tr><td>discuss</td><td>dis + cuss</td><td>อภิปราย (จากละติน)</td></tr><tr><td>season</td><td>sea + son</td><td>ฤดู (คำเดียว)</td></tr><tr><td>inflammable</td><td>ไม่ + ติดไฟ</td><td>ติดไฟง่าย!</td></tr></tbody></table></div><figcaption>คำเหล่านี้แยกตามตัวอักษรแล้วผิด</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">รอยนิ้วมือ</div><div class=\"tf-value\">prefix + root + suffix</div></div><div class=\"tense-formula\"><div class=\"tf-label\">พยาน</div><div class=\"tf-value\">คำรอบข้าง / คำเชื่อม / ตัวอย่าง</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ถ้าขัดกัน</div><div class=\"tf-value\">เชื่อบริบท</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>ขั้นที่ 1: ดูชนิดของคำจากตำแหน่งและ suffix</b> — รู้ชนิดก่อน แคบคำตอบลงครึ่งหนึ่ง</p><p><b>ขั้นที่ 2: แยกส่วนที่รู้จัก</b> — prefix บอกทิศทาง/ปฏิเสธ root บอกเรื่อง suffix บอกชนิด<br><span class=\"bv-rx\">un + avoid + able → unavoidable <small>หลีกเลี่ยงไม่ได้</small></span></p><p><b>ขั้นที่ 3: ใช้บริบทยืนยัน</b> — ดูคำรอบข้าง คำเชื่อม (but, because) ตัวอย่าง หรือคำอธิบายในประโยค<br><span class=\"bv-rx\">The delay was <b>unavoidable</b> because the port was closed. <small>ความล่าช้าหลีกเลี่ยงไม่ได้เพราะท่าเรือปิด</small></span></p><p><b>ระวังคำลวง (false friends)</b> — บางคำดูเหมือนแยกได้ แต่ไม่ใช่ เช่น sport (ไม่ใช่ s + port), carpet (ไม่ใช่ car + pet), discuss (ไม่ใช่ dis + cuss)</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The noise was unbearable.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The noise was unbearable.</div><div class=\"ex-th thai\">เสียงดังจนทนไม่ได้</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The data is unreliable, so we cannot use it.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The data is unreliable, so we cannot use it.</div><div class=\"ex-th thai\">ข้อมูลเชื่อถือไม่ได้ เราจึงใช้ไม่ได้</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The cable is detachable.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The cable is detachable.</div><div class=\"ex-th thai\">สายถอดออกได้</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"This step is mandatory; you must do it.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">This step is mandatory; you must do it.</div><div class=\"ex-th thai\">ขั้นตอนนี้บังคับ ต้องทำ</div></div></div></div><h3 class=\"bv-h\">กับดักที่ต้องระวัง</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ inflammable = ไม่ติดไฟ</p><p class=\"ok\">✓ inflammable = ติดไฟง่าย</p><small>อันตรายมากถ้าเดาผิด ต้องตรวจเสมอ</small></div><div class=\"bv-m\"><p class=\"no\">✗ priceless = ไม่มีราคา (ถูก)</p><p class=\"ok\">✓ priceless = ล้ำค่าจนตีราคาไม่ได้</p><small>บริบทช่วยบอกว่าเป็นทางบวก</small></div><div class=\"bv-m\"><p class=\"no\">✗ ใช้รากอย่างเดียว ไม่อ่านประโยค</p><p class=\"ok\">✓ ใช้รากร่วมกับบริบท</p><small>รากเป็นเบาะแส ไม่ใช่คำตอบสุดท้าย</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ในข้อสอบ Part 7 มีคำถาม &quot;The word X in paragraph 2 is closest in meaning to&quot; ให้แยกส่วนคำก่อน แล้วอ่านประโยครอบๆ เพื่อเลือกคำที่ความหมายเข้ากับบริบท</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The delay was unavoidable because the road was closed. The data from that day is unreliable, so the result is inconclusive.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The delay was <mark>unavoidable</mark> because the road was closed. The data from that day is <mark>unreliable</mark>, so the result is <mark>inconclusive</mark>.</div><div class=\"ts-th\">ความล่าช้าหลีกเลี่ยงไม่ได้เพราะถนนปิด ข้อมูลของวันนั้นเชื่อถือไม่ได้ ผลจึงยังสรุปไม่ได้</div></div></div></div>","easy":{"say":"เดาคำใหม่แบบนักสืบ: แยกส่วนคำ (รอยนิ้วมือ) แล้วอ่านประโยครอบๆ (พยาน) ถ้าขัดกัน เชื่อบริบท","eg":["un + avoid + able = <b>unavoidable</b> + \"because the road was closed\"","หลีกเลี่ยงไม่ได้"],"rule":"ส่วนประกอบ + บริบท = ความหมาย"}},{"id":"famprac","en":"Word family practice","th":"ฝึกเลือกรูปคำในครอบครัวเดียวกัน","intro":"บทนี้รวมแบบฝึกเลือกรูปคำจากครอบครัวเดียวกันในประโยคงานจริง ใช้ทุกอย่างที่เรียนมา: ตำแหน่ง suffix และความหมาย","r":[],"tips":[],"items":[{"id":"wf-famprac-0","p":0,"s":"The _____ of the new system took two days.","gap":1,"o":{"A":"installer","B":"install","C":"installed","D":"installation"},"oth":{},"a":"D","x":"The ___ of → noun ที่หมายถึงการกระทำ: installation","v":[]},{"id":"wf-famprac-1","p":0,"s":"Ms. Ito gave a very _____ presentation.","gap":1,"o":{"A":"informative","B":"inform","C":"informatively","D":"information"},"oth":{},"a":"A","x":"a very ___ noun → adjective","v":[]},{"id":"wf-famprac-2","p":0,"s":"The parts were _____ packed to avoid damage.","gap":1,"o":{"A":"care","B":"carefulness","C":"carefully","D":"careful"},"oth":{},"a":"C","x":"were ___ packed → adverb","v":[]},{"id":"wf-famprac-3","p":0,"s":"We will _____ the report by Monday.","gap":1,"o":{"A":"final","B":"finalize","C":"finally","D":"finality"},"oth":{},"a":"B","x":"will ___ → verb: finalize (final + -ize)","v":[]},{"id":"wf-famprac-4","p":0,"s":"Our _____ will contact you next week.","gap":1,"o":{"A":"representative","B":"representation","C":"represented","D":"represent"},"oth":{},"a":"A","x":"Our ___ will contact → คน: representative","v":[]},{"id":"wf-famprac-5","p":0,"s":"There has been a significant _____ in sales.","gap":1,"o":{"A":"increased","B":"increase","C":"increasing","D":"increasingly"},"oth":{},"a":"B","x":"a significant ___ → noun: increase","v":[]},{"id":"wf-famprac-6","p":0,"s":"The new procedure is more _____ than the old one.","gap":1,"o":{"A":"efficient","B":"efficiency","C":"efficientness","D":"efficiently"},"oth":{},"a":"A","x":"is more ___ than → adjective","v":[]},{"id":"wf-famprac-7","p":0,"s":"Please contact our technical _____ team.","gap":1,"o":{"A":"supportive","B":"support","C":"supportively","D":"supporter"},"oth":{},"a":"B","x":"technical support team (noun ขยาย noun)","v":[]},{"id":"wf-famprac-8","p":0,"s":"ในครอบครัวคำ \"similar\" คำใดเป็น adjective (คำคุณศัพท์)?","gap":0,"o":{"A":"similarity","B":"similar","C":"apartment","D":"similarly"},"oth":{},"a":"B","x":"similar (คล้ายกัน) เป็น adjective (คำคุณศัพท์)","v":[]},{"id":"wf-famprac-9","p":0,"s":"ในครอบครัวคำ \"write\" คำใดเป็น noun (คำนาม)?","gap":0,"o":{"A":"again","B":"written","C":"writer","D":"write"},"oth":{},"a":"C","x":"writer (นักเขียน) เป็น noun (คำนาม)","v":[]},{"id":"wf-famprac-10","p":0,"s":"ในครอบครัวคำ \"offend\" คำใดเป็น adjective (คำคุณศัพท์)?","gap":0,"o":{"A":"offence","B":"offend","C":"threaten","D":"offensive"},"oth":{},"a":"D","x":"offensive (หยาบคาย) เป็น adjective (คำคุณศัพท์)","v":[]},{"id":"wf-famprac-11","p":0,"s":"ในครอบครัวคำ \"proper\" คำใดเป็น adjective (คำคุณศัพท์)?","gap":0,"o":{"A":"behave","B":"properly","C":"property","D":"proper"},"oth":{},"a":"D","x":"proper (เหมาะสม) เป็น adjective (คำคุณศัพท์)","v":[]}],"grp":"Word Families — ครอบครัวคำและรากศัพท์","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">บทนี้คือ <b>สนามซ้อม</b> ก่อนแข่งจริง ทุกข้อเป็นประโยคที่ใช้ในอีเมลและรายงานงานจริง ฝึกให้มองตำแหน่งก่อนแปล จนกลายเป็นนิสัย</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ตำแหน่ง</th><th>ชนิด</th><th>ตัวอย่างจากแบบฝึก</th></tr></thead><tbody><tr><td>The ___ of</td><td>noun</td><td>The installation of</td></tr><tr><td>a very ___ noun</td><td>adjective</td><td>a very informative presentation</td></tr><tr><td>were ___ V3</td><td>adverb</td><td>were carefully packed</td></tr><tr><td>will ___</td><td>verb</td><td>will finalize</td></tr><tr><td>Our ___ will</td><td>noun (คน)</td><td>Our representative will</td></tr><tr><td>more ___ than</td><td>adjective</td><td>more efficient than</td></tr></tbody></table></div><figcaption>สรุปตำแหน่งที่ใช้ในบทนี้</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ดูตำแหน่ง</div><div class=\"tf-value\">คำหน้าและหลังช่อง</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ดู suffix</div><div class=\"tf-value\">เลือกชนิดที่ตรง</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ดูความหมาย</div><div class=\"tf-value\">คน กับ สิ่ง</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>ทวนกฎตำแหน่ง</b> — the ___ of → noun · a ___ noun → adj · be ___ → adj · ___ verb / verb ___ → adv · to / will ___ → verb</p><p><b>ทวน suffix</b> — noun -tion -ment -ance -ity · adj -ive -able -ful -al · adv -ly · verb -ize -ify -en</p><p><b>คน กับ สิ่ง</b> — -er / -or / -ant / -ee = คน · -tion / -ance / -ment = สิ่ง การกระทำ<br><span class=\"bv-rx\">consultant (ที่ปรึกษา) / consultation (การปรึกษา)</span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Our representative will call you.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Our representative will call you.</div><div class=\"ex-th thai\">ตัวแทนของเราจะโทรหาคุณ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The installation was completed on time.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The installation was completed on time.</div><div class=\"ex-th thai\">การติดตั้งเสร็จตรงเวลา</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We finalized the contract yesterday.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We finalized the contract yesterday.</div><div class=\"ex-th thai\">เราสรุปสัญญาเมื่อวาน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The new layout is more efficient.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The new layout is more efficient.</div><div class=\"ex-th thai\">ผังใหม่มีประสิทธิภาพกว่า</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ a significant increasingly</p><p class=\"ok\">✓ a significant increase</p><small>หลัง a + adj ต้องเป็น noun</small></div><div class=\"bv-m\"><p class=\"no\">✗ more efficiency than</p><p class=\"ok\">✓ more efficient than</p><small>more ___ than ใช้ adjective</small></div><div class=\"bv-m\"><p class=\"no\">✗ Our representation will call you.</p><p class=\"ok\">✓ Our representative will call you.</p><small>คนที่โทรได้คือ representative</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ฝึกต่อได้ที่ &quot;แผนผังรากศัพท์&quot; และ &quot;สุ่มข้อสอบจริง&quot; Part 5 ซึ่งมีข้อ word form จำนวนมาก</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"After the installation, our representative gave an informative demonstration. The new system works efficiently, and sales showed a clear increase.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">After the <mark>installation</mark>, our <mark>representative</mark> gave an <mark>informative</mark> <mark>demonstration</mark>. The new system works <mark>efficiently</mark>, and sales showed a clear <mark>increase</mark>.</div><div class=\"ts-th\">หลังการติดตั้ง ตัวแทนของเราสาธิตการใช้งานได้ละเอียด ระบบใหม่ทำงานอย่างมีประสิทธิภาพ และยอดขายเพิ่มขึ้นชัดเจน</div></div></div></div>","easy":{"say":"ทวนทั้งหมดในบทเดียว: ดูตำแหน่ง → รู้ชนิด → เลือกจาก suffix → ถ้าเหลือสองตัว ดูว่าเป็นคนหรือสิ่ง","eg":["Our <b>representative</b> will call. / the <b>installation</b> of",""],"rule":"ตำแหน่ง → ชนิด → suffix → ความหมาย"}}]};
